(window.GAMES = window.GAMES || {})[2003] = [{"t":".hack//Infection Part 1","p":["PlayStation 2"],"r":"February 10","l":"https://en.wikipedia.org/wiki/.hack//INFECTION"},{"t":"1080° Avalanche","p":["GameCube"],"r":"December 1","l":"https://en.wikipedia.org/wiki/1080%C2%B0_Avalanche"},{"t":"1893: A World's Fair Mystery","p":["Windows"],"d":"Peter Nepstad","u":"The Illuminated Lantern","g":"Interactive fiction","r":"April 24, 2003","l":"https://en.wikipedia.org/wiki/1893:_A_World's_Fair_Mystery","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/avfimrmq5cpfo58ehgjy.jpg","s":"1893 is an interactive fiction game that is accompanied by photography. The game explores Chicago's seedy history of crime; in this case, theft and kidnapping."},{"t":"A Tale in the Desert","p":["Windows","Linux","macOS"],"u":"Desert Nomad Studios","g":"MMORPG","l":"https://en.wikipedia.org/wiki/A_Tale_in_the_Desert","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2yqg.jpg","s":"A Tale in the Desert is a Massive Multiplayer Online Roleplaying Game (MMO), presented by Desert Nomad Studios, and set in ancient Egypt.\n\nThe game focuses on crafting and trading, mixed with strong social and political challenges, and has absolutely no combat.\n\nWithin the game is one of the most complex crafting and trade skill systems that have ever been created. This is coupled with tests in various disciplines that challenge players to work together or against each other. Be creative in the arts or build massive structures, create complex thought puzzles to challenge other players.\n\nThe game is a great sociological experiment, asking questions like \"Will players work together in a project when working against each other could potentially have more benefit to one of them?\"."},{"t":"Active Lancer","p":["macOS"],"d":"Freeverse","u":"Freeverse","g":"Shoot Em Up","r":"October 20, 2003","l":"https://en.wikipedia.org/wiki/Active_Lancer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc2ly.jpg","s":"Join Lancer Squad, an elite unit of flight-capable troops, on their current mission to battle an extraterrestrial army set on taking control the universe's evil war machine. Active Lancer confronts you (and a companion if necessary) against waves of alien spacecraft, tanks, boats, and gun turrets over 15 stages of increasing difficulty. It's straight-up arcade shooter action with vertical scrolling.\n\nIt has fifteen levels of vertical scrolling shooting, five hope-shattering monsters, three upgradeable weapon kinds, each with their own sort of charge shot, three distinct pilots, each with their unique strengths, and two-player action over a network or on a single machine."},{"t":"Advance Wars 2: Black Hole Rising","p":["Game Boy Advance"],"u":"Nintendo","r":"June 24, 2003"},{"t":"After...","p":["Windows","Dreamcast","PlayStation 2"],"d":"Ciel","u":"Ciel, Pionesoft","g":"Visual novel, eroge","r":"June 27, 2003","l":"https://en.wikipedia.org/wiki/After..._(video_game)"},{"t":"Age of Mythology: The Titans","p":["Windows"],"d":"Ensemble Studios","u":"Microsoft Game Studios","g":"Real-time strategy","r":"September 30, 2003","l":"https://en.wikipedia.org/wiki/Age_of_Mythology:_The_Titans"},{"t":"Age of Wanderer","p":["Windows"],"d":"Joymax","u":"OSC","g":"Beat 'em up","r":"January 27, 2003","l":"https://en.wikipedia.org/wiki/Age_of_Wanderer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2c7g.jpg","s":"Based on the blockbuster SBS drama series, Joymax brings back the exciting action of the acclaimed TV series with the arcade game Age of Wanderer."},{"t":"Age of Wonders: Shadow Magic","p":["Windows"],"d":"Triumph Studios","u":"Gathering","g":"Turn-based strategy","r":"July 24, 2003","l":"https://en.wikipedia.org/wiki/Age_of_Wonders:_Shadow_Magic","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xog.jpg","s":"Age of Wonders: Shadow Magic is the third entry in the award winning fantasy strategy series. This fan-favorite enhances the series' praised fusion of empire building, role-playing and tactical combat with the eerie Shadow World and battle with races never before seen, across new and diverse landscapes.\n\nCombined with the option of creating a totally unique environment with the map generator and rewriting the history of this world through the enhanced campaign editor, you are ensured a constant stream of completely new game experiences."},{"t":"AGON","p":["Windows","macOS"],"d":"Private Moon Studios","g":"Adventure","l":"https://en.wikipedia.org/wiki/AGON"},{"t":"Airborne Assault: Highway to the Reich","p":["Windows"],"d":"Panther Games","u":"Matrix Games","g":"FPS","r":"July 2003","l":"https://en.wikipedia.org/wiki/Airborne_Assault:_Highway_to_the_Reich"},{"t":"Airport Tycoon 2","p":["Windows"],"u":"Global Star Software","r":"February 26, 2003","l":"https://en.wikipedia.org/wiki/Airport_Tycoon"},{"t":"Akiba Girls","p":[],"l":"https://en.wikipedia.org/wiki/Akiba_Girls"},{"t":"Alien Shooter","p":["Windows"],"d":"Sigma Team","u":"Sigma Team","g":"Top-down shooter","r":"May 18, 2003","l":"https://en.wikipedia.org/wiki/Alien_Shooter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3gum.jpg","s":"Alien Shooter is an top-down shooter video game from Sigma Team created in 2003. It is the first title in the Alien Shooter series to be followed by Alien Shooter: Vengeance. Alien Shooter has two expansions, Fight for Life and The Experiment. They each contain five new levels, including the conclusion to the alien shooter story."},{"t":"Aliens Versus Predator: Extinction","p":["PlayStation 2","Xbox"],"d":"Zono","u":"Electronic Arts, Fox Interactive","g":"Real-time strategy","r":"July 30, 2003","l":"https://en.wikipedia.org/wiki/Aliens_Versus_Predator:_Extinction","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9fon.jpg","s":"Aliens Versus Predator: Extinction is a real-time strategy game featuring three different species, all vying for control of the planet LV-742. Players can command an elite force of Colonial Marines, stalk their prey as a member of the Predator clan, or scurry along in packs as the acid-spitting Aliens. Gameplay involves advancing through a series of missions ranging in locale from jungles and caverns to futuristic battlefields and space colonies. Each faction offers ten types of combat units that can be upgraded over time with new attributes or equipment specific to the species. Predators, for instance, increase their number of vision modes, Aliens impregnate their victims with facehuggers, while Colonial Marines receive new weapon enhancements. As in titles like StarCraft, units range in scope from standard grunts and infantry to specialized forces and massive troop transports."},{"t":"All Star Racing 2","p":["PlayStation"],"d":"Kung Fu Games","u":"Mud Duck Productions, Midas Interactive Entertainment","g":"Racing","r":"February 7, 2003","l":"https://en.wikipedia.org/wiki/All_Star_Racing_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ruoldczcqb3xmqoohn9t.jpg","s":"Mud Duck Productions' follow up title to 2002's All Star Racing changes focus from classic, stock and super cars to Truck, Kart, Grand Prix (open wheel) and Motorbike racing. Each type of vehicle in All Star Racing 2 features changeable color schemes and five tracks, and players can select from multiple viewpoints and three levels of difficulty. Five race lengths are offered (user's choice), beginning with three-lap sprints and increasing by increments of three, culminating in 15-lap endurance contests. \n \nAll Star Racing 2 is Mud Duck Productions' follow up title to the 2002 title, All Star Racing. While the first game focuses on stock, classic and super cars, this title features open wheel, truck, sport bike, and kart racing."},{"t":"All-Star Baseball 2004","p":["GameCube","Xbox","PlayStation 2","Game Boy Advance"],"d":"Acclaim Studios Austin, Acclaim Studios Manchester","u":"Acclaim Entertainment","g":"Sports","r":"February 28, 2003","l":"https://en.wikipedia.org/wiki/All-Star_Baseball_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6dlj.jpg","s":"The 2004 installment in Acclaim's long-running baseball series. The game features more than 80 new features and improvements, including a deeper, more customizable franchise mode. The biggest change comes in the interface. You still hit the same buttons to swing, bunt, steal, and field, but the batting cursor has been visually altered. It's still the same triangle shape as before, just with a different outline. Bunting is more unique, though. Instead of aiming the cursor when you go to bunt, a large arrow points on the ground. Aim your bunt in the desired direction and hope for the best. Fielding has also received a slight change, with the ball cursor changing color. Four up to four players."},{"t":"Alter Echo","p":["PlayStation 2","Xbox"],"r":"August 19","l":"https://en.wikipedia.org/wiki/Alter_Echo"},{"t":"America's 10 Most Wanted","p":["Windows","PlayStation 2"],"r":"November 18","l":"https://en.wikipedia.org/wiki/America%27s_10_Most_Wanted"},{"t":"American Idol","p":["Windows","Game Boy Advance"],"u":"Codemasters","r":"November 7, 2003","l":"https://en.wikipedia.org/wiki/American_Idol_(video_game)"},{"t":"AMF Bowling 2004","p":["Xbox"],"d":"Black Market Games","u":"Mud Duck Productions","g":"Bowling","r":"December 1, 2003","l":"https://en.wikipedia.org/wiki/AMF_Bowling_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/x7vizmmwva0rewpteyoy.jpg","s":"Bowling fans can appreciate AMF Bowling 2004's realistic sound effects, array of gameplay options, and accurate ball, pin, and lane physics. This bowling simulation also lets you create your own bowler and customize your ball's weight, color, and texture. In multiple gameplay modes, such as practice and tournament play, you can find that perfect combination of position, speed, and ball velocity. Showcase your skills against professional bowlers or against a friend."},{"t":"Amped 2","p":["Xbox"],"r":"October 28","l":"https://en.wikipedia.org/wiki/Amped_2"},{"t":"Amplitude","p":["PlayStation 2"],"r":"March 24","l":"https://en.wikipedia.org/wiki/Amplitude_(game)"},{"t":"Anarchy Online: The Shadowlands","p":["Windows"],"r":"September 8","l":"https://en.wikipedia.org/wiki/Anarchy_Online#The_Shadowlands"},{"t":"Angel's Feather","p":["Windows"],"g":"Role-playing (RPG), Visual Novel","l":"https://en.wikipedia.org/wiki/Angel's_Feather","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7y5r.jpg","s":"Angel's Feather is a Japanese boys' love visual novel game created by BlueImpact, which was originally released on April 25, 2003 for PC, and later ported to the PlayStation 2 by KID. It was adapted into an OVA, which was animated by Studio Venet. The game's character designer is Yamamoto Kazue. In 2007, Media Blasters licensed the anime for Region 1 release."},{"t":"Anito: Defend a Land Enraged","p":["Windows"],"d":"Anino Entertainment","u":"Anino Entertainment","g":"Adventure, role-playing","r":"November 20, 2003","l":"https://en.wikipedia.org/wiki/Anito:_Defend_a_Land_Enraged","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9epg.jpg","s":"Anito is a Single-Player Isometric Adventure RPG game by Anino Entertainment, an independent video game company based in the Philippines, set in 16th century Asia, in the land of Maroka. Maroka is an island besieged both by internal conflict and armored invaders from a faraway land who are slowly turning Maroka into their monarch's colony. When Datu Maktan, leader of the Mangatiwala tribe and the land's most influential peacemaker, mysteriously disappears, it is up to his children Agila and Maya to find him and restore the delicate peace that their father has kept in balance, before conlicting forces tear the land apart."},{"t":"Ape Escape 2","p":["PlayStation 2"],"r":"June 30","l":"https://en.wikipedia.org/wiki/Ape_Escape_2"},{"t":"Apocalyptica","p":["Windows"],"d":"Extreme FX","u":"Konami","g":"Third-person shooter","r":"October 24, 2003","l":"https://en.wikipedia.org/wiki/Apocalyptica_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ty4.jpg","s":"The forces of good and evil collide in this third-person gothic science fiction shooter.\n\nThe single-player mode lets players select one of 16 characters and lead a team of holy avengers against the forces of Neo-Satan. Characters are skill rated and armed with guns, swords, and spells. Although the teammates and opponents are bots, each of the 18 levels is an objective based mission typical of multiplayer FPS games (rescue hostages, deliver packages, etc...). The player and bots re-spawn an unlimited number of times until the level objective is completed or failed. The forces of evil usually have a numerical advantage including a team of character type bots (comparable to the player's team) and an additional horde of mindless minions."},{"t":"Apprentice","p":["Windows"],"d":"Herculean Effort Productions","u":"Herculean Effort Productions","g":"Point-and-click adventure","r":"July 10, 2003","l":"https://en.wikipedia.org/wiki/Apprentice_(video_game)"},{"t":"Aquaman: Battle for Atlantis","p":["GameCube","Xbox"],"u":"TDK Mediactive","r":"July 23, 2003"},{"t":"Arc the Lad: Twilight of the Spirits","p":["PlayStation 2"],"r":"June 25"},{"t":"Armed and Dangerous","p":["Windows","Xbox"],"r":"December 2","l":"https://en.wikipedia.org/wiki/Armed_and_Dangerous_(video_game)"},{"t":"Ashen Empires","p":["Windows"],"d":"Doug Gesler, David Reese, Jeremy Mappus, Bill Money, Denis Loubet","u":"Pixel Mine, Iron Will Games, Asylumsoft Inc., TKO Software","g":"Massively multiplayer online role-playing game","r":"March 10, 2003","l":"https://en.wikipedia.org/wiki/Ashen_Empires","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5855.jpg","s":"Ashen Empires is a classic MMORPG set in the fantasy world of Dransik. Dransik has been besieged by the sinister forces of Talazar, preying on mortals. Play with your friends, battle your foes, complete quests, defeat powerful bosses, pursue tradeskills in a player-driven market. Play YOUR way!"},{"t":"Asterix & Obelix: Kick Buttix","p":["PlayStation 2"],"r":"September 14","l":"https://en.wikipedia.org/wiki/Asterix_%26_Obelix_XXL"},{"t":"Atari Anthology","p":["Windows"],"d":"Digital Eclipse","u":"Atari, Inc.","g":"Various","r":"November 14, 2003","l":"https://en.wikipedia.org/wiki/Atari_Anthology"},{"t":"Atlantis Underwater Tycoon","p":["Windows"],"d":"Anarchy Enterprises","u":"Activision Value","g":"City-building, construction and management, business simulation","r":"March 21, 2003","l":"https://en.wikipedia.org/wiki/Atlantis_Underwater_Tycoon"},{"t":"ATV: Quad Power Racing 2","p":["PlayStation 2","GameCube","Xbox"],"d":"Climax Brighton","u":"Acclaim Entertainment","g":"Racing","r":"January 14, 2003","l":"https://en.wikipedia.org/wiki/ATV:_Quad_Power_Racing_2"},{"t":"Avalon no Kagi","p":["Arcade"],"d":"Hitmaker","u":"Sega","g":"Board game, digital collectible card game","l":"https://en.wikipedia.org/wiki/Avalon_no_Kagi","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8h1v.jpg","s":"Avalon no Kagi, alternatively known as The Key of Avalon is an arcade game developed by Hitmaker and published by Sega on the Triforce arcade board. It is the third card arcade game by Sega. It is a combination of sugoroku style board game and combat trading card game.\n\nIt was often compared to Culdcept, and is able to be played by multiple players at once, using a free in and free out method where other players can drop in and drop out of a match at any time. The cabinet reads a deck of up to 30 cards.\n\nSega Logistics Service announced it would end service on the machines on March 31, 2017."},{"t":"Backyard Baseball 2005","p":["GameCube","Windows"],"d":"Humongous Entertainment","u":"Infogrames/Atari","g":"Sports","r":"April 2, 2003","l":"https://en.wikipedia.org/wiki/Backyard_Baseball_2005","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7qyv.jpg"},{"t":"Backyard Wrestling: Don't Try This at Home","p":["PlayStation 2"],"r":"October 7"},{"t":"Banjo-Kazooie: Grunty's Revenge","p":["Game Boy Advance"],"r":"September 10"},{"t":"Bass Landing","p":["PlayStation"],"d":"Tose","u":"ASCII Entertainment, Agetec","g":"Sports","l":"https://en.wikipedia.org/wiki/Bass_Landing"},{"t":"Batman: Dark Tomorrow","p":["Xbox","GameCube"],"u":"Kemco","r":"March 18, 2003"},{"t":"Batman: Rise of Sin Tzu","p":["Xbox","PlayStation 2","Game Boy Advance","GameCube"],"d":"Ubi Soft Montreal","u":"Ubi Soft","g":"Action, beat 'em up","r":"October 16, 2003","l":"https://en.wikipedia.org/wiki/Batman:_Rise_of_Sin_Tzu","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dyt.jpg","s":"Batman: Rise of Sin Tzu is a 2003 beat 'em up video game released for the Xbox, PlayStation 2, Game Boy Advance and GameCube consoles. It was developed and published by Ubisoft in conjunction with Warner Bros. Interactive Entertainment and DC Comics. It is based on the television series The New Batman Adventures and is a sequel to the game Batman: Vengeance"},{"t":"Battle Engine Aquila","p":["PlayStation 2","Xbox"],"r":"January 20","l":"https://en.wikipedia.org/wiki/Battle_Engine_Aquila"},{"t":"Battlefield 1942: Secret Weapons of WWII","p":["Windows"],"r":"September 4","l":"https://en.wikipedia.org/wiki/Battlefield_1942#Expansion_packs"},{"t":"Battlefield 1942: The Road to Rome","p":["Windows"],"d":"DICE","u":"EA Games","g":"First-person shooter","r":"February 4, 2003","l":"https://en.wikipedia.org/wiki/Battlefield_1942:_The_Road_to_Rome"},{"t":"Battlestar Galactica","p":["Xbox","PlayStation 2"],"d":"Warthog Games","u":"Universal Interactive","g":"Space combat simulator","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/Battlestar_Galactica_(2003_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa3y7.jpg","s":"The war between man and machine rages on as the mechanical Cylons return to wipe out the human race. Begin your heroic journey through the Battlestar Galactica universe as the fearless, young Adama, and help lead the fleet of Colonials to survival. Choose from a wide array of ships, from sleek Vipers to heavy Bombers, and engage various classes of Cylon vessels, including Raiders and Marauders."},{"t":"Beatmania IIDX 9th Style","p":["Arcade"],"d":"Konami, Konami Computer Entertainment Studio","u":"Konami","g":"Music","r":"June 25, 2003","l":"https://en.wikipedia.org/wiki/Beatmania_IIDX_9th_Style","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2j3n.jpg","s":"Beatmania IIDX 9th style is one of the many titles in Konami's IIDX rhythm game series, featuring more than 80 tracks, primarily from the arcade version of the same title. As usual for the beatmania series, the player is given seven piano keys and a turntable, and must play along with the notes that scroll down the screen to play the music. 9th style features a completely revamped interface compared to the previous titles, owing to the more powerful hardware that the arcade version ran on.\n\nThere are three main modes: Arcade mode tasks the player with completing several tracks in succession, Free mode lets the player freely play any unlocked song, and Training mode lets the player practice parts of songs without danger of failure. The Beginner's mode from 5th style and the Class mode from 7th style are also present, as is the gallery mode."},{"t":"Beats of Rage","p":["Windows"],"d":"Senile Team","g":"Beat 'em up","r":"November 2003","l":"https://en.wikipedia.org/wiki/Beats_of_Rage","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ah7.jpg","s":"Beats of Rage is a customisable video game engine made by Senile Team and inspired by Sega's classic Streets of Rage series. With Beats of Rage, users can create their own beat 'em up games - no programming experience required!\nBeats of Rage was first released for DOS in November 2003. It was not advertised in any way other than by word of mouth, yet it soon gained enormous popularity. Ports to many other systems (e.g. Dreamcast, Linux, Windows, GP32, GP2X, etc) soon followed."},{"t":"Beyond Good & Evil","p":["Xbox","GameCube","PlayStation 2","Windows"],"u":"Ubisoft","r":"December 2, 2003","l":"https://en.wikipedia.org/wiki/Beyond_Good_%26_Evil_(video_game)"},{"t":"Big Biz Tycoon! 2","p":["Windows"],"d":"4HEAD Studios","u":"Activision Value","g":"Business simulation game","r":"June 12, 2003","l":"https://en.wikipedia.org/wiki/Big_Biz_Tycoon!_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/oszjzbocfwfirnuvrwxt.jpg"},{"t":"Big Rigs: Over the Road Racing","p":["Windows"],"u":"GameMill Publishing","g":"Action, Adventure, Racing","r":"November 20, 2003","l":"https://store.steampowered.com/app/3598130","i":"images/steam-3598130.jpg","s":"Get ready for some brake jamm'in, CB talk'in, convoy roll'in action across America! From Portland Oregon to Miami Florida, you'll be hauling loads and trying to stay one step ahead of the law as you climb into your Big Rig for non-stop driving action."},{"t":"Billy Hatcher and the Giant Egg","p":["GameCube"],"d":"Sonic Team","u":"Sega","g":"Platform","r":"September 23, 2003","l":"https://en.wikipedia.org/wiki/Billy_Hatcher_and_the_Giant_Egg","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26dv.jpg","s":"Darkness has fallen upon a once-magical land. An evil King who seeks to rule with an everlasting night has captured the creatures that inhabit this realm. Now, a young boy must use the powers of a legendary suit to control special eggs in order to restore light to the land.\n\nGamers will collect magical eggs, use them to solve puzzles and nurture them with items found while exploring the world. Gamers will be able to hatch the eggs and discover magical creatures with a variety of skills, introducing a strategic planning element to the combat and puzzles.\n\nPlayers will explore massive, colourful environments, each with their own missions and secrets, and then defeat the evil boss of each stage. It's up to Billy Hatcher to return light to the land."},{"t":"Bionicle","p":["GameCube","Game Boy Advance","PlayStation 2","Xbox","Windows"],"d":"Argonaut Games, Argonaut Sheffield, Möbius Entertainment","u":"Electronic Arts, Lego Interactive, THQ, Feral Interactive","g":"Platform","r":"September 9, 2003","l":"https://en.wikipedia.org/wiki/Bionicle_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pk3.jpg","s":"Bionicle: The Game (also known as Lego Bionicle and titled on the cover as simply Bionicle) is an action-adventure video game released in 2003. The game is based on parts of the movie Bionicle: Mask of Light and other parts of the Bionicle storyline. Initially, the game was supposed to make each Toa, Toa Nuva, and the Toa of Light playable, but due to deadlines, much of the game was dropped. However, all of the characters are playable in the Game Boy Advance version. The Mac OS X version of the game was released by Feral Interactive."},{"t":"Black & Bruised","p":["GameCube","PlayStation 2"],"r":"January 26","l":"https://en.wikipedia.org/wiki/Black_%26_Bruised"},{"t":"Black Stone: Magic & Steel","p":["Xbox"],"d":"XPEC Entertainment","u":"Xicat Interactive, Idea Factory","g":"Action role-playing","r":"March 13, 2003","l":"https://en.wikipedia.org/wiki/Black_Stone:_Magic_&_Steel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9u5c.jpg","s":"Black Stone: Magic & Steel, known in Japan as Ex-Chaser (エクスチェイサー?), is a role-playing video game developed by XPEC Entertainment and published by Xicat Interactive for the Xbox. The theme song is \"be with you\" by Chihiro Yonekura"},{"t":"Blitzkrieg","p":["Windows","macOS"],"d":"Nival Interactive","u":"CDV, 1C Company, Virtual Programming","g":"Real-time tactics","r":"March 28, 2003","l":"https://en.wikipedia.org/wiki/Blitzkrieg_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7nkt.jpg","s":"Blitzkrieg is a real-time tactics computer game based on the events of World War II and is the first title in the Blitzkrieg (video game series). The game allows players to assume the role of commanding officer during the battles of World War II that occurred in Europe and North Africa. Each country has its respective historically correct military units. Similar to the Sudden Strike games Blitzkrieg focuses on battles rather than real-time strategy aspects like base building."},{"t":"Bloody Roar 3","p":["GameCube"],"r":"March 19","l":"https://en.wikipedia.org/wiki/Bloody_Roar_3"},{"t":"Bloody Roar 4","p":["PlayStation 2"],"d":"Hudson Soft, Eighting","u":"Hudson Soft","g":"Fighting","r":"November 11, 2003","l":"https://en.wikipedia.org/wiki/Bloody_Roar_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7nn7.jpg","s":"During the XGC (X-Genome Code) Incident one year ago, riots raged over the earth by beasts that did not show the XCG, and all over the country small earthquakes shook the land. The cause was unknown, but as the Crest Incident came to an end and the rioting and earthquakes subsided, people began to claim that all was due to the influence of the Stone Seal. Although the Stone Seal has been locked away, the rioting and earthquakes have returned. This time, the incidents are on a larger scale than those of a year ago. What could be behind it all?\n\nBloody Roar 4 is the last title in the series, and is once again a full-3D fighting game featuring the series' trademark transformation abilities. Unlike previous titles in the series, the beast gauge now acts as its own health bar; if a character's health gauge is depleted, they will automatically transform. The game features 18 playable fighters and a variety of game modes, including standard arcade, versus, time-attack, training, and survival modes. Of special mention is the career mode, in which fighting battles will earn so-called \"DNA points,\" which can be spent on abilities and equipment to customize a character for use in other modes."},{"t":"BlowOut","p":["GameCube","Xbox"],"r":"November 26","l":"https://en.wikipedia.org/wiki/BlowOut"},{"t":"Blue-Sky-Blue: Sora o Mau Tsubasa","p":[],"l":"https://en.wikipedia.org/wiki/Blue-Sky-Blue:_Sora_o_Mau_Tsubasa"},{"t":"Bob the Builder: Bob's Castle Adventure","p":["Windows"],"l":"https://en.wikipedia.org/wiki/Bob_the_Builder:_Bob's_Castle_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2uq1.jpg"},{"t":"Boktai: The Sun Is in Your Hand","p":["Game Boy Advance"],"r":"September 16"},{"t":"Bombastic","p":["PlayStation 2"],"r":"August 27","l":"https://en.wikipedia.org/wiki/Bombastic_(video_game)"},{"t":"Bomberman Land 2","p":["PlayStation 2","GameCube"],"d":"Racjin","u":"Hudson Soft","g":"Party","r":"July 17, 2003","l":"https://en.wikipedia.org/wiki/Bomberman_Land_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5u5y.jpg","s":"Bomberman Land 2 is an Action game, developed by Racjin and published by Hudson, which was released in Japan in 2003."},{"t":"Bookworm","p":["Windows","macOS","Game Boy Advance","Mobile phone","Nintendo DS"],"d":"PopCap Games, Black Lantern Studios","u":"PopCap Games","g":"Puzzle","r":"February 25, 2003","l":"https://en.wikipedia.org/wiki/Bookworm_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coas3a.jpg","s":"Assist Lex in creating various words by chaining tiles that touch each other within the grid. The longer your word, the more points you earn, and sometimes you may even discover gem tiles to increase your score! Be wary though, as fire may sometimes threaten to burn your library if you don't stop it in time."},{"t":"Border Down","p":["Arcade","Dreamcast"],"d":"G.rev","u":"G.rev","g":"Scrolling shooter","r":"April 25, 2003","l":"https://en.wikipedia.org/wiki/Border_Down","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23kq.jpg","s":"A futuristic sci-fi shooter in which you play a test pilot strapped to the brand new RAIN combat simulator which allows you to remotely control fighters as they immerse themselves in the midst of enemy territory.\n\nThe game is a side-scrolling shooter in which you control your ship and try to survive the onslaught of enemy attacks while you attempt to clear the levels. Weapon upgrades are based on collectible power-ups, but the game mostly relies on a power bar that fills as you destroy enemies and which allows you to unleash your super weapon at the expense of decreased normal firepower. The game also features a unique \"border\" system which involves three separate routes through each stage. You select the default route at the start of a level and when your ship is destroyed you get knocked down to the next \"border\", which features alternate backgrounds and enemy patterns. Only if you get knocked off the last border you lose the game.\n\nUses completely polygonal graphics and features single player arcade, remix and practice modes through 6 enemy-infested stages, the last of which has four unique variations."},{"t":"Brave Shot","p":["Mobile phone"],"d":"Square Enix","u":"Square Enix","g":"Brave Shot, Scrolling shooter, Brave Shot 2","r":"December 10, 2003","l":"https://en.wikipedia.org/wiki/Brave_Shot"},{"t":"Breakdown","p":["Xbox"],"d":"Namco","u":"Namco, Namco Hometek, Electronic Arts","g":"Action-adventure","l":"https://en.wikipedia.org/wiki/Breakdown_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4af8.jpg","s":"Trapped inside a mysterious laboratory and unable to remember his past, Derrick Cole discovers his extraordinary powers, as he fights for survival against a determined military faction and a legion of seemingly invincible super-human warriors! Breakdown offers an exciting first-person action-adventure gaming experience by combining hand-to-hand combat and state-of-the-art weapons with an intense story line and incredible graphics. Embark on a thrilling and suspenseful search for the truth!"},{"t":"Broken Sword: The Sleeping Dragon","p":["Windows","PlayStation 2","Xbox"],"r":"November 14"},{"t":"Bruce Lee: Return of the Legend","p":["Game Boy Advance"],"d":"Vicarious Visions","u":"Universal Interactive","g":"Beat 'em up","r":"March 21, 2003","l":"https://en.wikipedia.org/wiki/Bruce_Lee:_Return_of_the_Legend","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5wyk.jpg","s":"The legendary Bruce Lee is back as Hai Feng! Master Bruce's fists of fury, nunchaku and dozens of awesome moves as you travel across the globe to locations of mystery and intrigue in this epic martial arts adventure! Use the environment to your advantage, evade your enemies by scaling walls, fight like the Masterwith multiple combo and power-up attacks."},{"t":"Brute Force","p":["Xbox"],"r":"May 27","l":"https://en.wikipedia.org/wiki/Brute_Force_(video_game)"},{"t":"Buffy the Vampire Slayer: Chaos Bleeds","p":["PlayStation 2","Xbox","GameCube"],"r":"August 27"},{"t":"Buffy the Vampire Slayer: Wrath of the Darkhul King","p":["Game Boy Advance"],"r":"June 24"},{"t":"Burnout 2: Point of Impact","p":["GameCube","Xbox"],"u":"Acclaim Entertainment","r":"April 9, 2003"},{"t":"Butt-Ugly Martians: Zoom or Doom","p":["PlayStation 2"],"r":"July 31"},{"t":"C.A.T.: Cyber Attack Team","p":["Xbox"],"d":"Hyde, Medix","u":"Medix","g":"Turn-based tactics","r":"June 26, 2003","l":"https://en.wikipedia.org/wiki/C.A.T.:_Cyber_Attack_Team","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/wi0zojwdg5hj3miiu7o4.jpg","s":"C.A.T.: Cyber Attack Team is an tactical-strategy game for Xbox released exclusively in Japan."},{"t":"Cabela's 4x4 Off-Road Adventure","p":["Windows"],"d":"Fun Labs","u":"Activision Value","g":"Racing","l":"https://en.wikipedia.org/wiki/Cabela's_4x4_Off-Road_Adventure"},{"t":"Cabela's Big Game Hunter: 2004 Season","p":["Windows"],"d":"Sand Grain Studios","u":"Activision Value","g":"Sports","r":"September 2003","l":"https://en.wikipedia.org/wiki/Cabela's_Big_Game_Hunter:_2004_Season"},{"t":"Cabela's Dangerous Hunts","p":["PlayStation 2","Xbox"],"d":"Fun Labs, Sand Grain Studios","u":"Activision Value, Zoo Digital Publishing","g":"Hunting, simulation, first-person shooter","r":"November 11, 2003","l":"https://en.wikipedia.org/wiki/Cabela's_Dangerous_Hunts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8z9e.jpg","s":"Get ready for the next evolution in hunting games! The animals now want to get even. Cabela's Dangerous Hunts delivers intense action in exotic locations through out the globe featuring some of the world's most ferocious animals on the planet! Encounter grizzly bears, rhinos, leopards, cape buffalo and many more, in palm sweaty heart pounding hunting action. You'll soon realize first hand what every hunter fears most with terrifying \"kill or be killed\" hunting action never before released. Test your aim and nerves - hunt over 15 of the most feared animals in 11 exotic locations around the world."},{"t":"Cabela's Deer Hunt: 2004 Season","p":["PlayStation 2","Xbox"],"d":"Sand Grain Studios, Fun Labs","u":"Activision","g":"Sports","r":"August 26, 2003","l":"https://en.wikipedia.org/wiki/Cabela's_Deer_Hunt:_2004_Season","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/l907evtsqxfqeqzxnurf.jpg","s":"Keep your eyes peeled and your trigger finger ready as you never know when a \"Monster Trophy Buck\" will cross your path. In Cabela's Deer Hunt: 2004 Season, you will hunt in nine different deer species using over authentic firearms, gear, and more than 90 unique rack configurations. Get ready to travel to exotic locations via ATV, boat, snowmobile, and truck. With advanced animal AI and true-to-life habits, these deer will have your heart pounding and your palms sweating with intense hunting action."},{"t":"Cabela's GrandSlam Hunting: 2004 Trophies","p":["Windows"],"u":"Activision Value","g":"Sports","l":"https://en.wikipedia.org/wiki/Cabela's_GrandSlam_Hunting:_2004_Trophies","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4zjp.jpg"},{"t":"Cafe Little Wish","p":["Windows","Dreamcast","PlayStation 2"],"d":"Patissier","u":"Digital Works, Princess Soft","g":"Eroge, Visual novel","r":"February 14, 2003","l":"https://en.wikipedia.org/wiki/Cafe_Little_Wish"},{"t":"Cal Ripken's Real Baseball","p":["Windows"],"d":"NCK Tiger Electronic Handheld Studios","u":"Netamin Communication Corporation","g":"Baseball MMOSG","l":"https://en.wikipedia.org/wiki/Cal_Ripken's_Real_Baseball"},{"t":"Call of Duty","p":["Windows"],"u":"Activision","g":"Action","r":"October 29, 2003","l":"https://en.wikipedia.org/wiki/Call_of_Duty_(video_game)","i":"images/steam-1938090.jpg","s":"The Call of Duty® experience supports Modern Warfare® 4, Black Ops 7 and Call of Duty®: Warzone™."},{"t":"Capcom vs. SNK EO","p":["Xbox"],"r":"February 11","l":"https://en.wikipedia.org/wiki/Capcom_vs._SNK_2"},{"t":"Car Tycoon","p":["Windows"],"d":"Vectorcom Development","u":"JoWooD Productions","g":"Business simulation game","r":"January 5, 2003","l":"https://en.wikipedia.org/wiki/Car_Tycoon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/diwnhsmnk3nutvqhkj24.jpg","s":"Car Tycoon is a manager game in which you are the owner of a car company that produces and sells cars. You start in the 1950's in a small town somewhere in the USA. You build a factory, a car shop and a repair facility (most of your money is gone by then) and start to produce cars. By selling them, you'll get money to invent new parts which will then power your new car models. There are up to 3 computer players which want to become rich, too."},{"t":"Care Bears: Care-a-lot Jamboree","p":["Windows","macOS"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Care_Bears:_Care-a-lot_Jamboree","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co85y1.jpg","s":"Care Bears: Care-a-lot Jamboree is an educational game. Includes 10 Care Bears and 8 games."},{"t":"Cartoon Network Speedway","p":["Game Boy Advance"],"d":"DC Studios","u":"Majesco","g":"Racing","r":"November 4, 2003","l":"https://en.wikipedia.org/wiki/Cartoon_Network_Speedway","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5zdp.jpg","s":"All of your favorite Cartoon Network stars are revving their engines to compete for the Speedway Championship! Play as 12 hilarious characters from Courage the Cowardly Dog, Cow and Chicken, Ed, Edd n Eddy, Johnny Bravo and Sheep in the Big City in this fast and fun kart-style racing game."},{"t":"Casino, Inc.","p":["Windows"],"d":"Hothouse Creations","u":"Konami","g":"Business simulation game","r":"March 26, 2003","l":"https://en.wikipedia.org/wiki/Casino,_Inc."},{"t":"Castlevania: Aria of Sorrow","p":["Game Boy Advance"],"u":"Konami","r":"May 6, 2003"},{"t":"Castlevania: Lament of Innocence","p":["PlayStation 2"],"r":"October 21"},{"t":"Celebrity Deathmatch","p":["Windows","PlayStation 2","Xbox"],"u":"Gotham Games","r":"October 14, 2003","l":"https://en.wikipedia.org/wiki/Celebrity_Deathmatch_(video_game)"},{"t":"Championship Manager 4","p":["Windows"],"u":"Eidos Interactive","r":"March 28, 2003","l":"https://en.wikipedia.org/wiki/Championship_Manager_4"},{"t":"Championship Manager: Season 03/04","p":["Windows","macOS"],"d":"Sports Interactive","u":"Eidos Interactive","g":"Sports","r":"November 21, 2003","l":"https://en.wikipedia.org/wiki/Championship_Manager:_Season_03/04"},{"t":"Chaos Legion","p":["Windows","PlayStation 2"],"r":"August 5","l":"https://en.wikipedia.org/wiki/Chaos_Legion"},{"t":"Chariots of War","p":["Windows"],"d":"Slitherine Software, Paradox Interactive","u":"Strategy First, Koch Media, PAN Vision","g":"Computer wargame","r":"June 11, 2003","l":"https://en.wikipedia.org/wiki/Chariots_of_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zrt.jpg","s":"Chariots of War is an operational real-time game where you can play one of 58 different nations on a huge historically accurate and beautiful map covering the entire Middle East! Build up your cities and keep their inhabitants happy."},{"t":"Charlie's Angels","p":["GameCube","PlayStation 2"],"u":"Ubisoft","r":"July 8, 2003","l":"https://en.wikipedia.org/wiki/Charlie%27s_Angels_(video_game)"},{"t":"Charlie's Angels: Angel X","p":["Windows"],"u":"Sony Online Entertainment","r":"June 20, 2003","l":"https://en.wikipedia.org/wiki/Charlie%27s_Angels_(franchise)"},{"t":"Chaser","p":["Windows"],"d":"Cauldron","u":"JoWooD Productions NA:Encore, Inc.","g":"First-person shooter","r":"June 20, 2003","l":"https://en.wikipedia.org/wiki/Chaser_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2b1y.jpg","s":"Chaser is a first-person shooter action video game that takes place in the future, when humanity has inhabited Mars. The gameplay is fast pace, featuring 12 maps that make up the gameplay over four different game modes."},{"t":"Chicago 1930","p":["macOS","Windows"],"d":"Spellbound Entertainment","u":"Wanadoo Edition, MC2-Microids","g":"Action, role-playing","r":"November 2003","l":"https://en.wikipedia.org/wiki/Chicago_1930","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zs5.jpg","s":"The game is a RPG based in Chicago in the 1930s, an era heavily associated with gangsters and mafia."},{"t":"Chicken Shoot 2","p":["Windows"],"d":"Toontraxx, Frontline Studios","u":"Zuxxez/TopWare Interactive, DSI Games, Zoo Digital Publishing","g":"Shoot 'em up","r":"December 17, 2003","l":"https://en.wikipedia.org/wiki/Chicken_Shoot_2"},{"t":"Chinese Paladin 3","p":["Windows"],"d":"Softstar Technology Co., Ltd.","u":"Softstar Entertainment Inc., Unistar","g":"Role-playing","r":"July 31, 2003","l":"https://en.wikipedia.org/wiki/Chinese_Paladin_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2k93.jpg","s":"The Legend of Sword and Fairy 3 (Chinese Paladin 3) is an action role-playing game developed by the Taiwanese company Softstar Entertainment. It is the third installment in The Legend of Sword and Fairy (or Chinese Paladin) video game series, and serves as a prequel to the first game. The game incorporates elements of wuxia, shenmo and fantasy."},{"t":"Choco-Mate","p":[],"l":"https://en.wikipedia.org/wiki/Choco-Mate"},{"t":"Choro Q HG 4","p":["PlayStation 2"],"d":"Barnhouse Effect","u":"Takara, Atlus, Zoo Digital Publishing","g":"Racing, Role-playing","r":"November 27, 2003","l":"https://en.wikipedia.org/wiki/Choro_Q_HG_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ucw.jpg","s":"Choro-Q HG 4 (Japanese: チョロQ HG 4), known as Choro-Q in all other regions, is the fourth and final video game in the \"HG/High Grade\" series.\n\nChoro Q refines its fantasy-style racing series with more cars, parts, and extras. Now you can race on courses that range from earthquake country and space to haunted castles and underwater tracks. You can participate in more than 160 races and 100 events to earn 200 kinds of vehicles. Customize your vehicle with interchangeable parts and colors, and then race head-to-head against a friend. In addition to racing, ChoroQ also features more than 30 minigames."},{"t":"Chrome","p":["Windows"],"d":"Techland","u":"Gathering, Strategy First","g":"First-person shooter","r":"June 13, 2003","l":"https://en.wikipedia.org/wiki/Chrome_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4htc.jpg","s":"You play as Logan, a surly space-faring mercenary in this first-person shooter. Travel from planet to planet working for the highest paying corporation. You not only travel on foot, you can man a variety of different vehicles on the land, air and sea. Chrome adds a neat spin on the first-person shooter realm with features such as an inventory system, cybernetic implants that enhance your abilities and an engaging and cinematic storyline."},{"t":"CIMA: The Enemy","p":["Game Boy Advance"],"d":"Neverland","u":"Natsume Inc., Marvelous Entertainment","g":"Role-playing","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/CIMA:_The_Enemy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4pru.jpg","s":"For decades, the human race and the CIMA race have been in constant conflict with one another. As Ark J, your mission is to guard the gate between the two worlds, protect your appointed town, and ultimately, find peace. You'll progress through a nonlinear storyline while solving puzzles, exploring worlds, and battling enemies. The game includes a combat system that features both action and strategy elements. Another feature lets you activate non-playable characters to help you accomplish your goals."},{"t":"Civilization III: Conquests","p":["Windows"],"r":"November 4"},{"t":"Clover Heart's","p":["Windows","PlayStation 2"],"d":"ALcot, HuneX, Dennō Club","u":"ALcot, Interchannel","g":"Eroge, Visual novel","r":"November 28, 2003","l":"https://en.wikipedia.org/wiki/Clover_Heart's"},{"t":"Cold War Conflicts","p":["Windows"],"d":"Red Ice Software, Fireglow Games","u":"Russobit-M, GMX Media","g":"Real-time strategy","l":"https://en.wikipedia.org/wiki/Cold_War_Conflicts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3uv2.jpg","s":"Cold War Conflicts is a real-time strategy game developed by Russian studios Fireglow Games and Red Ice software, set in the historical period of the Cold War era from 1950 to 1973. In four campaigns you take control of the military forces of eight nations (United States, Israel, Egypt, North Korea, United Kingdom, Syria, USSR and China)."},{"t":"Combat Mission 3: Afrika Korps","p":["Windows","macOS"],"d":"Battlefront.com","u":"CDV Software","g":"Computer wargame","r":"November 28, 2003","l":"https://en.wikipedia.org/wiki/Combat_Mission_3:_Afrika_Korps","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co60lj.jpg","s":"Combat Mission: Afrika Korps is a turn-based computer game about tactical battles in World War II. It is part of the Combat Mission series."},{"t":"Command & Conquer: Generals","p":["Windows"],"g":"Action, Strategy","r":"February 10","l":"https://store.steampowered.com/app/2229870","i":"images/steam-2229870.jpg","s":"Command &amp; Conquer Generals puts your trigger finger on the pulse of modern warfare. Prepare your forces General... it's time to engage in the next generation of real-time strategy."},{"t":"Command & Conquer: Generals – Zero Hour","p":["Windows"],"r":"September 22"},{"t":"Commandos 3: Destination Berlin","p":["Windows"],"d":"Pyro Studios","u":"Eidos Interactive","g":"Real-time tactics","r":"October 14, 2003","l":"https://en.wikipedia.org/wiki/Commandos_3:_Destination_Berlin","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1v0d.jpg","s":"Third part of the legendary tactical strategic saga from Pyro Studios"},{"t":"Conflict: Desert Storm II","p":["PlayStation 2","Windows","Xbox"],"d":"Pivotal Games","u":"SCi Games, Gotham Games","g":"Tactical shooter","r":"September 18, 2003","l":"https://en.wikipedia.org/wiki/Conflict:_Desert_Storm_II"},{"t":"Conspiracies","p":["Windows"],"d":"Anima Interactive","u":"Got Game Entertainment, GMX Media","g":"Adventure, Interactive movie","r":"October 29, 2003","l":"https://en.wikipedia.org/wiki/Conspiracies_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/hdj11rd7egpjetjbreyl.jpg"},{"t":"Construction-Destruction","p":["Windows"],"d":"Gabriel Entertainment","u":"ValuSoft","g":"Construction game","l":"https://en.wikipedia.org/wiki/Construction-Destruction"},{"t":"Contract J.A.C.K.","p":["Windows"],"d":"Monolith Productions","u":"Vivendi Universal Games, Sierra Entertainment","g":"First-person shooter","r":"November 11, 2003","l":"https://en.wikipedia.org/wiki/Contract_J.A.C.K.","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5vpr.jpg","s":"Trained to survive. Paid to kill. Explore the dark side of the \"No One Lives Forever\" universe as John Jack, a rugged anti-hero in the services of H.A.R.M."},{"t":"Corvette","p":["Windows","Xbox","Game Boy Advance"],"d":"Steel Monkeys, Visual Impact","u":"TDK Mediactive, Global Star Software","g":"Racing game","r":"November 11, 2003","l":"https://en.wikipedia.org/wiki/Corvette_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9bma.jpg","s":"Corvette lets you race a variety of Corvettes on the open road or in super speedways. The game includes more than 120 production Corvette models from 1953 to 2003, plus show and race cars. Choose a car, official car color, and a driver, and then race on tracks or an obstacle-filled Route 66. Upgrade your car's engine and suspension for more realistic physics."},{"t":"Counter-Strike","p":["Windows","Xbox"],"r":"September 9","l":"https://en.wikipedia.org/wiki/Counter-Strike_(video_game)"},{"t":"Counter-Strike Neo","p":["Arcade"],"d":"Namco","u":"Namco","g":"Tactical arcade first-person shooter","r":"June 11, 2003","l":"https://en.wikipedia.org/wiki/Counter-Strike_Neo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co270a.jpg","s":"Counter-Strike Neo is a Japanese arcade adaptation of Counter-Strike, the original Half-Life multiplayer modification. It was published by Namco and runs on a Linux system. The game features unique maps, factions, and settings, though the gameplay and the weapon lineups remain the same as other Counter-Strike games, only with a huge difference in visuals."},{"t":"Crash Bandicoot 2: N-Tranced","p":["Game Boy Advance"],"r":"January 7"},{"t":"Crash Nitro Kart","p":["PlayStation 2","Xbox","GameCube","Game Boy Advance","N-Gage"],"r":"November 15","l":"https://en.wikipedia.org/wiki/Crash_Nitro_Kart"},{"t":"Crazy Taxi: Catch a Ride","p":["Game Boy Advance"],"r":"April 9"},{"t":"Crimson Skies: High Road to Revenge","p":["Xbox"],"u":"Microsoft Game Studios","r":"October 21, 2003"},{"t":"Crimsonland","p":["Windows","macOS","Linux"],"d":"10tons Entertainment","u":"Reflexive Entertainment","g":"Shoot 'em up","r":"April 22, 2003","l":"https://en.wikipedia.org/wiki/Crimsonland","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc400.jpg","s":"Top-down arena shooter video game with role-playing elements. It was developed by Finnish studio 10tons Entertainment and published by Reflexive Entertainment in 2003. In 2014 an enhanced re-release followed."},{"t":"Cross Channel","p":["Windows"],"d":"Flying Shine","u":"Flying Shine, KID, Cyberfront, 5pb.","g":"Visual novel","r":"September 26, 2003","l":"https://en.wikipedia.org/wiki/Cross_Channel_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3skj.jpg","s":"Set in Gunjo Gakuin, a school specialized for those deemed by the government to be unfit for society, Cross Channel follows the story of eight members of the school's Broadcasting Club who have just returned from a disastrous field trip, which throws their club and their friendships into turmoil."},{"t":"Crouching Tiger, Hidden Dragon","p":["Xbox"],"r":"December 9","l":"https://en.wikipedia.org/wiki/Crouching_Tiger,_Hidden_Dragon_(video_game)"},{"t":"CSI: Crime Scene Investigation","p":["Windows"],"d":"Radical Entertainment, EPCConnect","u":"Ubi Soft, Aspyr","g":"Adventure","r":"March 25, 2003","l":"https://en.wikipedia.org/wiki/CSI:_Crime_Scene_Investigation_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yki.jpg","s":"What do a murdered woman, a slain police officer, and a mysterious arson case have in common? Enter the gritty world of CSI and search for the answer with Grissom, Catherine, and the entire Crime Scene Investigation team. As a new recruit, you'll have to learn how to use all of the investigator tools, including cotton swabs, rubber gloves, and plaster molds."},{"t":"CT Special Forces: Back to Hell","p":["Game Boy Advance","PlayStation"],"d":"Light and Shadow Production, Wizarbox","u":"Light and Shadow Production, Hip Interactive","g":"Run and gun","r":"July 9, 2003","l":"https://en.wikipedia.org/wiki/CT_Special_Forces:_Back_to_Hell","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4epr.jpg","s":"Intelligence agencies are mentioning an increase in terrorist activity in every nook and cranny of the planet. The secret services are in a decidedly uncomfortable spot, given the latest resounding failures. The CT Special Forces unit will once again be called upon to diffuse a series of conflicts that have democracies around the globe highly concerned."},{"t":"CTU: Marine Sharpshooter","p":["Windows"],"d":"Jarhead Games","u":"Groove Games","g":"First-person shooter","r":"March 20, 2003","l":"https://en.wikipedia.org/wiki/CTU:_Marine_Sharpshooter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/mgn9upxzha4oqsmjgwgb.jpg","s":"Marine Sharpshooter's gameplay involves both sniping and close quarters combat. The game's environment varies from the caves and small villages of Afghanistan, to snowy cliffs and rooftops of Chechnya, to sandy beaches and jungles of Pacific island. Interaction between player and environment is minimal.\n\nThe game features simulations of the real sniper rifles used by the US Marine Corps snipers, as well as other real weapons, such as assault rifles, pistols, and sniper rifles. There is even the occasional RPG used by the enemy.\n\nThe game features sniping, with the ability to use the sniper rifle's scope to zoom in on far away targets, as well as close quarters combat using a pistol with an optional silencer or using a knife. Several points in the game require the player to stay in one spot engaging hostiles that emerge from various doorways and windows. At other times, the player can explore the map freely."},{"t":"Cubix Robots for Everyone: Showdown","p":["GameCube","PlayStation 2"],"d":"Blitz Games","u":"The 3DO Company","g":"Action-adventure, role-playing","r":"June 2, 2003","l":"https://en.wikipedia.org/wiki/Cubix_Robots_for_Everyone:_Showdown","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ttg.jpg","s":"Cubix: Robots for Everyone - Showdown is a futuristic themed 3D action adventure game based on the Cubix: Robots for Everyone TV series.\n\nIn the game the player takes control of either Connor or Abby and has to explore Bubble town by solving puzzles and battling robots. You have the ability to jump and move objects. The robot battles are turn-based and when won the robot is added to your battle team and can be used in the next battle. More than twenty-five robots can be collected. Cubix the main robot can transform into several vehicles. The game also includes mini-games that can be played with up to four players."},{"t":"Curse: The Eye of Isis","p":["Windows","Xbox","PlayStation 2"],"d":"Asylum Entertainment","u":"DreamCatcher Interactive, Wanadoo Edition","g":"Survival horror","r":"October 20, 2003","l":"https://en.wikipedia.org/wiki/Curse:_The_Eye_of_Isis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22ib.jpg","s":"Strange things are happening at Great Britain’s museum of natural history in 1890. A gang of ruthless thugs has broken into the establishment, the Eye of Isis Egyptian statue has been stolen, and a mysterious fog has overtaken a number of areas of the museum killing and transforming all it comes into contact with."},{"t":"Cyber Troopers Virtual-On MARZ","p":["PlayStation 2"],"r":"October 14","l":"https://en.wikipedia.org/wiki/Cyber_Troopers_Virtual-On_Marz"},{"t":"Cyberchase: Carnival Chaos","p":["Windows","macOS"],"d":"Basis Applied Technology","u":"The Learning Company","g":"Edutainment","l":"https://en.wikipedia.org/wiki/Cyberchase:_Carnival_Chaos"},{"t":"Cyberchase: Castleblanca Quest","p":["Windows","macOS"],"d":"Basis Applied Technology","u":"The Learning Company","g":"Edutainment","l":"https://en.wikipedia.org/wiki/Cyberchase:_Castleblanca_Quest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/fpktr7hhfvlbnxevumwt.jpg","s":"An educational game based on the Cyberchase TV series."},{"t":"Dakar 2: The World's Ultimate Rally","p":["PlayStation 2","GameCube","Xbox"],"d":"Acclaim Studios Cheltenham","u":"Acclaim Entertainment","g":"Racing","r":"March 14, 2003","l":"https://en.wikipedia.org/wiki/Dakar_2:_The_World's_Ultimate_Rally","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6tth.jpg","s":"Dakar 2 is a racing game, of course simulating the famous Paris-Dakar Rally. Although not the real 6000 kilometers can be crossed in the game, the rally mode takes the player through 12 tracks all the way from France to Dakar. The tracks lead racers through cities, forests and the desert. Most of them are simple tracks, but there are desert tracks where the player can drive around freely, finding the checkpoints faster than the opponents. The player can choose from the officially licensed cars, trucks and bikes from Dakar 2002, but only vehicles of the same type can compete in a race. There is also an arcade racing mode, where all the tracks and vehicles that have been unlocked in rally mode can be selected, as well as a splitscreen mode for two players."},{"t":"Dancing Stage MegaMix","p":["PlayStation 2"],"d":"Konami, Bemani","u":"Konami","g":"Music, exercise","r":"May 30, 2003","l":"https://en.wikipedia.org/wiki/Dancing_Stage_MegaMix","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5s2l.jpg","s":"Dancing Stage MegaMix is the fifth home release in the Dancing Stage series, a European version of the Dance Dance Revolution series of music video games. MegaMix was the first Dancing Stage game released on the Sony PlayStation 2 game console.\n\nBased largely on Dancing Stage EuroMix 2, MegaMiX was separated from the arcade game by a completely different track list of songs. The game was marketed by Konami as a family game and an exercise tool in an effort to make the niche series more mainstream."},{"t":"Danger from the Deep","p":["Linux","Windows"],"g":"Submarine simulator","l":"https://en.wikipedia.org/wiki/Danger_from_the_Deep"},{"t":"Daredevil","p":["Game Boy Advance"],"d":"Griptonite Games","u":"Encore Software, THQ","g":"Action","r":"February 4, 2003","l":"https://en.wikipedia.org/wiki/Daredevil_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d3z.jpg","s":"Daredevil for the Game Boy Advance is your basic punch-kick-jump action platformer featuring Marvel's more unlikely superhero, a blind lawyer with enhanced abilities and senses. Though the game was marketed as a tie-in with the February 14th release of the Daredevil film, the GBA title is more based upon a less realistic, comic book design with bright and vibrant colors and the occasional \"Pow!\" and \"Bif!\" when knocking out opponents. Some levels cut across rooftops, others over vehicles in traffic; some go in buildings and underground. As players get through the 23 different levels, they'll uncover the game's original plot through comic book-style cutscenes."},{"t":"Dark Age of Camelot: Foundations","p":[],"l":"https://en.wikipedia.org/wiki/Dark_Age_of_Camelot:_Foundations"},{"t":"Dark Age of Camelot: Trials of Atlantis","p":[],"l":"https://en.wikipedia.org/wiki/Dark_Age_of_Camelot:_Trials_of_Atlantis"},{"t":"Dark Cloud 2","p":["PlayStation 2"],"r":"February 17","l":"https://en.wikipedia.org/wiki/Dark_Chronicle"},{"t":"Day of Defeat","p":["Windows"],"g":"Action","r":"May 6","l":"https://en.wikipedia.org/wiki/Day_of_Defeat","i":"images/steam-30.jpg","s":"Enlist in an intense brand of Axis vs. Allied teamplay set in the WWII European Theatre of Operations. Players assume the role of light/assault/heavy infantry, sniper or machine-gunner class, each with a unique arsenal of historical weaponry at their disposal. Missions are based on key historical operations."},{"t":"DDRMAX2: Dance Dance Revolution","p":["PlayStation 2"],"r":"September 23"},{"t":"Dead or Alive Xtreme Beach Volleyball","p":["Xbox"],"r":"January 22","l":"https://en.wikipedia.org/wiki/Dead_or_Alive_Xtreme_Beach_Volleyball"},{"t":"Dear Boys","p":[],"l":"https://en.wikipedia.org/wiki/Dear_Boys"},{"t":"December When There Is No Angel","p":["Windows"],"u":"Leaf","g":"Eroge, Visual novel","r":"September 26, 2003","l":"https://en.wikipedia.org/wiki/December_When_There_Is_No_Angel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30xq.jpg","s":"TenInai is about a senior high school boy with relationship problems; he's got few friends and perhaps because of his bothersome kid sister, is averse to any steady relationship. That is, until he has a sexual encounter with Kurihara Touko. Touko, a classmate of his, is a sensitive, simple girl desperate to make an impression on others, and willingly offers herself to the protagonist. He runs away from a relationship; Touko clings to him hoping to find one. This unusual relationship soon leads them on a long soul-searching journey."},{"t":"Decisive Battles of WWII: Korsun Pocket","p":["Windows"],"d":"Strategic Studies Group","u":"Matrix Games","g":"Computer wargame","l":"https://en.wikipedia.org/wiki/Decisive_Battles_of_WWII:_Korsun_Pocket","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/k8pglfluphsjjoworhsv.jpg"},{"t":"Def Jam Vendetta","p":["GameCube","PlayStation 2"],"d":"AKI Corporation, EA Canada","u":"EA Sports BIG, EA Games","g":"Sports, fighting","r":"April 1, 2003","l":"https://en.wikipedia.org/wiki/Def_Jam_Vendetta","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4vwc.jpg","s":"The unlikely combination of Def Jam recording artists and underground wrestling is the subject of this Electronic Arts release, which features the 3D likenesses of such musicians as Ludacris, Redman, DMX, Scarface, Ghostface Killa, Method Man, and more as playable characters. Developed by AKI Corporation, whose previous experience in the genre includes titles WWF No Mercy and WCW/NWO Revenge, Def Jam Vendetta offers an estimated 1,500 animations for each of the 45 included characters. A total of ten different venues are available, and one of the featured modes offers a storyline complete with soap opera-style drama to go along with the suplexes and body slams. Up to four players can compete in Single, Tag-Team, Handicap, or Battle Royale matches."},{"t":"Defense of the Ancients","p":["Windows","macOS"],"g":"MOBA","l":"https://en.wikipedia.org/wiki/Defense_of_the_Ancients","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r5l.jpg","s":"Defense of the Ancients (DotA) is a multiplayer online battle arena mod for the video game Warcraft III: Reign of Chaos and its expansion, Warcraft III: The Frozen Throne, based on the \"Aeon of Strife\" map for StarCraft. The scenario objective is for each team to destroy the opponents' Ancient, heavily guarded structures at opposing corners of the map. Players use powerful units known as heroes, and are assisted by allied heroes and AI-controlled fighters. As in role-playing games, players level up their heroes and use gold to buy equipment during the mission.\n\nThe scenario was developed with the \"World Editor\" of Reign of Chaos, and was updated upon the release of its expansion, The Frozen Throne. There have been many variations of the original concept; the most popular being DotA Allstars, which eventually was simplified to DotA with the release of version 6.68. This specific scenario has been maintained by several authors during development, the latest of whom is the anonymous developer known as \"IceFrog\" who has developed the game since 2005.\n\nSince its original release, DotA has become a feature at several worldwide tournaments, including Blizzard Entertainment's BlizzCon and the Asian World Cyber Games, as well as the Cyberathlete Amateur and CyberEvolution leagues; in a 2008 article of video game industry website Gamasutra, the article's author claimed that DotA was probably \"the most popular and most-discussed free, non-supported game mod in the world\". DotA is largely attributed to being the most significant inspiration for the multiplayer online battle arena genre. Valve Corporation acquired the intellectual property rights to DotA to develop a stand-alone sequel, Dota 2, which was released in 2013."},{"t":"Delta Force: Black Hawk Down","p":["Windows"],"d":"NovaLogic, Climax London, Rebellion Developments, Aspyr","u":"NovaLogic, Aspyr","g":"First-person shooter","r":"March 25, 2003","l":"https://en.wikipedia.org/wiki/Delta_Force:_Black_Hawk_Down","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dk5.jpg","s":"In late 1993, the United States launched dual military operations in Mogadishu Somalia. Delta Force Operatives and Army Rangers were sent in to capture Somali warlords and restore order. Experience the intense combat of Operation Restore Hope in this ground breaking first person shooter. As a Delta Force operative participate in a number of daring and intense raids against the oppressive Somali warlords in and around Mogadishu."},{"t":"DemiKids: Dark Version","p":["Game Boy Advance"],"r":"October 7"},{"t":"DemiKids: Light Version","p":["Game Boy Advance"],"r":"October 6"},{"t":"Demonbane","p":["Windows"],"g":"Visual Novel","l":"https://en.wikipedia.org/wiki/Demonbane","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fch.jpg","s":"Arkham city is a bustling hub of commerce and industry, however Arkham is also a center of eldrich lore: home to Miskatonic University, an institution of higher learning with one of the most complete libraries of arcane literature in the world. In the span of two generations the town was built up to the status of prestige it now commands, an expansion helmed by the Hadou Group, an industrial complex and family dynasty currently run by the young Hadou Ruri. She pursues the peace and prosperity of Arkham diligently, against the forces of darkness threatening to plunge the city, and the world, back into a second dark age. Among the most sinister threats to Arkham City is the evil Black Lodge syndicate. Led by the charismatic Master Therion, his nihilistic outlook shapes the group's destructive goals: with a circle of powerful sorcerers at his command, the potential for sowing chaos in the city is unmatched.\n\nFormer Miskatonic University Magic Academy student Daijuuji Kurou knows little of grimoires, but what he does know terrifies him - enough that he left his university life behind, and now practices a failing detective business in the shelter of an orphanage in a quiet corner of Arkham. But just when he thought his Academy past was buried, it catches up with him and pulls him back into the dark shadows of the occult: Hadou Ruri herself appears at his door with an offer he can't refuse. The only way to combat the Black Lodge's growing magical power is to find, and retrieve, a grimoire with the power to activate the mightiest Machina of all: Demonbane. The quest to find this forbidden tome will change Kurou's destiny... forever."},{"t":"Densetsu no Starfy 2","p":["Game Boy Advance"],"d":"Tose","u":"Nintendo","g":"Platform","r":"September 5, 2003","l":"https://en.wikipedia.org/wiki/Densetsu_no_Starfy_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4an7.jpg","s":"Stafy is now back at Pufftop Palace, playing with his friend Moe. Ogura, imprisoned inside the Magic Jar, unleashes his children into the sky. Ogura's children cause a series of thunderstorms and earthquakes that shake Pufftop Palace, causing the Magic Jar to shatter and release Ogura."},{"t":"Deus Ex: Invisible War","p":["Windows","Xbox"],"g":"Action","r":"December 2","l":"https://store.steampowered.com/app/6920","i":"images/steam-6920.jpg","s":"Approximately 20 years after Deus Ex, the world is only beginning to recover from a catastrophic worldwide depression. In this techno-nightmare, take part in the dark struggle to raise the world from its own ashes."},{"t":"Devastation","p":["Windows","Linux"],"d":"Digitalo Studios","u":"ARUSH Entertainment, Groove Games, NovaLogic","g":"First-person shooter","r":"March 25, 2003","l":"https://en.wikipedia.org/wiki/Devastation_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8bkj.jpg","s":"The year is 2075. Instead of a bright and peaceful future, human civilization is in a state of polluted, dilapidated ruin akin to post-World War II Europe. A corrupt mega-corporation, Grathius Inc., controls the world by force, using pacification squads to kill any who oppose them.\n\nThe game's protagonist is Flynn Haskell, the leader of a small band of terrorists/resistance-fighters determined to rid the world of Grathius and their evil schemes.Later the player meets up with a female scientist Eve whom Flynn regards as the best helper he could get. Flynn, while exploring once, is captured and put into jail but successfully escapes with another resistance member named Duffy who also helps him in his next destination Urbia, as she is familiar with their resistance leader Tara.\n\nThe game's main plot revolves around a new technology developed by Grathius, nano-machinery based cloning, that allows the corporation to resurrect its fallen troops and gives them an unstoppable immortal army. As the game progresses, the player travels from San Francisco to Taiwan to Japan, recruiting new characters into the resistance and capturing Grathius cloning devices for their own personal use."},{"t":"Devil May Cry 2","p":["PlayStation 2"],"r":"January 25","l":"https://en.wikipedia.org/wiki/Devil_May_Cry_2"},{"t":"Digimon Battle Spirit 2","p":["Game Boy Advance"],"r":"September 24","l":"https://en.wikipedia.org/wiki/Digimon_Battle_Spirit_2"},{"t":"Diner Dash","p":["macOS","Mobile phone","PlayStation Portable"],"d":"Gamelab","u":"PlayFirst","g":"Strategy, time management","l":"https://en.wikipedia.org/wiki/Diner_Dash","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8xrr.jpg","s":"Diner Dash, a popular PC action-puzzle game, has landed on the WiiWare service. Guide Flo, an office worker-turned-restaurateur, as she builds up her empire over four unique diners. Go online to face players in head-to-head. If you feel up to the challenge, join up with a friend or another player online for a Team Dash game where your team will take on six other players to see whose diner is the best in town. (Broadband Internet access is required for online play.)\n\nPlayers take direct control of Flo as she runs around to seat patrons, take orders, deliver food, take payment and bus tables as efficiently as possible within the time allowed. Players who are fond of traditional control schemes may also use a point-and-click style with hotkeys to aid Flo in her quest for customer satisfaction, which is reflected in a heart meter that empties as customers lose patience. If the meter empties completely, then the customer will leave the restaurant."},{"t":"Dino Crisis 3","p":["Xbox"],"r":"September 16","l":"https://en.wikipedia.org/wiki/Dino_Crisis_3"},{"t":"Dinotopia: The Sunstone Odyssey","p":["Xbox"],"r":"July 23"},{"t":"Disaster Report","p":["PlayStation 2"],"r":"February 15","l":"https://en.wikipedia.org/wiki/Disaster_Report"},{"t":"Disgaea: Hour of Darkness","p":["PlayStation 2"],"d":"Nippon Ichi Software","u":"Nippon Ichi Software, Atlus, Koei, Square Enix","g":"Tactical role-playing","r":"January 30, 2003","l":"https://en.wikipedia.org/wiki/Disgaea:_Hour_of_Darkness","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ps9.jpg","s":"Disgaea: Hour of Darkness is a tactical role-playing video game and the first game in the Disgaea series. Battle gameplay takes place on a map divided into a square grid. The player controls a squad of humanoid units and monsters, which each occupy a single square of the grid and do combat with a group of enemies. Depending on the character and attack selected, the player will be able to deal damage to a specific enemy unit or a designated region of the map. Combat ends when all enemy units or all of the player's units are destroyed."},{"t":"Disney Sports Motocross","p":["Game Boy Advance"],"d":"Jupiter Corporation","u":"Konami","g":"Racing","r":"March 29, 2003","l":"https://en.wikipedia.org/wiki/Disney_Sports_Motocross","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d14.jpg","s":"Race to become a motocross champion! Join Mickey and his pals for the most action you will find on two wheels as you rack up points, gather gems, and collect cool motorcycle parts."},{"t":"Disney Sports Snowboarding","p":["Game Boy Advance"],"d":"Konami","u":"Konami","g":"Racing","r":"January 16, 2003","l":"https://en.wikipedia.org/wiki/Disney_Sports_Snowboarding","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w0p.jpg","s":"Get ready for some serious powder action!\n\nMickey and his pals are ready to hit the slopes. Race in fantastic locals, compete against friends, and show off your trick style to see who is king of the snowy castle.\n\nGame features include 5 massive stages, 30 boards to unlock and boost performance, a wide range of outrageous tricks, and multiplayer mode to race against your friends."},{"t":"Disney's Brother Bear","p":["Game Boy Advance","Windows"],"d":"KnowWonder, Vicarious Visions","u":"Disney Interactive","g":"Action, platformer","r":"November 4, 2003","l":"https://en.wikipedia.org/wiki/Disney's_Brother_Bear_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rxs.jpg","s":"Brother Bear allows players to play as Kenai and Koda, individually or as a team, as they go on an adventure that follows the beats of the film. The game features elements such as spectacular weather effects and cut-scenes from the film which will bring alive the world of Brother Bear. With four worlds, 16 levels and unlockable bonus games, Disney's Brother Bear for the GBA is a game of epic proportions."},{"t":"Disney's Extreme Skate Adventure","p":["PlayStation 2","GameCube","Xbox","Game Boy Advance"],"d":"Toys for Bob, Vicarious Visions","u":"Activision","g":"Sports","r":"September 2, 2003","l":"https://en.wikipedia.org/wiki/Disney's_Extreme_Skate_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dyz.jpg","s":"Disney characters step out of the movies and onto skateboards in Disney's Extreme Skate Adventure. You can play as your favorite Disney and Pixar characters, such as Buzz Lightyear and Woody from Toy Story 2, Simba and Rafiki from The Lion King, and Young Tarzan and Terk from Tarzan. Now you can skate, pull off tricks, and solve puzzles in all the exciting places you've seen in the movies, including Pride Rock, the Jungle Treehouse, and Pizza Planet."},{"t":"Disney's Hide and Sneak","p":["GameCube"],"d":"Capcom","u":"Capcom","g":"Action-adventure","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/Disney's_Hide_and_Sneak","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ryo.jpg","s":"Either Mickey or Minnie will get kidnapped by a strange flying alien mushroom - depending on who the players chooses to control. Now the other character has to undertake a rescue mission. Gameplay includes climbing, solving puzzles, jumping, evading and hiding from enemies. Enemies can be taken out when sneaking close enough to enemies. As you make progress you traverse three game areas. These are a warehouse, museum and ruins."},{"t":"Disney's Magical Quest 2 Starring Mickey & Minnie","p":["Game Boy Advance"],"r":"November 12","l":"https://en.wikipedia.org/wiki/Disney%27s_Magical_Quest_2_Starring_Mickey_%26_Minnie"},{"t":"Dog's Life","p":["PlayStation 2"],"d":"Frontier Developments","u":"Sony Computer Entertainment, Hip Games","g":"Action-adventure","r":"October 31, 2003","l":"https://en.wikipedia.org/wiki/Dog's_Life","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pxq.jpg","s":"In Dog's Life you play Jake the puppy, as he explores the USA in an attempt to foil a fiendish plot. Miss Peaches doesn't like dogs, and sees them as a way of making money, by dog-napping Daisy the pedigree dog.\n\nThe dog elements are closely integrated into the game - smells are indicated by lines of coloured smoke, emphasising a dog's acute sense of smell. Locating footprints is also done via this Smellovision mode. Tricks can be learnt, and used to win treats from humans.\n\nJake must explore vast environments and interact with 15 breeds of dog. The aim is to get them onto his side, which is usually done by either having more bones than them, or winning a subgame against them. These are also dog-based - in one you must dig up bones, while another has you 'marking territory' to annex a full screen."},{"t":"Dogfight: Battle for the Pacific","p":["Windows","PlayStation 2"],"d":"InterActive Vision","u":"Midas Interactive Entertainment, ValuSoft","g":"Simulation","l":"https://en.wikipedia.org/wiki/Dogfight:_Battle_for_the_Pacific"},{"t":"Dokapon DX: Wataru Sekai wa Oni Darake","p":["GameCube"],"d":"Asmik Ace Entertainment","u":"Asmik Ace Entertainment","g":"Action","r":"April 10, 2003","l":"https://en.wikipedia.org/wiki/Dokapon_DX:_Wataru_Sekai_wa_Oni_Darake"},{"t":"Dokodemo Chocobo 2: Dasshutsu! Yūreisen","p":[],"l":"https://en.wikipedia.org/wiki/Dokodemo_Chocobo_2:_Dasshutsu!_Y%C5%ABreisen"},{"t":"Dominions II: The Ascension Wars","p":["Windows","Linux","macOS"],"d":"Illwinter Game Design","u":"Shrapnel Games","g":"Turn-based strategy, fantasy","r":"November 14, 2003","l":"https://en.wikipedia.org/wiki/Dominions_II:_The_Ascension_Wars"},{"t":"Domácí násilí: Game over","p":[],"l":"https://en.wikipedia.org/wiki/Dom%C3%A1c%C3%AD_n%C3%A1sil%C3%AD:_Game_over"},{"t":"Donkey Kong Country","p":["Game Boy Advance"],"r":"June 9","l":"https://en.wikipedia.org/wiki/Donkey_Kong_Country"},{"t":"Donkey Konga","p":["GameCube"],"d":"Namco","u":"Nintendo","g":"Rhythm","r":"December 12, 2003","l":"https://en.wikipedia.org/wiki/Donkey_Konga","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6rdt.jpg","s":"Donkey Konga is a GameCube rhythm video game starring the ape Donkey Kong, developed by Namco and published by Nintendo. Instead of the standard GameCube controllers, the game is intended to be played with a special controller called the DK Bongos that resemble two small bongo drums.\n\nDonkey Konga was developed by the same team of people who made the Taiko: Drum Master series for the PlayStation 2. The tracks include hits such as \"Louie Louie\", \"We Will Rock You\", \"Shining Star\", \"Rock Lobster\" and \"Losing My Religion\". There are tracks from the Mario series, the The Legend of Zelda series and other Nintendo related music. All regional variants of the game have differing track listings, and in the North American version of both games, almost all of the licensed non-Nintendo/traditional songs are shortened covers."},{"t":"Double Dragon Advance","p":["Game Boy Advance"],"r":"November 13","l":"https://en.wikipedia.org/wiki/Double_Dragon_Advance"},{"t":"Downhill Domination","p":["PlayStation 2"],"d":"Incog Inc. Entertainment","u":"Sony Computer Entertainment, Codemasters","g":"Racing, vehicular combat","r":"July 22, 2003","l":"https://en.wikipedia.org/wiki/Downhill_Domination","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3h0v.jpg","s":"Downhill Domination is a video game based on a fictional racing event with fictional racers mixed with a few unlockable professional racers. The game was released exclusively for the PlayStation 2.\n\nDownhill Domination includes a very different style of gameplay that differs from standard bike racing games by having the character riding downhill almost exclusively (hence the name), due to the incline of the tracks."},{"t":"Downtown Run","p":["Windows","GameCube","Mobile phone","PlayStation 2"],"d":"Ubi Soft Bucharest, Com2uS","u":"Ubi Soft, Com2uS","g":"Racing, vehicular combat","r":"March 27, 2003","l":"https://en.wikipedia.org/wiki/Downtown_Run"},{"t":"Dr. Blob's Organism","p":["Windows","macOS"],"d":"Digital Eel","u":"Cheapass Games","g":"Shoot 'em up","r":"July 4, 2003","l":"https://en.wikipedia.org/wiki/Dr._Blob's_Organism"},{"t":"Drag Racer","p":["Browser"],"d":"XMG Studio, Phantom Games","u":"XMG Studio, Phantom Games","g":"Gaming, Family & Arcade, Racing","l":"https://en.wikipedia.org/wiki/Drag_Racer_(video_game)"},{"t":"Dragon Ball Z: Budokai","p":["GameCube"],"r":"October 28"},{"t":"Dragon Ball Z: Taiketsu","p":["Game Boy Advance"],"u":"Atari","r":"November 24, 2003"},{"t":"Dragon Ball Z: The Legacy of Goku II","p":["Game Boy Advance"],"d":"Webfoot Technologies","u":"Atari, Infogrames, Banpresto","g":"Action-adventure","r":"June 17, 2003","l":"https://en.wikipedia.org/wiki/Dragon_Ball_Z:_The_Legacy_of_Goku_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2z5y.jpg","s":"Dragon Ball Z: The Legacy of Goku II was released on June 17, 2003. The plot of the game picks up where The Legacy of Goku left off, and continues until the end of the Cell Games Saga when Gohan defeats the evil android Cell. The game introduced several new concepts to the series. The first was transformations, which allowed characters to become temporarily stronger, at the cost of slowly draining their energy. It also introduced the scouter, which allowed players to look up the stats of other characters in the game, as well as basic information about them. The game also introduced charged melee attacks, which allowed characters to unleash a powerful physical strike after a short charging period. The game also allowed characters to further supplement their stats with capsules that were scattered around the game world. Despite being titled \"The Legacy of Goku\" this game featured the most limited play as the character Goku.\n\nDue to the game's success, a second version was released titled Dragon Ball Z: The Legacy of Goku II International exclusive to Japan on July 23, 2004. In this version all characters were given new profile images and their names were reverted to their original Japanese. However, Mister Satan still retains his English name \"Hercule\" on the front of his parade float.\n\n[Source] - Wikipedia."},{"t":"Dragon Ball Z: Ultimate Battle 22","p":["PlayStation"],"r":"March 25"},{"t":"Dragon Drive: D-Masters Shot","p":["GameCube"],"g":"Shooter","l":"https://en.wikipedia.org/wiki/Dragon_Drive:_D-Masters_Shot","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ir8.jpg","s":"Dragon Drive: D-Masters Shot is a third-person shooter video game released in 2003 by Treasure Co. Ltd. The game is based on the Dragon Drive series and was only released in Japan.\n\nGameplay[edit]\nDragon Drive was an aerial combat game, set primarily in large, outdoor arenas where players had to face several waves of enemies. With multi-directional dash and lock on abilities, the game has sometimes drawn comparisons to the Zone of the Enders series.\n\nThe game also has a handful of rail shooter levels, drawing frequent comparisons to Sega's Panzer Dragoon series, but these comprise only a very small portion of the game."},{"t":"Dragon Quest Monsters: Caravan Heart","p":["Game Boy Advance"],"d":"Tose","u":"Enix","g":"Role-playing","r":"March 29, 2003","l":"https://en.wikipedia.org/wiki/Dragon_Quest_Monsters:_Caravan_Heart","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2w3i.jpg","s":"Dragon Quest Monsters: Caravan Heart acts as a prequel to Dragon Quest 7 and was never released outside of Japan but there is a fan-translation patch.\n\nYou play Kiefer from Dragon Quest VII who ends up in the world of Dragon Quest II. You can use a group of 3 people or monsters to fight but enemies can show up in larger numbers. There is a job system for human characters with 20 classes."},{"t":"Dragon Treasure","p":["Arcade"],"d":"Overworks, Sega WOW","u":"Sega","g":"Medal game, role-playing","r":"July 2003","l":"https://en.wikipedia.org/wiki/Dragon_Treasure"},{"t":"Drake of the 99 Dragons","p":["Xbox"],"u":"Majesco","r":"November 3, 2003","l":"https://en.wikipedia.org/wiki/Drake_of_the_99_Dragons"},{"t":"DreamMix TV World Fighters","p":["GameCube","PlayStation 2"],"d":"Bitstep","u":"Hudson Soft","g":"Fighting","r":"December 18, 2003","l":"https://en.wikipedia.org/wiki/DreamMix_TV_World_Fighters","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ylj.jpg","s":"A fledgling television program has been suffering from poor audience approval, and the station that carries the show has informed its producers that they will have to rectify the situation or face inevitable cancellation.\n\nAn unorthodox plan is implemented: broadcast a contest pitting various superstars from differing realities in physical combat in order to increase ratings."},{"t":"Drome Racers","p":["Game Boy Advance"],"r":"June 19","l":"https://en.wikipedia.org/wiki/Drome_Racers"},{"t":"Duel Masters","p":[],"l":"https://en.wikipedia.org/wiki/Duel_Masters_(2003_video_game)"},{"t":"Duel Masters: Nettō! Battle Arena","p":[],"l":"https://en.wikipedia.org/wiki/Duel_Masters:_Nett%C5%8D!_Battle_Arena"},{"t":"Dungeon Scroll","p":["Windows"],"d":"Robinson Technologies","u":"Robinson Technologies","g":"Role-playing, word","l":"https://en.wikipedia.org/wiki/Dungeon_Scroll"},{"t":"Dungeons & Dragons: Heroes","p":["Xbox"],"r":"September 17"},{"t":"Dynasty Tactics 2","p":["PlayStation 2"],"d":"Koei","u":"Koei","g":"Tactical role-playing game","r":"June 26, 2003","l":"https://en.wikipedia.org/wiki/Dynasty_Tactics_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ouh.jpg","s":"The sequel to Dynasty Tactics gives the player more tactics to choose from, and introduces some new characters and features.\n\nLike in the first game, the player assumes the role of 3 important leaders in ancient China: Cao Cao, Liu Bei and Sun Ce. A new choice is the warrior Lu Bu. The characters have their own, unique story paths, which are affected by choices and outcomes occurring during the chapters the game is divided into. The player organizes and moves his officers and armies over the map while engaging others, trying to fulfill certain objectives during a turn limit.\n\nFor battles, the game switches from the map to a dedicated screen showing the battlefield. The battle system is a bit like chess: the player moves the units around the battlefield in a turn-based fashion, mostly trying to bring them in a position to pull off special tactics. Ideally, this results in effective combos, that may not only defeat enemy units, but also capture the leading officers, which may join the player (there are over 200 in the game).\n\nMorale and terrain need to be taken into consideration as well. Units have different abilities depending on their type and position in the army, Engineers may build useful installments like supply depots for example. Army strategists can use the link command retained from the previous game for pinning down enemy units and helping to rack up higher combos, in addition, they may order chains now. These allow individual officers to perform multiple tactics (provided the conditions are met for each of them), but cost morale.\n\nThe game also contains a two player versus mode, which consists of random battles."},{"t":"Dynasty Warriors 3: Xtreme Legends","p":["PlayStation 2"],"r":"January 11","l":"https://en.wikipedia.org/wiki/Dynasty_Warriors_3"},{"t":"Dynasty Warriors 4","p":["PlayStation 2"],"r":"March 25","l":"https://en.wikipedia.org/wiki/Dynasty_Warriors_4"},{"t":"Earth City demo","p":["Windows"],"d":"Bungie","u":"Microsoft","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Earth_City_demo"},{"t":"Ed, Edd n Eddy: Jawbreakers!","p":["Game Boy Advance"],"r":"March 25"},{"t":"Emergency 2: The Ultimate Fight for Life","p":["Windows"],"l":"https://en.wikipedia.org/wiki/Emergency_2:_The_Ultimate_Fight_for_Life"},{"t":"Emergency Fire Response","p":["Windows"],"d":"Monte Cristo Multimedia","u":"DreamCatcher Interactive","g":"Simulation","r":"July 29, 2003","l":"https://en.wikipedia.org/wiki/Emergency_Fire_Response","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8z93.jpg","s":"Command a team of elite firefighters as they are dispatched on missions to save lives and property from blazing infernos in locations including warehouses, apartments, banks, and chemical plants."},{"t":"Empires: Dawn of the Modern World","p":["Windows"],"d":"Stainless Steel Studios","u":"Activision","g":"Real-time strategy","r":"October 21, 2003","l":"https://en.wikipedia.org/wiki/Empires:_Dawn_of_the_Modern_World","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7nkv.jpg","s":"Empires: Dawn of the Modern World is a 2003 history-based real-time strategy computer game developed by Stainless Steel Studios and released on October 21, 2003. Considered an unofficial sequel to Empire Earth, the game requires players to collect resources to build an empire, train military units, and conquer opposing civilizations.\nBased on a slightly compressed version of world history, Empires covers five eras, from the Medieval Age to World War II. The game features nine civilizations: England, the Franks, Korea, and China are playable from the Medieval Age to the Imperial Age; the United States, Russia, Germany, France, and the United Kingdom are playable in the World War I and World War II ages.\nThe game attracted positive critical reaction.\nIn 2009, Activision terminated its multiplayer server contract with GameSpy. Multiplayer can be played unofficially in Gameranger services."},{"t":"Endless Ages","p":["Windows"],"d":"Avaria Corporation","u":"SummitSoft","g":"Massively multiplayer online first-person shooter/role-playing","r":"July 1, 2003","l":"https://en.wikipedia.org/wiki/Endless_Ages"},{"t":"Energy Airforce Aim Strike!","p":["PlayStation 2"],"u":"Taito, 505 Game Street","g":"Simulation","r":"October 2, 2003","l":"https://en.wikipedia.org/wiki/Energy_Airforce_Aim_Strike!"},{"t":"Enigma: Rising Tide","p":["Windows"],"d":"Tesseraction Games","u":"Dreamcatcher Interactive, GMX Media","g":"Vehicle simulation game","r":"August 25, 2003","l":"https://en.wikipedia.org/wiki/Enigma:_Rising_Tide","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/x2dbjbl6jkeowyadghio.jpg","s":"Set in an alternate 1940s, Enigma: Rising Tide is a simulator that solely focuses on naval combat."},{"t":"Enigmo","p":["Windows","macOS","PlayStation Portable"],"d":"Pangea Software, Beatshapers","u":"Pangea Software, Beatshapers","g":"Puzzle","l":"https://en.wikipedia.org/wiki/Enigmo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co60ka.jpg","s":"Enigmo is an award-winning unique 3D puzzle game where you manipulate slides, bumpers, accelerators and other pieces to control streams of flowing liquid. Liquids (water, oil, and lava) fall from 'droppers' and will bounce around the walls of a puzzle. You move and rotate the various puzzle pieces in order to divert the flow of the falling droplets so that they can reach their target. The faster you complete each level, the more bonuses you will receive, the higher position in the high scores table you get."},{"t":"Enter The Matrix","p":["Windows","GameCube","PlayStation 2","Xbox"],"r":"May 14","l":"https://en.wikipedia.org/wiki/Enter_The_Matrix"},{"t":"Entropia Universe","p":["Windows"],"d":"MindArk","u":"MindArk","g":"Massively multiplayer online role-playing game, first-person shooter","r":"January 30, 2003","l":"https://en.wikipedia.org/wiki/Entropia_Universe","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ho2.jpg","s":"Entropia Universe is an advanced 3D online virtual environment with a developed planetary system and one universal Real Cash Economy system. Each planet offers a wide variety of exciting entertainment. You can travel between the planets through space and socialize with people from all over the world.\n\nIt does not cost anything to join and there are no subscription fees. The Entropia Universe economy is built on an advanced micro-payment system, giving you as a participant a great freedom-of-choice."},{"t":"Espgaluda","p":["Arcade","Mobile phone","PlayStation 2"],"d":"Cave","u":"AMI","g":"Bullet hell","r":"November 2003","l":"https://en.wikipedia.org/wiki/Espgaluda","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27ks.jpg","s":"A great vertically scrolling manic shooter.\n\nIn an otherwise peaceful world, the Shinra Empire began conquering nearby nations one by one to expand their territory gradually. Meanwhile, in the Shinra weapons lab, the Espgaluda project produced two successful prototypes: Agaha and Tateha. Fearing for their future, the project's head scientist, Hiodoshi, escaped with the two prototypes to a nearby kingdom, but time after were found by Shinra's troops and Hiodoshi was killed by the attack of the imperial army, the power of the galuda has awaken.\n\nYou have the option of controlling one of two siblings each with different skills, Ageha faster but with narrower shooting capabilities or Tateha slower but with a wider attack. As you fly through the various stages various mechanical enemies attack with a high number of bullets, often nearly filling the screen. Aside from the regular shots, Ageha and Tateha also have additional abilities which help the player navigate through the numerous bullets. The first is a guard barrier; when activated the player is immune to collisions and as a bonus when the barrier button is released a more powerful laser shot is fired. A meter at the bottom of the screen indicates how much power is left in the barrier. The second ability is called the Kakusei mode; when this mode is activated your character gender is altered and is able to fire a more powerful shot. More importantly, when this mode is activated all of the enemies and their bullets slow down considerably while the players speed remains the same making it easier to navigate through a tricky pattern of bullets. Activating Kakusei mode will rapidly deplete the players supply of green gems; since the number of gems isn't limitless the player may not be able to remain in Kakusei mode for long. When not in Kakusei mode additional gems can be collected by destroying the various enemies. If the player completely runs out of gems, enemy bullets begin travelling faster than usual. Another bonus in the game is gold inguts which greatly increase the players score. These are found when in Kakusei mode; when an enemy is destroyed, all of its bullets will turn into ingots which can be collected by the player."},{"t":"ESPN College Hoops","p":["PlayStation 2","Xbox"],"d":"Kush Games","u":"Sega","g":"Sports","r":"November 11, 2003","l":"https://en.wikipedia.org/wiki/ESPN_College_Hoops","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/vuf3vh6spqbzzeifnoj5.jpg","s":"\"ESPN College Hoops is an American college basketball video game which was initially released on November 13, 2003 for the Xbox and PS2. It is the sequel to the debut game of the series, NCAA College Basketball 2K3, and the first game in the series to feature the ESPN license. It features former Texas Longhorns and retired NBA guard T. J. Ford on the cover.\""},{"t":"ESPN NBA Basketball","p":["PlayStation 2","Xbox"],"u":"Sega","r":"October 21, 2003","l":"https://en.wikipedia.org/wiki/ESPN_NBA_Basketball_(video_game)"},{"t":"ESPN NFL Football","p":["Xbox","PlayStation 2"],"u":"Sega","r":"September 3, 2003","l":"https://en.wikipedia.org/wiki/NFL_2K"},{"t":"ESPN NHL Hockey","p":["PlayStation 2","Xbox"],"u":"Sega","r":"September 9, 2003","l":"https://en.wikipedia.org/wiki/NHL_2K"},{"t":"Etherlords II","p":["Windows"],"g":"Adventure, Indie, RPG, Strategy","r":"October 1","l":"https://en.wikipedia.org/wiki/Etherlords#Etherlords_II","i":"images/steam-270790.jpg","s":"The saga continues! Etherlords II takes you back to the world of Ether and into a whole new realm of fantastic possibilities. Lead your hero on an unforgettable journey through lands filled with unsurpassed beauty and danger to unlock the ultimate mystery."},{"t":"Eve Online","p":["Windows"],"g":"Action, Massively Multiplayer, RPG, Strategy, Free To Play","r":"May 6","l":"https://en.wikipedia.org/wiki/Eve_Online","i":"images/steam-8500.jpg","s":"Over 20 years of legendary space battles! Explore a massive living universe of danger and opportunity in a challenging and highly rewarding space adventure. Fight, trade, build, and connect with a universe driven and shaped directly by players."},{"t":"Everblue 2","p":["PlayStation 2"],"r":"February 24","l":"https://en.wikipedia.org/wiki/Everblue_2"},{"t":"EverQuest Online Adventures","p":["PlayStation 2"],"d":"Sony Online Entertainment","u":"Sony Online Entertainment, Sony Computer Entertainment","g":"MMORPG","r":"February 11, 2003","l":"https://en.wikipedia.org/wiki/EverQuest_Online_Adventures","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1h66.jpg","s":"In EverQuest Online Adventures, you'll join players around the world in exciting combat, fantastic quests, and character development. Online gameplay allows players to team up and fight together, meet friends, form guilds, and become heroes. Customize your character's race, class, appearance, and abilities, and find secret character enhancements hidden in your environment."},{"t":"EverQuest: Lost Dungeons of Norrath","p":["Windows"],"r":"September 9","l":"https://en.wikipedia.org/wiki/Lost_Dungeons_of_Norrath"},{"t":"EverQuest: The Legacy of Ykesha","p":["Windows"],"r":"February 25"},{"t":"Everybody's Golf 4","p":["PlayStation 2"],"d":"Clap Hanz","u":"Sony Computer Entertainment","g":"Sports","r":"November 27, 2003","l":"https://en.wikipedia.org/wiki/Everybody's_Golf_4"},{"t":"Evil Dead: A Fistful of Boomstick","p":["PlayStation 2","Xbox"],"d":"VIS Entertainment","u":"THQ","g":"Action, hack and slash","r":"May 20, 2003","l":"https://en.wikipedia.org/wiki/Evil_Dead:_A_Fistful_of_Boomstick","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4psd.jpg","s":"Fully \"armed\" with his chainsaw, trusty boomstick, and trademark quips, Ash must once again save Dearborn from the unspeakable horrors spawned from The Book of the Dead. After a vortex to the undead is unwittingly opened, deadites swarm through Dearborn, turning humans into zombies. Now, with Dearborn in chaos and citizens begging for help, Ash must hack and slash his way through the streets and figure out how to close the vortex. Ash soon learns that all is not what it seems--those he trusts may be plotting against him, and the history of Dearborn might be irrevocably changed."},{"t":"Evil Dead: Hail to the King","p":["Windows","Dreamcast","PlayStation"],"r":"April 9"},{"t":"Ex Zeus","p":["Arcade","Windows"],"d":"HyperDevbox Japan, Octopus Studio","u":"HyperDevbox Japan, Metro3D, Conspiracy Entertainment, 505 Games","g":"Rail shooter","r":"May 1, 2003","l":"https://en.wikipedia.org/wiki/Ex_Zeus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48lq.jpg","s":"In 2102 C.E., a giant asteroid enters Earth's orbit, and inside is a horde of aliens led by the entity Diadora, unleashing an invasion on mankind. Hiding deep underground, the surviving rebels create three experimental robots, Sophia, Calista and Dynamis, to combat Diadora's army, the objective codenamed \"Operation ExZeus\". These three robots are humanity's last hope.\n\nExZeus is an on-rails arcade shooter in a third-person perspective. The player can move in all directions while progressing forward, shooting enemies and collecting power-ups and gold. The player has the ability to lock onto enemies and fire powerful missiles at them, and also has a laser (which recharges by itself after every use) they can launch by holding down the fire button. The player can also send out nuclear bombs that destroy all of the enemies on screen, which can also be used to help with bosses.\n\nAt the end of every level, the player faces a boss. Before the fight begins, a screen will display the weaknesses of that boss. Successfully defeating a boss will bring the player to the item shop, where they can buy items to power up their robot, and then proceed to the next level."},{"t":"EyeToy: Groove","p":["PlayStation 2"],"d":"London Studio","u":"Sony Computer Entertainment","g":"Rhythm","r":"November 14, 2003","l":"https://en.wikipedia.org/wiki/EyeToy:_Groove","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coctt4.jpg","s":"In this game, you are given many popular songs to choose from and dance to. Since this is the Eye Toy we are talking about, it is much more interactive. As lights shoot at buttons around the screen, you touch the buttons. Songs include:\n\nMusic by Madonna\nCheeky Holiday by The Cheeky Girls\nMove Your Feet by Junior Senior\nand much, much more."},{"t":"EyeToy: Play","p":["PlayStation 2"],"d":"London Studio","u":"Sony Computer Entertainment","g":"Party","r":"July 4, 2003","l":"https://en.wikipedia.org/wiki/EyeToy:_Play","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2acp.jpg","s":"EyeToy: Play is a video game for the PlayStation 2, released in 2003. It was the first game to make use of the PlayStation 2's video camera accessory, EyeToy. The game was initially packaged with the EyeToy when the accessory was first released. It features twelve mini-games to choose from. This game, and all other EyeToy titles, are played by moving one's body. The motion is detected by the USB camera. The software recognizes pixel changes in the video image and compares the proximity of the change to other game objects to play the game. Users who get a high score get to take a photo to tease other players."},{"t":"F-Zero GX","p":["GameCube"],"u":"Nintendo","r":"July 25, 2003","l":"https://en.wikipedia.org/wiki/F-Zero_GX"},{"t":"F1 Career Challenge","p":["GameCube","Windows","PlayStation 2","Xbox"],"d":"Visual Science, Image Space Incorporated","u":"EA Sports","g":"Racing","r":"June 23, 2003","l":"https://en.wikipedia.org/wiki/F1_Career_Challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2est.jpg","s":"F1 Challenge spans four entire championship seasons and features accurate team, vehicle, and driver data for each."},{"t":"F1 Challenge '99–'02","p":["Windows"],"u":"EA Sports","r":"June 24, 2003","l":"https://en.wikipedia.org/wiki/EA_Sports_F1_series"},{"t":"Fatal Frame II: Crimson Butterfly","p":["PlayStation 2"],"r":"December 10"},{"t":"Federation II","p":[],"d":"Interactive Broadcasting, F2CE","u":"Compunet, GEnie, AOL, independent","g":"Space Fantasy MUD","l":"https://en.wikipedia.org/wiki/Federation_II"},{"t":"FIFA Football 2004","p":["Windows","PlayStation","PlayStation 2","GameCube","Xbox","Game Boy Advance","N-Gage"],"d":"EA Canada, Exient Entertainment","u":"EA Sports","g":"Sports","r":"October 24, 2003","l":"https://en.wikipedia.org/wiki/FIFA_Football_2004"},{"t":"Final Fantasy Tactics Advance","p":["Game Boy Advance"],"u":"Square","r":"February 14, 2003","l":"https://en.wikipedia.org/wiki/Final_Fantasy_Tactics_Advance"},{"t":"Final Fantasy X-2","p":["PlayStation 2"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Final_Fantasy_X-2"},{"t":"Final Fantasy XI","p":["Windows"],"r":"October 28","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XI"},{"t":"Final Fantasy XI: Rise of the Zilart","p":["Windows","PlayStation 2"],"r":"April 17","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XI"},{"t":"Finding Nemo","p":["GameCube","PlayStation 2","Xbox","Game Boy Advance"],"r":"May 12","l":"https://en.wikipedia.org/wiki/Finding_Nemo_(video_game)"},{"t":"Fire Emblem: The Blazing Blade","p":["Game Boy Advance"],"u":"Nintendo","r":"April 25, 2003"},{"t":"FireStarter","p":["Windows"],"d":"GSC Game World","u":"Hip Games","g":"First-person shooter","r":"November 28, 2003","l":"https://en.wikipedia.org/wiki/FireStarter_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co632s.jpg","s":"In the year 2010, a malicious virus has infected a virtual reality machine, the FireStarter. The intruding program has caused the computer to malfunction. The rules of the simulation have been altered in a potentially deadly manner, with the player's consciousness trapped inside. There is only one possible way to escape, by completing the game with a period of 48 virtual hours. The penalty for failing to do so is the ultimate one – real death."},{"t":"Fisherman's Challenge","p":["PlayStation 2"],"d":"Konami","u":"Konami","g":"Sports","r":"January 22, 2003","l":"https://en.wikipedia.org/wiki/Fisherman's_Challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/rtzfqshkazgtaua2drid.jpg","s":"A next-gen upgrade of Fisherman's Bait: A Bass Challenge for the PSOne. This one features five different lakes to fish in, each free-roaming and with seven different types of fish to catch including Catfish, Trout and Bass to name a few. There are a 110 different lures to choose from as well as 100 different rod and reel combinations to choose from. To catch fish the players must hit certain buttons when prompted in order to keep the fish hooked, the larger the fish, the faster and harder the sequences. \n \nThere is even a Fish Mood Meter that gives the player tips on why the fish aren't biting and how to remedy the situation. There is also a two-player mode, where friends can take on each other head-to-head or against an AI opponent in a series of mini-games along with the obligatory career mode."},{"t":"Flatspace","p":[],"l":"https://en.wikipedia.org/wiki/Flatspace"},{"t":"Flipnic: Ultimate Pinball","p":["PlayStation 2"],"d":"Sony Computer Entertainment Japan","u":"Sony Computer Entertainment, Capcom, Ubisoft","g":"Pinball","r":"August 7, 2003","l":"https://en.wikipedia.org/wiki/Flipnic:_Ultimate_Pinball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6tfm.jpg","s":"A pinball game with multiple twists. Flipnic isn't your basic pinball game, it's a psychedelic trip through fantastic land of pinball. The game features multiple tables in which the player must complete a given set of tasks before he or she can proceed to the next level. Each of the \"tables\" consists of many smaller playing areas and every one has some gimmick in them. For example, one must first freeze the waterfall and then destroy the ice and climb a mountain behind it. All this using only the paddles and the ball."},{"t":"Ford Racing 2","p":["PlayStation 2","Xbox","Windows"],"d":"Razorworks","u":"Gotham Games, Empire Interactive, Feral Interactive","g":"Racing","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Ford_Racing_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9c2m.jpg","s":"The sequel to Ford Racing has arrived. Ford Racing 2 has new and improved cars, added tracks and challenges, and more thrills than ever. With an expanded selection of Ford vehicles--ranging from the '49 Ford to the latest Mustang GT Concept--picking out a car will be a lot harder than you expect. Get a feel for each car on a diverse set of tracks including Road Tracks, City Limits, Ovals, Spring Break, and Lost World. Ford Racing 2 is ready to put you in the driver's seat, but are you daring enough to sit there?"},{"t":"Formula One 2003","p":["PlayStation 2"],"d":"Studio Liverpool","u":"Sony Computer Entertainment","g":"Racing","r":"July 11, 2003","l":"https://en.wikipedia.org/wiki/Formula_One_2003_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co72et.jpg","s":"This game is an officially licensed product of the FIA Formula One 2003 championship. It features all the drivers, tracks (including changes), teams and the new qualifying rules and point tables. You can fine-tune almost every aspect of the chosen car to create the best setup for the current track."},{"t":"Freaky Flyers","p":["PlayStation 2","Xbox","GameCube"],"r":"August 5","l":"https://en.wikipedia.org/wiki/Freaky_Flyers"},{"t":"FreeCol","p":["Windows","macOS","Linux"],"g":"Turn-based strategy (TBS)","l":"https://en.wikipedia.org/wiki/FreeCol","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ohj.jpg","s":"FreeCol is a 4X video game, a clone of Sid Meier's Colonization. FreeCol is free and open source software released under the GNU General Public License v2. FreeCol is mostly programmed in Java and should thus be platform-independent."},{"t":"Freedom Fighters","p":["Windows","PlayStation 2","Xbox","GameCube"],"g":"Action","r":"October 1","l":"https://en.wikipedia.org/wiki/Freedom_Fighters_(video_game)","i":"images/steam-1347780.jpg","s":"Freedom Fighters is an intense third-person action game set in an alternate history New York during the invasion of a foreign superpower. Take on the role of Chris Stone, a hard-working plumber, and rise through the ranks of the resistance to prove yourself as a charismatic leader."},{"t":"Freedoom","p":["Windows","Linux","MS-DOS","macOS"],"g":"Shooter","l":"https://en.wikipedia.org/wiki/Freedoom","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3922.jpg","s":"Freedoom is a project aiming to create open content for the free and open source software Doom engine. The project distributes three IWAD files: the two single-player campaigns named Freedoom: Phase 1 and Freedoom: Phase 2, and FreeDM, which contains a collection of deathmatch levels.\n\nThe project presents itself as complementary to the free and open source code of the Doom engine released by id Software in 1997 under the GNU GPL license. The content is licensed under the permissive 3-clause BSD license. It allows custom levels and other customizations designed for Doom, Doom II or Final Doom (e.g. PWAD files) to be used with Freedoom."},{"t":"Freelancer","p":["Windows"],"g":"Indie, Simulation","r":"March 4","l":"https://en.wikipedia.org/wiki/Freelancer_(video_game)","i":"images/steam-2360310.jpg","s":"You earn money by doing various kinds of work that you receive as a &quot;Freelance&quot; over the computer. With the money you earn, you can customize the house, improve yourself, have fun and more."},{"t":"Freestyle MetalX","p":["PlayStation 2","GameCube","Xbox"],"d":"Deibus Studios","u":"Midway Sports Asylum","g":"Sports","r":"June 24, 2003","l":"https://en.wikipedia.org/wiki/Freestyle_MetalX","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2nxd.jpg","s":"Billed as the \"first freestyle motocross\" video game, Freestyle MetalX offers eight go-anywhere environments filled with objects like swimming pools and skyscrapers to trick off. Since there are no limitations imposed on players, they are free to smash windows, plow through parks, and do things that would otherwise be illegal. In addition to riding across real-world locales, players can participate in side events like bus jumping, wheelies, and zipping through tunnels of fire to earn some notoriety and cash for their character. Money can then be used to purchase new equipment including bikes, clothing, accessories, and more.\n\nNine professional riders are available to play as or against, including such legends as Kris \"The Rock\" Rourke and Ronnie \"Kung Fu\" Faisst. Seven generic riders are also selectable, bringing the total lineup of characters to 16. Players must guide these characters through various skill-based challenges in order to unlock the remaining courses. Once unlocked, the eight levels seamlessly connect with one another to form one sprawling environment. Within each region are special events entitled Big Air, Freestyle, Hill Climb, and Race, which typically involve performing as many aerial stunts as possible to outscore the competition.\n\nFreestyle MetalX also features a number of sub-games to add some diversity to the racing action. Players will ride off a cliff to see how many tricks they can perform during their rapid decent, become a human dart while hurling themselves toward an enormous dartboard, and even participate in a game of motocross pinball. Those tired of the existing courses can create their own arena using the built-in level editor. No matter which mode is selected, players can listen to hard-driving music from such bands as Megadeath, Mötley Crüe, Motörhead, and Twisted Sister."},{"t":"Freewar","p":["Browser"],"d":"Jirko Cernik alias Sotrax","u":"Intercyloon","g":"MMORPG","l":"https://en.wikipedia.org/wiki/Freewar"},{"t":"Frogger's Adventures: The Rescue","p":["GameCube","PlayStation 2","Windows"],"d":"Hudson Soft","u":"Konami","g":"Action-adventure","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Frogger's_Adventures:_The_Rescue","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gp1.jpg","s":"'The Rescue' is another game in the storied Frogger franchise. You play as Frogger who must \"hop-n-dodge\" his way through 7 worlds and 25 plus levels. All this in search for his girlfriend. The gameplay follows in its predecessors footsteps with challenging puzzles and enemies. On your quest you will also encounter mini-quests and side stories adding to the fun. In addition to the story mode is a multi-player mode for up to 4 players to compete in action."},{"t":"Frogger's Journey: The Forgotten Relic","p":["Game Boy Advance"],"d":"Konami Computer Entertainment Hawaii","u":"Konami","g":"Action-adventure","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Frogger's_Journey:_The_Forgotten_Relic","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6hh9.jpg","s":"In Frogger's Adventure: Forgotten Relic, join Frogger on a fun-filled journey as he travels across diverse worlds, searches for clues and avoids fierce foes. Featuring Frogger's Famous \"hop-and-dodge\" style gameplay, this game is designed to please players of all ages. There are also some elements that increase the replay of Frogger's Journey: The Forgotten Relic, like the Castlevania: Harmony of Dissonance inspired furniture collection and the multiple paths unlocked by using the increasing abilities of Frogger. The game features almost 20 different levels and RPG-inspired gameplay on top of the classic Frogger formula."},{"t":"From TV Animation - One Piece: Treasure Battle!","p":[],"l":"https://en.wikipedia.org/wiki/From_TV_Animation_-_One_Piece:_Treasure_Battle!"},{"t":"Fugitive Hunter: War on Terror","p":["PlayStation 2"],"u":"Encore, Inc.","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/America%27s_10_Most_Wanted"},{"t":"Full Pipe","p":["Windows"],"d":"Pipe Studio","u":"1C Company, Daedalic Entertainment","g":"Adventure","r":"November 28, 2003","l":"https://en.wikipedia.org/wiki/Full_Pipe"},{"t":"Fullmetal Alchemist and the Broken Angel","p":["PlayStation 2"],"d":"Racjin","u":"Square Enix","g":"Action role-playing","r":"December 25, 2003","l":"https://en.wikipedia.org/wiki/Fullmetal_Alchemist_and_the_Broken_Angel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ovf.jpg","s":"Fullmetal Alchemist and the Broken Angel, is an action role-playing game developed by Racjin and published by Square Enix for the PlayStation 2 console and is the first ever Fullmetal Alchemist video game released. The game features an original story by Hiromu Arakawa. The game was released in Japan on December 25th 2003 and in North America on January 18, 2005."},{"t":"Futurama","p":["PlayStation 2","Xbox"],"r":"August 12","l":"https://en.wikipedia.org/wiki/Futurama_(video_game)"},{"t":"Gakuen Heaven","p":[],"l":"https://en.wikipedia.org/wiki/Gakuen_Heaven"},{"t":"Galactic Civilizations","p":["Windows"],"r":"March 26","l":"https://en.wikipedia.org/wiki/Galactic_Civilizations"},{"t":"Gekkeiju Online","p":["Windows"],"d":"Coolhouse Productions","g":"MMORPG","l":"https://en.wikipedia.org/wiki/Gekkeiju_Online"},{"t":"Gem Smashers","p":["Game Boy Advance"],"d":"Frame Studios","u":"Metro3D, Crave Entertainment, Thumbstar Games, Funbox Media","g":"Puzzle","r":"July 1, 2003","l":"https://en.wikipedia.org/wiki/Gem_Smashers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co60r6.jpg","s":"Many ages ago. The Earth was populated by beings that lived in peace and harmony until a fearsome scientist named IMBU and his henchmen arrived to steal earth's energy, capture all the inhabitants and lock them up in crystal cells. Miraculously, three creatures escaped: BAU, BAM and BOM. They became Gem Smashers, traveling the world to spring, spin, and smash the crystal cells where their friends are imprisoned. It's up to you to help our little heroes survive!"},{"t":"Geneforge 2","p":["macOS","Windows"],"d":"Spiderweb Software","u":"Spiderweb Software","g":"Role-playing","r":"July 25, 2003","l":"https://en.wikipedia.org/wiki/Geneforge_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2176.jpg","s":"Geneforge 2 is a fantasy role-playing epic with a science fiction twist. In Geneforge 2, you explore a huge world, choose which side you will fight for, and make your own horde of completely obedient mutant monsters."},{"t":"Geograficus","p":[],"g":"Adventure, Educational","r":"October 2003","l":"https://en.wikipedia.org/wiki/Geograficus"},{"t":"Geometry Wars: Retro Evolved","p":["Xbox"],"d":"Bizarre Creations","u":"Microsoft Game Studios","g":"Multidirectional shooter","r":"November 17, 2003","l":"https://en.wikipedia.org/wiki/Geometry_Wars:_Retro_Evolved"},{"t":"Ghost Master","p":["Windows"],"g":"Strategy","r":"May 23","l":"https://en.wikipedia.org/wiki/Ghost_Master","i":"images/steam-6200.jpg","s":"Grim spectres, howling banshees, and sly gremlins are yours to command as you unleash ghastly spirits on the town of Gravenville and scare the wits out of its citizens. In the world of the Ghost Master, spooks do your bidding, as you solve puzzles and unlock mysteries in a challenge that combines the best of strategy, adventure, and..."},{"t":"Ghosthunter","p":["PlayStation 2"],"d":"SCEE Cambridge Studio","u":"Sony Computer Entertainment, Namco Hometek, Electronic Arts","g":"Action, third-person shooter","r":"December 3, 2003","l":"https://en.wikipedia.org/wiki/Ghosthunter_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7lfo.jpg","s":"Following the adventures of Lazarus Jones on his first day on the Detroit Police Force, Ghosthunter sees the plucky rookie called in to investigate a disturbance in an old abandoned school, the scene of a grisly (and ultimately unsolved) mass-murder. Heading out with his senior partner Anna Steele, Lazarus sets off on what he believes is a routine call but, in the true spirit of survival horror, it's not long before the crime-bothering duo are knee-deep in ectoplasm. After much bickering between the pair, Jones somehow inadvertently sets free a horde of ghosts contained in the school's secret paranormal research lab. An errant apparition materialises, grabs Anna, and drags her away with him to a dark, eerie place (the school canteen, perhaps?). One of the wayward spooks (Astral) also manages to 'bond' with Jones, giving him the gift of supernatural sight, allowing him to see dead people. Nice. Picking up the reins as Laz, you'll start out in search of Anna, and attempt to figure out the mysteries buried deep in the school's past along the way..."},{"t":"Giftpia","p":["GameCube"],"d":"Skip Ltd.","u":"Nintendo","g":"Adventure","r":"April 25, 2003","l":"https://en.wikipedia.org/wiki/Giftpia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2yml.jpg","s":"Having slept too long and missed his coming of age ceremony, Pockle gets thrown in jail and told that he must repay the 5 million Mane that the ceremony cost. This is so that another can be held, which is required in order for Pockle to reach adulthood."},{"t":"Gladiator: Sword of Vengeance","p":["PlayStation 2","Xbox","Windows"],"d":"Acclaim Studios Manchester","u":"Acclaim Entertainment, Throwback Entertainment","g":"Hack and slash","r":"November 4, 2003","l":"https://en.wikipedia.org/wiki/Gladiator:_Sword_of_Vengeance","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5x7s.jpg","s":"A Warrior Slave… Chosen by the Gods… To restore the glory of an Empire.\n\nIn the Year 106 AD the Roman Empire is in terrible decline. After the untimely death of the much-loved Emperor Trajan, the despotic Emperor Arruntius has bled the once powerful Rome to its knees. Poorly fought wars, famine, and plague are rife in all corners of the Empire, whilst the Emperor and his elite enjoy every excess and vice that the emptying coffers can afford. As herald to this age of degeneration, Arruntius has destroyed large portions of the city of Rome to create the battleground for the bloodiest gladiator event ever staged…"},{"t":"Gladius","p":["GameCube","PlayStation 2","Xbox"],"d":"LucasArts","u":"LucasArts","g":"Tactical role-playing","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Gladius_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q8t.jpg","s":"Gladius is a turn-based gladiatorial RPG. Players try to build a championship gladiator school by gaining experience through fighting battles in the arenas and recruiting new members."},{"t":"Glass Rose","p":["PlayStation 2"],"d":"Cing, Capcom Production Studio 3","u":"Capcom","g":"Point-and-click adventure, psychological horror","r":"November 6, 2003","l":"https://en.wikipedia.org/wiki/Glass_Rose","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5tst.jpg","s":"Time-slip into 1929 to solve the mystery of the Cinema Mansion Serial Murder. But hurry, the death toll is rising and the future could be damaged irrecoverably...\nDynamic pacing, innovative clue and free-speech systems make Glass Rose an adventure game like no other.\n\nWith a supernatural twist and multiple endings, there are many questions, but only one truth..."},{"t":"Go! Go! Hypergrind","p":["GameCube"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Go!_Go!_Hypergrind"},{"t":"Goblin Commander: Unleash the Horde","p":["PlayStation 2","Xbox","GameCube"],"d":"Jaleco Entertainment","u":"Jaleco Entertainment","g":"Action, real-time strategy","r":"November 11, 2003","l":"https://en.wikipedia.org/wiki/Goblin_Commander:_Unleash_the_Horde","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6tup.jpg","s":"Set in a fantasy world, the story follows the tale of a civil war between goblin clans after their creator and master is killed. The gameplay is a combination of real-time strategy and light action where players gather resources and build up their horde of goblins while also being able to take direct control of certain units."},{"t":"Gods and Generals","p":["Windows"],"u":"Activision","r":"March 1, 2003","l":"https://en.wikipedia.org/wiki/Gods_and_Generals_(video_game)"},{"t":"Godzilla: Destroy All Monsters Melee","p":["Xbox"],"r":"April 16"},{"t":"Golden Sun: The Lost Age","p":["Game Boy Advance"],"r":"April 14"},{"t":"Gotcha Force","p":["GameCube"],"r":"December 3","l":"https://en.wikipedia.org/wiki/Gotcha_Force"},{"t":"Gothic II: Night of the Raven","p":["Windows"],"d":"Piranha Bytes","u":"JoWooD Productions","g":"Action role-playing","r":"August 20, 2003","l":"https://en.wikipedia.org/wiki/Gothic_II:_Night_of_the_Raven"},{"t":"Grabbed by the Ghoulies","p":["Xbox"],"d":"Rare","u":"Microsoft Game Studios","g":"Action-adventure, beat 'em up","r":"October 21, 2003","l":"https://en.wikipedia.org/wiki/Grabbed_by_the_Ghoulies","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2xci.jpg","s":"Grabbed by the Ghoulies follows a young man named Cooper Chance who sets out to rescue his girlfriend, Amber, from Ghoulhaven Hall. This mansion is full of supernatural creatures, and Cooper will receive help along the way from the many hired hands that work there."},{"t":"Grand Chase","p":["Windows"],"d":"KOG Studios","u":"Netmarble, Asiasoft, Nexon, Gamania, SG Interactive, Level Up! Games, Megaxus, Kill3rCombo, Axeso5","g":"Action MMORPG","r":"August 2003","l":"https://en.wikipedia.org/wiki/Grand_Chase","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4uhi.jpg","s":"free-to-play, two-dimensional side-scrolling MMORPG."},{"t":"Grand Theft Auto Double Pack","p":["Xbox"],"u":"Rockstar Games","r":"November 4, 2003","l":"https://en.wikipedia.org/wiki/Grand_Theft_Auto#Compilations"},{"t":"Grand Theft Auto III","p":["Xbox"],"r":"November 4","l":"https://en.wikipedia.org/wiki/Grand_Theft_Auto_III"},{"t":"Grand Theft Auto: Vice City","p":["Windows","Xbox"],"u":"Rockstar Games","r":"May 12, 2003"},{"t":"Gregory Horror Show","p":["PlayStation 2"],"d":"Capcom Production Studio 3","u":"Capcom","g":"Survival horror","r":"August 7, 2003","l":"https://en.wikipedia.org/wiki/Gregory_Horror_Show_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coayiy.jpg","s":"A bizarre adventure game that follows the adventures of a main hero named Gregory whose purpose it is to collect lost souls in a haunted mansion. This hotel of the undead is filled with a bizarre group of guests -- along with Gregory and a mischievous little punk kid called James. Your goal is to steal the soul fragment (contained in milk bottles) that each guest holds. Doing so will, as Death informed you, get you out of the hotel, and apparently fill you in on why you were out walking about in the forest in the first place. You obtain the soul fragments by interacting with guests and solving basic puzzles. The game ends when you've run out of spirit as indicated by a spirit meter."},{"t":"Grooverider: Slot Car Thunder","p":["GameCube","Xbox"],"d":"King of the Jungle","u":"Encore, Play It","g":"Racing","r":"September 25, 2003","l":"https://en.wikipedia.org/wiki/Grooverider:_Slot_Car_Thunder","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3yvz.jpg","s":"Slot car racing isn't just for kids anymore. Set in a fantasy penthouse, Grooverider: Slot Car Thunder lets you experience quick lane changes, 360-degree loops, and crazy twists and turns on 20 slot car tracks. If you're a smart racer, you'll be sure to grab extra power-ups for a boost or blasting power. If you're not, then the tracks' spikes, mines, and other booby traps will surely be your downfall. In single- or multiplayer modes, you can get behind the wheel of any racecar, ranging from 1920s British cars to American stock cars"},{"t":"Group S Challenge","p":["Xbox"],"d":"DigitalStudio","u":"Capcom","g":"Racing","r":"August 28, 2003","l":"https://en.wikipedia.org/wiki/Group_S_Challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5tss.jpg","s":"Group S Challenge is a racing game published by Capcom."},{"t":"Growlanser: Wayfarer of Time","p":["PlayStation 2"],"d":"Career Soft","u":"Atlus","g":"Tactical role-playing","r":"December 18, 2003","l":"https://en.wikipedia.org/wiki/Growlanser:_Wayfarer_of_Time"},{"t":"GT Advance 3: Pro Concept Racing","p":["Game Boy Advance"],"r":"February 6"},{"t":"GT Cube","p":["GameCube"],"d":"MTO","u":"MTO","g":"Racing","r":"June 20, 2003","l":"https://en.wikipedia.org/wiki/GT_Cube","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6uds.jpg","s":"GT Cube is a Racing game, published by MTO, which was released in Japan in 2003."},{"t":"Guilty Gear Isuka","p":["Arcade"],"d":"Arc System Works","u":"Sammy Studios, Sourcenext, 505 Games, Zoo Digital Publishing","g":"Fighting","r":"December 17, 2003","l":"https://en.wikipedia.org/wiki/Guilty_Gear_Isuka","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2h9v.jpg","s":"A new Gear arises, its name Leopaldon. As they threaten to lay waste to the world, you prepare to mount your offense. The good news? You won't have to face them alone.\n\nGuilty Gear Isuka introduces the brand new mechanic of cooperative gameplay to the tried and true fighting madness of the Guilty Gear XX series. With support for up to four local players (either on teams or as lone wolves), Guilty Gear has never seen more hectic action.Key FeaturesA Cast of Misfits - The colorful characters of Guilty Gear XX #Reload return for an encore, and are joined by newcomers A.B.A and Robo-Ky Mk. II! On top of the 23 characters available by default, who knows if there are even more waiting to be uncovered...\nBeat-Em-Up Action - Isuka goes from fighter to brawler when you dive into GG Boost Mode. Punch/kick/cut/grapple your way through waves of formidable opponents, and feel free to invite a friend to help; two-player co-op can give you that extra edge you need.\nMake an Abomination - Newcomer Robo-Ky Mk. II can be retrofitted with the moves of other characters, making him the ultimate doppelganger. Brutal command grabs, a projectile or two, almost nothing is verboten when it comes to the murderous art of imitation.\nBeautiful Characters and Environments - From the tiniest bounty hunter to the largest brute, from sunny beaches to moonlit cemetaries, Guilty Gear Isuka's sprite art oozes character.\nJaw-Dropping Heavy Metal Soundtrack - From the mind and frets of Guilty Gear creator Daisuke Ishiwatari comes some of the most intense rock you'll ever roman cancel to. Buyers of Guilty Gear Isuka on Steam will receive a digital copy of the Official Soundtrack for free!"},{"t":"Gunfighter II: Revenge of Jesse James","p":["PlayStation 2"],"d":"Rebellion Developments","u":"Ubi Soft","g":"Rail shooter","r":"March 14, 2003","l":"https://en.wikipedia.org/wiki/Gunfighter_II:_Revenge_of_Jesse_James","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/uxmwjrigs5xg8emcj2om.jpg","s":"Gunfighter II: Revenge of Jesse James is the second game in the Gunfighter light gun series."},{"t":"GunZ: The Duel","p":["Windows"],"d":"MAIET Entertainment","u":"MAIET Entertainment, Netmarble, Aeria Games and Entertainment, Level Up! Games","g":"Third-person shooter","r":"June 2003","l":"https://en.wikipedia.org/wiki/GunZ:_The_Duel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2k41.jpg","s":"GunZ: The Duel is an online third-person shooting game. The game allowed players to perform exaggerated, gravity-defying moves, including wall running, stunning, tumbling, and blocking bullets with swords, in the style of action films and anime."},{"t":"Hamtaro: Rainbow Rescue","p":["Game Boy Advance"],"d":"AlphaDream, Graphic Research","u":"Nintendo","g":"Adventure","r":"May 23, 2003","l":"https://en.wikipedia.org/wiki/Hamtaro:_Rainbow_Rescue","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4kr2.jpg","s":"One day while playing outside, Bijou witnesses a great rainbow. The rainbow disappears and Prince Bo falls to the ground. The Prince states that he can make rainbows by using his umbrella. He tries to prove it to disbelieving Stan and the rest of the Ham-Hams, but realizes too late that the colors on his umbrella are gone. And thus, Hamtaro and his Ham-Ham friends must set off on a journey in order to collect things that are the proper color for Prince Bo to use for his umbrella so he can create a rainbow to return home."},{"t":"Harbinger","p":["Windows"],"d":"Silverback Entertainment","u":"DreamCatcher Interactive","g":"Role-playing","r":"February 25, 2003","l":"https://en.wikipedia.org/wiki/Harbinger_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7cow.jpg","s":"A huge ship, known as the Harbinger, enters a solar system destroying planets and civilizations in its path. Survivors are taken aboard the havoc-wreaking ship to work in labor camps, or be unluckily sent off to the laboratories for vicious tests and experiments that often lead to insanity. Few have managed to escape into the deep, forgotten wasteland levels of the ship, where an underground society exists. They search for a means of escape while fighting for their survival with anything they can scavenge as they attempt to ward off the relentless patrols sent for them."},{"t":"Hard Rock Casino","p":["Windows"],"d":"MumboJumbo, Jamdat Mobile, FarSight Studios","u":"Jamdat Mobile, MacPlay, Crave Entertainment, Oxygen Games","g":"Gambling","l":"https://en.wikipedia.org/wiki/Hard_Rock_Casino_(video_game)"},{"t":"Hardware: Online Arena","p":["PlayStation 2"],"d":"London Studio","u":"Sony Computer Entertainment","g":"Vehicular combat","r":"November 7, 2003","l":"https://en.wikipedia.org/wiki/Hardware:_Online_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4lqv.jpg","s":"Hardware: Online Arena is an online multiplayer game that focuses on vehicular destruction using varying means such as missiles, lasers and machine guns. The game was released for PlayStation 2 with the launch of online play for the console and was possibly the first online game for PS2. The game was not a huge commercial success, selling very little. Later the game was added onto the network access disk that comes when you buy the network adaptor and during 2005 was one of the three most popular games played online having over 200 users on at any one time."},{"t":"Harry Potter and the Philosopher's Stone","p":["GameCube","PlayStation 2","Xbox"],"d":"Warthog Games","u":"Electronic Arts","g":"Action-adventure","r":"December 12, 2003","l":"https://en.wikipedia.org/wiki/Harry_Potter_and_the_Philosopher's_Stone_(2003_video_game)"},{"t":"Harry Potter: Quidditch World Cup","p":["Windows","GameCube","PlayStation 2","Xbox","Game Boy Advance"],"r":"October 28"},{"t":"Harvest Moon: A Wonderful Life","p":["GameCube"],"d":"Marvelous Interactive","u":"Marvelous Interactive, Natsume Inc., 505 Game Street, Marvelous","g":"Simulation, role-playing","r":"September 12, 2003","l":"https://en.wikipedia.org/wiki/Harvest_Moon:_A_Wonderful_Life","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ae6.jpg","s":"Harvest Moon: A Wonderful Life will span a lifetime on the farm and follow the drama that goes with it. Not only must you build and successfully run a farm, but you must also build a successful life with family and friends! This new Harvest Moon experience will take the best qualities of the series and add more...more animals, more vegetables and more drama! What sort of life will you live?"},{"t":"Harvest Moon: Friends of Mineral Town","p":["Game Boy Advance"],"r":"November 17"},{"t":"Heat Project","p":["Windows"],"d":"DOOBIC Entertainment","u":"22px|South Korea ParanGAME, 22px|Republic of China 22px|Hong Kong Gamania, 22px|People's Republic of China Asia Eastern","g":"First-person shooter/Role-playing video game","r":"May 14, 2003","l":"https://en.wikipedia.org/wiki/Heat_Project"},{"t":"Heaven and Hell","p":["Windows"],"d":"MadCat Interactive","u":"CDV Software","g":"Real-time strategy, god game","r":"June 27, 2003","l":"https://en.wikipedia.org/wiki/Heaven_and_Hell_(video_game)"},{"t":"Hexic","p":["Windows"],"d":"Carbonated Games, Astraware, Other Ocean","u":"Microsoft Game Studios","g":"Puzzle","r":"July 2003","l":"https://en.wikipedia.org/wiki/Hexic","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaltq.jpg","s":"Designed by Alexey Pajitnov, best known as the original creator of Tetris. It was originally released on the MSN Games service in July 2003, later it came pre-installed on the Xbox 360, and further down the line MumboJumbo released a retail version for the PC called Hexic Deluxe."},{"t":"Hidden & Dangerous 2","p":["Windows"],"d":"Illusion Softworks","u":"Gathering","g":"Tactical shooter","r":"October 23, 2003","l":"https://en.wikipedia.org/wiki/Hidden_&_Dangerous_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1q6k.jpg","s":"Hidden and Dangerous 2, like its predecessor, focuses on the British Special Air Service during the Second World War. It follows the same concept as the original tactical first/third person shooter. The game's LS3D engine was used by the game Mafia.\nGameplay elements such as the vocal commands, plan or real-time map control, vehicle usage, equipment selection and the first person mechanic were significantly enhanced from the original. The ability to take POWs, added enhanced stealth options for the player which include the acquisition of enemy uniforms. Mission types include, espionage, sabotage, search and destroy, town liberation, prisoner rescue, retrieval of enemy officers and documents, partisan assistance and assassination. The variety of locales include Norway, Libya, a Norwegian fjord, Burma, Austria, France and Czechoslovakia.\n\nThe expansion pack Sabre Squadron adds missions in France, Libya and Sicily. Some of the missions are modeled on real SAS exploits. However most of the game takes liberty with the historical time and place of SAS operations.[6] The missions are based on sandbox style game-play where players are free to roam a map and pursue objectives usually at their leisure and choice of sequence. A real time strategy mechanic also allows players to control events for staged sequential tactical maneuvers or through real time overhead command."},{"t":"High Heat Major League Baseball 2004","p":["PlayStation 2","Windows","Xbox"],"d":"The 3DO Company","u":"The 3DO Company","g":"Sports","r":"February 19, 2003","l":"https://en.wikipedia.org/wiki/High_Heat_Major_League_Baseball_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co74xz.jpg","s":"High Heat has always been generous with features in its PC incarnation, and the console version has finally caught up to it. Boasting eleven different modes of play, HH 2004 takes several steps beyond the product offered last year and genuinely tries rather hard to push feature diversity. All the classics are here: Home Run Derby, Exhibition, All-Star Games, Batting Practice, Player Editing devices, and other such goodies await the gamers who patiently explore its every area. Perfect for two-player matches, Two-on-Two Showdown returns from last year's PS2 version and presents itself as a console-exclusive option (you're not going to find it in the GBA or PC versions at all)."},{"t":"Highland Warriors","p":["Windows"],"d":"Soft Enterprises","u":"Data Becker","g":"Real-time strategy, history","r":"January 20, 2003","l":"https://en.wikipedia.org/wiki/Highland_Warriors","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co292c.jpg","s":"In the year of our lord 843, the first king of Scotland, Kenneth McAlpin, united the lands of the Picts and Scots to form the Kingdom of Alba. 400 years later Edward I, also known as the \"Hammer of the Scots\" engulfed the land in a great feud. It was not long before Edward I controlled most of Scotland. The Scots, led by William Wallace and Robert the Bruce, are left to fight what seems to be a futile war for freedom. This is the time when legends are born..."},{"t":"Highway Pursuit","p":["Windows"],"d":"Adam Dawes/Retrospec","u":"Adam Dawes/Retrospec","g":"Racing game","r":"November 12, 2003","l":"https://en.wikipedia.org/wiki/Highway_Pursuit","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co600r.jpg","s":"Highway Pursuit is a modern game taking its inspiration from a number of classic arcade games.\n\nIt's an action-packed 3d blast along roads filled with enemy agents -- but also with innocent civilians that you should protect at all costs.\n\nFeaturing diverse landscapes and scenery, a variety of enemy vehicles, multiple weapons, weather effects, radio communications from your HQ, 3d sound effects, configurable support for keyboard, joysticks and steering wheels, Highway Pursuit is a road trip you shouldn't miss!"},{"t":"Homeworld 2","p":["Windows"],"r":"September 16","l":"https://en.wikipedia.org/wiki/Homeworld_2"},{"t":"Hot Wheels: World Race","p":["PlayStation 2","GameCube","Windows","Game Boy Advance"],"d":"Climax Brighton","u":"THQ","g":"Racing","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Hot_Wheels:_World_Race_(video_game)"},{"t":"Hoyle Majestic Chess","p":["Windows"],"d":"Fluent Entertainment","u":"Sierra Entertainment, JoWooD Productions","g":"Computer chess","r":"September 8, 2003","l":"https://en.wikipedia.org/wiki/Hoyle_Majestic_Chess","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7pmb.jpg","s":"A chess game with a heavy fantasy theme; the player travels across a map and follows quests that show you how to properly play chess."},{"t":"HSX: Hypersonic.Xtreme","p":["PlayStation 2"],"r":"January 26","l":"https://en.wikipedia.org/wiki/G-Surfers"},{"t":"Hugo: Bukkazoom!","p":["Windows","PlayStation 2"],"d":"ITE Media","u":"ITE Media, Namco","g":"Racing","l":"https://en.wikipedia.org/wiki/Hugo:_Bukkazoom!"},{"t":"Hulk","p":["Windows","PlayStation 2","GameCube","Xbox"],"r":"May 28","l":"https://en.wikipedia.org/wiki/Hulk_(video_game)"},{"t":"Hunter: The Reckoning – Redeemer","p":["Xbox"],"d":"High Voltage Software","u":"Vivendi Universal Games","g":"Hack and slash, third-person shooter","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Hunter:_The_Reckoning_%E2%80%93_Redeemer"},{"t":"Hunter: The Reckoning – Wayward","p":["PlayStation 2"],"d":"High Voltage Software","u":"Vivendi Universal Games","g":"Hack and slash, third-person shooter","r":"September 9, 2003","l":"https://en.wikipedia.org/wiki/Hunter:_The_Reckoning_%E2%80%93_Wayward"},{"t":"Hyper Street Fighter II","p":["PlayStation 2"],"d":"Capcom","u":"Capcom","g":"Fighting","r":"December 18, 2003","l":"https://en.wikipedia.org/wiki/Hyper_Street_Fighter_II"},{"t":"I-Ninja","p":["PlayStation 2","GameCube","Xbox"],"d":"Argonaut Games","u":"Namco Hometek, Sony Computer Entertainment, Zoo Digital Publishing","g":"Platform","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/I-Ninja","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jop.jpg","s":"I Ninja is a 3D platform title starring an original character created by British developer Argonaut Software. Players control a spirited young ninja as they make their way through a diverse selection of indoor and outdoor locales. The title character is garbed in a blue suit and matching hooded mask, so that only his eyes and his expressive brow are visible to players. The character also wields a pair of katana blades in both hands as he jumps from platform to platform, avoiding hazards and slicing at enemies. The cartoon-style atmosphere is brought to life with the use of cel-shaded graphics, giving the game a distinctive look from many of its platform contemporaries.\n\nI-Ninja is an adrenaline-charged adventure game. An ultra-cool ninja with major attitude meets extreme sports game play, I-Ninja is the consummate warrior who has spent years mastering his weapons and honing his skills. In true gravity defying game play, I-Ninja can scale buildings, \"shred\" on extreme rails, hover great distances with a \"sword copter\", ride drifting roller spheres and utilize specialized manga-style ninja moves to navigate through each dynamic environment."},{"t":"I.G.I.-2: Covert Strike","p":["Windows"],"r":"February 21"},{"t":"Ichigeki Sacchu!! HoiHoi-san","p":["PlayStation 2"],"g":"Shooter","l":"https://en.wikipedia.org/wiki/Ichigeki_Sacchu!!_HoiHoi-san","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5mwc.jpg","s":"A Japan-only third person action game where you play as a tiny robot doll on a mission to exterminate bugs."},{"t":"IHRA Drag Racing 2004","p":["Xbox"],"d":"Super Happy Fun Fun","u":"Bethesda Softworks","g":"Racing","r":"November 2003","l":"https://en.wikipedia.org/wiki/IHRA_Drag_Racing_2004"},{"t":"IHRA Drag Racing: Multiplayer","p":["Mobile phone"],"d":"Vir2L Studios","u":"Mforma","g":"Racing","r":"June 2003","l":"https://en.wikipedia.org/wiki/IHRA_Drag_Racing:_Multiplayer"},{"t":"Ikaruga","p":["GameCube"],"r":"April 15","l":"https://en.wikipedia.org/wiki/Ikaruga"},{"t":"IL-2 Sturmovik: Forgotten Battles","p":["Windows"],"d":"1C: Maddox Games","u":"1C, Ubi Soft","g":"Combat flight simulator","r":"March 4, 2003","l":"https://en.wikipedia.org/wiki/IL-2_Sturmovik:_Forgotten_Battles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yc6.jpg","s":"IL-2 Sturmovik: Forgotten Battles is a combat flight simulator video game, and sequel to the 2001 combat flight simulation of the year IL-2 Sturmovik. Unlike the first instalment, Forgotten Battles focuses on the Soviet-Finnish Continuation War of 1941-1944."},{"t":"Impossible Creatures","p":["Windows"],"d":"Relic Entertainment","u":"Microsoft Game Studios","g":"Real-time strategy","r":"January 7, 2003","l":"https://en.wikipedia.org/wiki/Impossible_Creatures","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21a0.jpg","s":"Genetically-alter animals to create scientific marvels in \"Impossible Creatures\", the 2003 classic RTS. Taking place in a fictional 1930's setting, take down evil villains in the single player campaign or challenge other players online in multiplayer.\n\nCreate combined creatures from a selection of stock animals' genetic samples. Many animals possess inherent abilities to add more strategic depth to the game. There is an extensive single-player campaign as well as online multiplayer functionality with different game modes, add-ons, custom maps, mods, and scenarios.\n\nOn November 12th 2015 Impossible Creatures was released on Steam as Impossible Creatures: Steam Edition, by Nordic Games. The Steam version includes all patches and expansion packs released in the past, the IC Online servers reimplemented through Steam's cloud service and the game's modding SDK included in the package alongside the Mission Editor originally available within the game's files; potential Steam Workshop support is in the works. The Steam Edition is also optimized for modern computer systems and software."},{"t":"In Memoriam","p":["Windows","macOS"],"d":"Lexis Numérique","u":"Ubi Soft, The Adventure Company","g":"Adventure, puzzle","r":"October 16, 2003","l":"https://en.wikipedia.org/wiki/In_Memoriam_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/zc4xtzu3iblzso9ox4km.jpg","s":"Missing (also known as \"In Memoriam\" in Europe) is a single player Alternate Reality Game. The story revolves around the disappearance of journalist Jack Lorski and his friend Karen Gijman. Jack and Karen had been investigating a series of murders."},{"t":"Indiana Jones and the Emperor's Tomb","p":["Xbox","Windows","PlayStation 2"],"r":"February 24","l":"https://en.wikipedia.org/wiki/Indiana_Jones_and_the_Emperor%27s_Tomb"},{"t":"IndyCar Series","p":["PlayStation 2","Xbox","Windows"],"d":"Brain in a Jar","u":"Codemasters","g":"Racing","r":"May 20, 2003","l":"https://en.wikipedia.org/wiki/IndyCar_Series_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/jhhqysrcryyzvfp9dnq6.jpg","s":"Codemasters' official game, IndyCar Series, is blisteringly fast, nerve-shatteringly intense, pure professional racing and features ultra-close pack racing with up to 33 cars racing on track. Gameplay requires total focus to handle the incredible overtaking manoeuvres at speeds well over 220 mph. IndyCar Series delivers a full racing season, which includes the Indianapolis 500-Mile Race (Indy 500), the greatest spectacle in US racing."},{"t":"Inside Pitch 2003","p":["Xbox"],"r":"May 20"},{"t":"Inspector Gadget Racing","p":["Game Boy Advance"],"d":"Bit Managers","u":"Light & Shadow Production","g":"Racing","r":"February 28, 2003","l":"https://en.wikipedia.org/wiki/Inspector_Gadget_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8gj2.jpg","s":"Inspector Gadget Racing is a Racing game, developed by Bit Managers and published by LSP, which was released in Europe in 2003."},{"t":"Inspector Gadget: Mad Robots Invasion","p":["PlayStation 2"],"d":"Silmarils","u":"Light and Shadow Production","g":"Action","l":"https://en.wikipedia.org/wiki/Inspector_Gadget:_Mad_Robots_Invasion","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qfd.jpg","s":"Dr. Claw continues his quest for world domination. He dreams of a world completely ruled by his super-powerful robots that are indestructible and fitted with highly advanced artificial intelligence!. To carry on his plan without interference, Dr. Claw has to first kidnap Penny and Brain to diver the attentions of Inspector Gadget. Now it is up to you! Become Inspector Gadget, free your friends and save the world from Dr. Claws evil clutches."},{"t":"Interlude","p":["PlayStation 2","Dreamcast"],"g":"Visual Novel","l":"https://en.wikipedia.org/wiki/Interlude_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co62mk.jpg","s":"A NEC Interchannel published visual novel released first on the Dreamcast and then later on the PlayStation 2 in Japan."},{"t":"International Superstar Soccer 3","p":["PlayStation 2","GameCube","Windows"],"d":"KCEO","u":"Konami","g":"Sports","r":"March 28, 2003","l":"https://en.wikipedia.org/wiki/International_Superstar_Soccer_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ty8.jpg","s":"Come and be a part of Football. Feel the nerves in the tunnel and the excitement on the pitch. Immerse yourself with intuitive gameplay and realism for total footballing action. Experience the all new one-on-one situations and live the game. Pull off some amazing skills that really are pure football."},{"t":"Interstellar Trader 2","p":["Windows"],"u":"Shrapnel Games","r":"March 21, 2003"},{"t":"Iridion II","p":["Game Boy Advance"],"r":"May 12","l":"https://en.wikipedia.org/wiki/Iridion_II"},{"t":"Istaria: Chronicles of the Gifted","p":["Windows"],"d":"Virtrium LLC","u":"Virtrium LLC","g":"Massively multiplayer online role-playing","r":"December 5, 2003","l":"https://en.wikipedia.org/wiki/Istaria:_Chronicles_of_the_Gifted","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co256e.jpg","s":"Originally released as 'Horizons: Empire of Istaria', Istaria is unique among MMORPGs in that players may choose a dragon for their avatar. Istaria allows players to build non-instanced player communities with either multi-level underground dragon chambers or ground level communities."},{"t":"Itaike na Kanojo","p":["Windows"],"d":"Zero","u":"Visual Art's, AiCherry","g":"Eroge, Visual novel","r":"October 24, 2003","l":"https://en.wikipedia.org/wiki/Itaike_na_Kanojo"},{"t":"Jak II","p":["PlayStation 2"],"u":"Sony Computer Entertainment","r":"October 14, 2003","l":"https://en.wikipedia.org/wiki/Jak_II"},{"t":"Jawbreaker","p":["Mobile phone","Windows"],"d":"Oopdreams software, Inc.","u":"Microsoft","g":"Puzzle games","r":"April 7, 2003","l":"https://en.wikipedia.org/wiki/Jawbreaker_(Windows_Mobile_game)"},{"t":"Jet Grind Radio","p":["Game Boy Advance"],"d":"Vicarious Visions, Smilebit","u":"THQ, Sega","g":"Action, platform","r":"June 26, 2003","l":"https://en.wikipedia.org/wiki/Jet_Grind_Radio_(2003_video_game)"},{"t":"JetFighter V: Homeland Protector","p":["Windows"],"d":"InterActive Vision","u":"Global Star Software","g":"Simulator","r":"October 21, 2003","l":"https://en.wikipedia.org/wiki/JetFighter_V:_Homeland_Protector","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ybe3anmefib4jjpjtxrl.jpg","s":"Jetfighter V: Homeland Protector is a combat flight simulator video game developed by Polish studio Interactive Vision and published by Global Star Software in 2003."},{"t":"Jinx","p":["PlayStation"],"d":"HammerHead","u":"Sony Computer Entertainment","g":"Platform","r":"January 31, 2003","l":"https://en.wikipedia.org/wiki/Jinx_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8uru.jpg","s":"Jinx is a 3D platformer for the PlayStation in the vein of other 3D platformers like Spyro the Dragon. The main character Jinx, a court jester, is tasked with finding and rescuing the royal family he works for since it has been kidnapped by Gripply the Pirate King, leaving the realm into a state of chaos. The player has to traverse various different worlds and locations in pursuit of Gripply, while facing a number of enemies, solving puzzles and collecting items. The graphics are notable for being very colourful."},{"t":"Journey to the Center of the Earth","p":["Windows"],"d":"Frogwares","u":"Micro Application","g":"Graphic adventure","r":"October 16, 2003","l":"https://en.wikipedia.org/wiki/Journey_to_the_Center_of_the_Earth_(2003_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24o3.jpg","s":"Ariane, a young reporter, is suddenly swallowed by the earth while covering a story near the Sneffels volcano. When she awakens, she discovers the strangest landscapes and a host of unusual objects. Join Ariane as she explores an unkown world of fascinating and fantastical civilizations hidden beneath the surface of the Earth. Inspired by the Jules Verne classic!"},{"t":"Judge Dredd: Dredd vs. Death","p":["Windows","PlayStation 2","Xbox","GameCube"],"g":"Action","r":"October 17","l":"https://store.steampowered.com/app/3710","i":"images/steam-3710.jpg","s":"Welcome to Mega-City One, a city of over 400 million people - every one of them a potential criminal. It is the third decade of the 22nd Century, unemployment is widespread, boredom is universal and only the Judges can prevent total anarchy. Empowered to dispense instant justice, they are Judge, Jury and Executioner all in one."},{"t":"Jurassic Park: Operation Genesis","p":["Windows","PlayStation 2","Xbox"],"r":"March 10"},{"t":"Justice League: Chronicles","p":["Game Boy Advance"],"d":"Full Fat","u":"Midway Home Entertainment","g":"Beat 'em up","r":"November 10, 2003","l":"https://en.wikipedia.org/wiki/Justice_League:_Chronicles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ycu.jpg","s":"Justice League: Chronicles is a video game based on Justice League. It was released on November 12, 2003. This game has three levels; each level has two characters. In the first stage, they are Green Lantern and Flash; in the second, Batman and Hawkgirl; and in the last, Superman and Wonder Woman."},{"t":"Kao the Kangaroo: Round 2","p":["Windows","GameCube","PlayStation 2","Xbox"],"d":"Tate Interactive","u":"Cenega, JoWooD Productions, Atari","g":"Action-adventure, platform","r":"November 4, 2003","l":"https://en.wikipedia.org/wiki/Kao_the_Kangaroo:_Round_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coayor.jpg","s":"Play as Kao! The cutest and bravest kangaroo of all video games returns.\nExperience the joy of playing a classic 3D single-player platformer filled with various challenges, including fighting, racing and solving puzzles.\nBounce through 25 levels set in 5 unique, colorful worlds to rescue your animal friends captured by the evil Hunter and his henchmen!"},{"t":"Karaoke Revolution","p":["PlayStation 2","Xbox","GameCube"],"d":"Harmonix, Secret Level, Inc., Blitz Games, Hijinx Studios","u":"Konami","g":"Rhythm","l":"https://en.wikipedia.org/wiki/Karaoke_Revolution"},{"t":"Karaoke Revolution","p":["PlayStation 2"],"d":"Harmonix, Secret Level, Inc.","u":"Konami","g":"Music","r":"November 5, 2003","l":"https://en.wikipedia.org/wiki/Karaoke_Revolution_(2003_video_game)"},{"t":"Kasparov Chessmate","p":["Windows","macOS","Mobile phone"],"d":"The Learning Company","u":"Jamdat Mobile","g":"Computer chess","l":"https://en.wikipedia.org/wiki/Kasparov_Chessmate","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ixtuznehwgosu849grby.jpg","s":"The game is backed by grand chessmaster, Garry Kasparov.\nPlayers can create a personal profile using their own name, MSN nickname for online/network play, country and a facial icon.\nSelect a side black or white and game type: \"Local\" against the computer or other human to either no time limit or specified; \"Online\" via MSN Game Zone or over a computer network; and \"Kasparov Chess Club\" of 45 club members in a single \"exhibition\" game versus any member or \"championship\" to become Club Champion against all members each has different abilities and ratings ranging from Bronze to Gold with \"hints\" available during play.\nActual play has accessible \"history\" record of all movement, option to \"resign\" or \"draw\" a game. The chessboard is viewable in 2D or 3D and styled as Staunton Black & White, Staunton Rosewood or Modern set with notation in algebraic or figurine. Movement is instant or adjustable by a slide for fast or slower paced game.\nFor a novice unfamiliar with Chess, the \"training\" (tutorial) segment covers basic rules of play to winning. Strategies for openings and defenses to middle/end games. Useful tips, possible traps and problems.\nReview a selection of 64 historical games played by the grandmaster himself, Kasparov including famous matches against various top chess players to IBM's supercomputer Deep Blue.\nInstall or synchronize the game using a handheld device: Palm OS 3.5 or PocketPC docked in the cradle from Windows PC CD-ROM."},{"t":"Kenshin Dragon Quest","p":[],"d":"SSD Co.","u":"Square Enix","g":"Adventure","r":"September 19, 2003","l":"https://en.wikipedia.org/wiki/Kenshin_Dragon_Quest"},{"t":"Ketsui: Kizuna Jigoku Tachi","p":["Arcade"],"d":"Cave","u":"AMI, Arika, 5pb., M2","g":"Manic shooter","r":"January 28, 2003","l":"https://en.wikipedia.org/wiki/Ketsui:_Kizuna_Jigoku_Tachi"},{"t":"Kill Switch","p":["PlayStation 2","Xbox"],"d":"Namco Hometek, Visual Impact","u":"Namco Hometek, Sony Computer Entertainment","g":"Third-person shooter","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Kill_Switch_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co57c7.jpg","s":"Aiming and moving in cover and blind-fire modes is tricky, though. To gain the 3-D effect, some detail gets sacrificed. Usually this is no problem, but occasionally you'll have a tough time recognizing an object. You move from area to area to engage a new group of enemies. You'll conveniently find crates for cover and barrels to help you pull off big explosions. Locking the enemy in your crosshairs, signified by your crosshairs turning red, doesn't guarantee a direct hit? The accuracy depends on the weapon of choice. A shotgun will normally provide a kill on the first shot. If you have an automatic rifle, your shots are relatively inaccurate even if your aim is true."},{"t":"Kingdom of Loathing","p":["Browser"],"d":"Asymmetric Publications","u":"Asymmetric Publications","g":"Turn-based role-playing game","r":"February 10, 2003","l":"https://en.wikipedia.org/wiki/Kingdom_of_Loathing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rmq.jpg","s":"Kingdom of Loathing is a browser-based role-playing game."},{"t":"Kino's Journey","p":[],"l":"https://en.wikipedia.org/wiki/Kino's_Journey"},{"t":"Kirby Air Ride","p":["GameCube"],"r":"October 13","l":"https://en.wikipedia.org/wiki/Kirby_Air_Ride"},{"t":"Knight Rider: The Game","p":["Windows","PlayStation 2"],"r":"February 12"},{"t":"Knights of Valour: The Seven Spirits","p":[],"l":"https://en.wikipedia.org/wiki/Knights_of_Valour:_The_Seven_Spirits"},{"t":"Kollon","p":["Arcade"],"d":"MagicPot","u":"CyberFront, Conspiracy Entertainment, 505 Games","g":"Puzzle","l":"https://en.wikipedia.org/wiki/Kollon"},{"t":"Korea: Forgotten Conflict","p":["Windows"],"d":"Plastic Reality Technologies","u":"Cenega Publishing","g":"Real-time strategy, Stealth","r":"November 2, 2003","l":"https://en.wikipedia.org/wiki/Korea:_Forgotten_Conflict","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7mxn.jpg","s":"A stealth game based on the Commandos gameplay style of interdependent characters solving puzzles based mainly on stealth. The player receives a number of commandos each mission and they have some special abilities (medic, sniper, engineer, spy and assassin), with the main gameplay focusing on inventory management and basic combat. Stealth is rudimentary and doesn't affect the mission beyond enemies trying to attack the player's units"},{"t":"Kreed","p":["Windows"],"d":"Burut Creative Team","u":"Russobit-M","g":"First-person shooter","r":"August 29, 2003","l":"https://en.wikipedia.org/wiki/Kreed_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3mss.jpg","s":"In the year 2944 humanity is still at war with the Tiglaary and a strange anomaly named Kreed gives the scientists riddles they can't solve. Some religious groups believe the Kreed is a higher being and many of them try to enter it. One day they finally succeed and under the command of Teofrast Rumi, a high ranking officer, a ship full of fanatics makes his way into the anomaly. As a soldier of the legion, you and your colleagues aboard the spaceship Aspero are sent after him."},{"t":"Kung Fu Chaos","p":["Xbox"],"d":"Just Add Monsters","u":"Microsoft Game Studios","g":"Fighting, party","r":"February 25, 2003","l":"https://en.wikipedia.org/wiki/Kung_Fu_Chaos","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co62rt.jpg","s":"Kung Fu Chaos is an entertaining brawler game inspired by the 70s Kung Fu movie era. You fight as one of nine characters--three of which are unlockable--with looks, moves, and taunts based on kung-fu movie icons. Your quest for movie stardom places you on a dynamic movie set, and when the director yells \"Action!\" you fight against multiple enemies either by yourself or with three friends. Perform over-the-top, Hong-Kong-style combat--including leaps, and flying kicks--and you'll become a star in no time."},{"t":"Kya: Dark Lineage","p":["PlayStation 2"],"r":"November 18"},{"t":"La Terre","p":["Windows"],"d":"Microïds","u":"Microïds","l":"https://en.wikipedia.org/wiki/La_Terre_(video_game)"},{"t":"Laden VS USA","p":[],"d":"Panyu Gaming Electronic Co.","u":"Panyu Gaming Electronic Co.","g":"Shooter game","l":"https://en.wikipedia.org/wiki/Laden_VS_USA"},{"t":"Law & Order: Double or Nothing","p":["Windows"],"d":"Legacy Interactive","u":"Legacy Interactive, The Adventure Company","g":"Adventure","r":"October 1, 2003","l":"https://en.wikipedia.org/wiki/Law_&_Order:_Double_or_Nothing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8t1n.jpg","s":"The second point and click adventure based upon the popular TV series. A renowned scientist is found murdered in his car. It is up to you to find the murderer and put together a good enough case to nail the guilty verdict."},{"t":"Legacy of Kain: Defiance","p":["Windows","PlayStation 2","Xbox"],"r":"November 11"},{"t":"Legend of Zord","p":["Windows"],"d":"Imaginations FZ LLC","u":"BMS Modern Games Handelsagentur GmbH, Imaginations FZ LLC, enjoy Software & Entertainment GmbH, Media-Service 2000","g":"Action-adventure","l":"https://en.wikipedia.org/wiki/Legend_of_Zord","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9pb1.jpg"},{"t":"Line of Sight: Vietnam","p":["Windows"],"d":"NFusion","u":"Infogrames Interactive, Atari Europe","g":"Tactical shooter","r":"March 5, 2003","l":"https://en.wikipedia.org/wiki/Line_of_Sight:_Vietnam","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3w1m.jpg","s":"Every day brings another mission. Every day is LIFE or DEATH. Be quick, be quiet and be careful. That’s what will get you HOME ALIVE."},{"t":"Lineage II","p":["Windows"],"d":"NCSoft, E&G Studios","u":"NCSoft","g":"Massively multiplayer online role-playing","r":"October 1, 2003","l":"https://en.wikipedia.org/wiki/Lineage_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1nhg.jpg","s":"Lineage II. The legend that started it all. MMORPG with a huge open world and a variety of social features. Become a powerful warrior, play a new class (the Death Knight) and join the fight for dominance!"},{"t":"Links 2004","p":["Xbox"],"d":"Salt Lake Games Studio","u":"Microsoft Game Studios","g":"Sports","r":"November 11, 2003","l":"https://en.wikipedia.org/wiki/Links_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coazzc.jpg","s":"Links, the best-selling golf franchise for the personal computer, has been rebuilt—from the ground up—exclusively for the Xbox video game system. Links 2004 delivers one of the most realistic and competitive golf experiences for Xbox. Golf fans worldwide can compete online in friendly matches with old golfing buddies or compete in tournaments against the best golfers in the world via Xbox Live. Links 2004 also features top championship courses and top professionals, including cover athlete Sergio Garcia."},{"t":"Lionheart: Legacy of the Crusader","p":["Windows"],"d":"Reflexive Entertainment","u":"Black Isle Studios","g":"Action role-playing","r":"August 12, 2003","l":"https://en.wikipedia.org/wiki/Lionheart:_Legacy_of_the_Crusader","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co95z4.jpg","s":"Starting from humble beginnings as a slave, rise to fame and fortune by proving your self worthy against the terrible odds presented by your world's realities and the recent crack in the fabric of reality. Face monstrous hordes and relentless bandits. Specialize in wielding cold steal or be a master of casting hot magical spells. Join factions to gain powerful allies and earn perks that will help you rise above the challenges."},{"t":"Lock On: Modern Air Combat","p":["Windows"],"d":"Eagle Dynamics","u":"Ubi Soft, 1C Company","g":"Air combat simulation","r":"November 20, 2003","l":"https://en.wikipedia.org/wiki/Lock_On:_Modern_Air_Combat","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9nff.jpg","s":"Lock On: Modern Air Combat is considered as a survey simulator by its creators. It contains 8 flyable aircraft and over 40 non-playable/AI-controlled planes. The game mainly revolves around air-to-air combat and air-to-ground combat with some optional, unique roles such as pinpoint/anti-radiation strikes, anti-ship strikes or aerobatics. The game realistically models all aspects of take-off and landing, AWACS (also known as AEW&C), carrier-based landings (for the Su-33), and aerial refueling."},{"t":"Looney Tunes: Back in Action","p":["Game Boy Advance"],"r":"November 11"},{"t":"Lords of EverQuest","p":["Windows"],"d":"Rapid Eye Entertainment","u":"Sony Online Entertainment, Ubi Soft","g":"Real-time strategy","r":"December 1, 2003","l":"https://en.wikipedia.org/wiki/Lords_of_EverQuest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hjr.jpg","s":"Lords of EverQuest is a spin-off of the EverQuest franchise featuring real-time strategy."},{"t":"Lost Kingdoms II","p":["GameCube"],"d":"FromSoftware","u":"Activision, FromSoftware","g":"Action role-playing","r":"May 22, 2003","l":"https://en.wikipedia.org/wiki/Lost_Kingdoms_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30sj.jpg","s":"Lost Kingdoms II is a card-themed RPG for the Gamecube. Set 200 years after Queen Katia saved her kingdom from the God of Destruction, Tara Grimface must now save the land from a new threat."},{"t":"Lupin the 3rd: Lost Treasure by the Sea","p":[],"l":"https://en.wikipedia.org/wiki/Lupin_the_3rd:_Lost_Treasure_by_the_Sea"},{"t":"Mace Griffin: Bounty Hunter","p":["Windows","PlayStation 2","Xbox"],"r":"June 19"},{"t":"Madden NFL 2004","p":["PlayStation 2","GameCube","Xbox","Windows"],"u":"EA Sports","r":"August 12, 2003","l":"https://en.wikipedia.org/wiki/Madden_NFL_2004"},{"t":"Magic Pengel: The Quest for Color","p":["PlayStation 2"],"r":"June 24"},{"t":"Magic: The Gathering – Battlegrounds","p":["Windows","Xbox"],"d":"Secret Level, Inc.","u":"Atari","g":"Fighting","r":"November 19, 2003","l":"https://en.wikipedia.org/wiki/Magic:_The_Gathering_%E2%80%93_Battlegrounds"},{"t":"Magnetic","p":["Windows"],"d":"Mulawa Dreaming","l":"https://en.wikipedia.org/wiki/Magnetic_(video_game)"},{"t":"Manhunt","p":["PlayStation 2"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Manhunt_(video_game)"},{"t":"Maple Colors","p":["Windows"],"g":"Simulator, Visual Novel","l":"https://en.wikipedia.org/wiki/Maple_Colors","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co91nt.jpg","s":"Saku Yoshijirou has just transferred to Kouka Academy, which is famous for its theatrical activities. On his first day at school, he started a fight with Aoi Mirai. To make the matter worse, the fight was seen by Aizen Yukihito, the head of the Drama Club. All of Yoshijirou's classmates are problem students, and he thought he could use the fight to rid himself of them. Then, Yoshijirou is assigned to direct his class in a drama competition against the Drama Club. If they lose the competition, they will be suspended. However, because they are problem students, he has difficulties directing them."},{"t":"MapleStory","p":["Windows","macOS"],"d":"Wizet, Nexon","u":"Nexon, Shengqu Games, AsiaSoft, Gamania","g":"Massively multiplayer online role-playing game","r":"April 29, 2003","l":"https://en.wikipedia.org/wiki/MapleStory","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaas1.jpg","s":"Welcome to MapleStory, the original side-scrolling MMORPG where epic adventure, action and good friends await you. With hundreds of hours of gameplay, this immersive role-playing experience will allow you to unleash your wild side as you create and train a mighty hero, conquer perilous dungeons, overcome terrifying bosses, socialize with your friends and much more. Your MapleStory begins today!"},{"t":"Marcel Desailly Pro Soccer","p":["Mobile phone","PlayStation","PlayStation 2","Windows"],"d":"Gameloft S.A., G Artist, Anco Software","u":"Gameloft, Ubisoft","g":"Sports","r":"July 22, 2003","l":"https://en.wikipedia.org/wiki/Marcel_Desailly_Pro_Soccer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/jvfwuyzsxp8fx8h0yyya.jpg","s":"A soccer game that released for Nokia N-Gage."},{"t":"Marginal: Ano Toki no Tooi Yakusoku wo","p":[],"l":"https://en.wikipedia.org/wiki/Marginal:_Ano_Toki_no_Tooi_Yakusoku_wo"},{"t":"Mario & Luigi: Superstar Saga","p":["Game Boy Advance"],"u":"Nintendo","r":"November 17, 2003"},{"t":"Mario Golf: Toadstool Tour","p":["GameCube"],"r":"July 28"},{"t":"Mario Kart: Double Dash","p":["GameCube"],"r":"November 17"},{"t":"Mario Party 5","p":["GameCube"],"r":"November 11","l":"https://en.wikipedia.org/wiki/Mario_Party_5"},{"t":"Mark Davis Pro Bass Challenge","p":["PlayStation 2"],"d":"Sims","u":"Natsume Inc.","g":"Sports","r":"August 27, 2003","l":"https://en.wikipedia.org/wiki/Mark_Davis_Pro_Bass_Challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6txn.jpg","s":"Mark Davis Pro Bass Challenge is a Fishing game, developed by Sims and published by Natsume, which was released in 2005."},{"t":"Martial Kingdoms","p":["Windows"],"d":"T-Time Technology","g":"Strategy","l":"https://en.wikipedia.org/wiki/Martial_Kingdoms"},{"t":"Marvel vs. Capcom 2: New Age of Heroes","p":["Xbox"],"r":"March 30"},{"t":"Massive Assault","p":["Windows","macOS"],"d":"Wargaming","u":"Matrix Games, Virtual Programming","g":"Turn-based strategy","l":"https://en.wikipedia.org/wiki/Massive_Assault","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ie0.jpg","s":"Take the command of Free Nations Union forces and defeat the Phantom League on one of six distant planets. The rebels decided to seize the power on Earth by first conquering the space colonies, which provide vital energy resources to AOG. The war for global domination unrolls on continents, at sea, and in the air. With secret allies, you can disclose and provide troops at any moment, surprisingly shifting the power balance in a particular region. Lead your divisions, fleets, and air squadrons against those who dared threaten our freedom and democracy."},{"t":"Master of Orion III","p":["Windows"],"r":"February 25","l":"https://en.wikipedia.org/wiki/Master_of_Orion_III"},{"t":"Matrimelee","p":["Arcade","Neo Geo AES"],"d":"Noise Factory","u":"Atlus, Playmore, MEGA, Sun Amusement","g":"Fighting","r":"March 20, 2003","l":"https://en.wikipedia.org/wiki/Matrimelee","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2wx8.jpg","s":"A year after the events of Power Instinct 2, the king of Certain Country wants to find a worthy successor for the throne. He wants the ideal husband for his little daughter (or a beautiful and strong woman for his older son) so he holds a fighting tournament where the prize is the hand of the princess and the throne succession."},{"t":"Max Payne 2: The Fall of Max Payne","p":["Windows","Xbox","PlayStation 2"],"u":"Rockstar Games","g":"Action","r":"October 14, 2003","l":"https://store.steampowered.com/app/12150","i":"images/steam-12150.jpg","s":"Max Payne 2: The Fall of Max Payne is a violent, film-noir love story. Dark, tragic and intense, the in-depth story is a thrill-ride of shocking twists and revelations. Love hurts."},{"t":"Medabots Infinity","p":["GameCube"],"r":"December 14","l":"https://en.wikipedia.org/wiki/Medabots_Infinity"},{"t":"Medal of Honor: Infiltrator","p":["Game Boy Advance"],"d":"Netherock Ltd.","u":"EA Games","g":"Third-person shooter","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/Medal_of_Honor:_Infiltrator","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3nfh.jpg","s":"Medal of Honor Infiltrator puts you in the role of Corporal Jake Murphy, a man who must complete five daring missions to defeat the Axis powers in WWII. From sabotaging enemy resources to capturing key personnel to all-out firefights, you'll need to master a variety of gameplay styles to overcome the enemy. On foot, in a tank, or even in disguise, you must engage opponents on the battlefield with an assortment of WWII-era weapons, including machine guns, grenades, bazookas, and more."},{"t":"Medal of Honor: Rising Sun","p":["PlayStation 2","Xbox","GameCube"],"r":"November 11"},{"t":"Mega Man & Bass","p":["Game Boy Advance"],"r":"March 11","l":"https://en.wikipedia.org/wiki/Mega_Man_%26_Bass"},{"t":"Mega Man Battle Chip Challenge","p":["Game Boy Advance","WonderSwan Color"],"d":"Inti Creates, Capcom Production Studio 2","u":"Capcom","g":"Card battle","r":"August 8, 2003","l":"https://en.wikipedia.org/wiki/Mega_Man_Battle_Chip_Challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3bhg.jpg","s":"Bring it On... Rise to the Challenge! Face off against your opponents. Earn new battle chips and power 'em up! Test your skills in cool new battle scenes and prepare for the ultimate battle for \"Net Domination\" in the Battle Chip Grand Prix. Choose familiar characters from the Battle Network universe—including Mega Man and Guts Man, meet an all new Net-Navi character, and render shots, sword maneuvers and specialized moves with your Battle Chips. Released in Japan as Rockman EXE Battle Chip GP, Mega Man Battle Chip Challenge supports combat for two players via link-up."},{"t":"Mega Man Battle Network 3","p":["Game Boy Advance"],"r":"June 24","l":"https://en.wikipedia.org/wiki/Mega_Man_Battle_Network_3"},{"t":"Mega Man Network Transmission","p":["GameCube"],"r":"June 17","l":"https://en.wikipedia.org/wiki/Mega_Man_Network_Transmission"},{"t":"Mega Man X7","p":["PlayStation 2"],"r":"October 14","l":"https://en.wikipedia.org/wiki/Mega_Man_X7"},{"t":"Mega Man Zero 2","p":["Game Boy Advance"],"r":"October 14","l":"https://en.wikipedia.org/wiki/Mega_Man_Zero_2"},{"t":"Men in Black II: Alien Escape","p":["GameCube"],"r":"February 27"},{"t":"Metal Arms: Glitch in the System","p":["PlayStation 2","Xbox"],"r":"November 18"},{"t":"Metal Gear Solid 2: Substance","p":["Windows"],"r":"March 27"},{"t":"Metal Slug 5","p":["Arcade"],"d":"Noise Factory, SNK Playmore","u":"SNK Playmore, Mega, Ignition Entertainment","g":"Run and gun","r":"November 13, 2003","l":"https://en.wikipedia.org/wiki/Metal_Slug_5","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25th.jpg","s":"A special disc that contains deep and intricate secrets about the Metal Slug project is stolen by a mysterious group called the Ptolemaic Army, whose specialty lies from within archaeological excavation and espionage. Marco and Tarma of the Peregrine Falcon Strike Force follow in hot pursuit against the group and in the process are joined by Eri and Fio of SPARROWS. Together once more, the quartet investigate the shrouded objective of the Ptolemaic Army."},{"t":"Mia's Language Adventure: The Kidnap Caper","p":["Windows","macOS"],"d":"Kutoka Interactive","u":"Kutoka Interactive","g":"Educational","l":"https://en.wikipedia.org/wiki/Mia's_Language_Adventure:_The_Kidnap_Caper"},{"t":"Microsoft Flight Simulator 2004: A Century of Flight","p":["Windows"],"u":"Microsoft","r":"July 29, 2003"},{"t":"Midnight Club II","p":["Windows","PlayStation 2","Xbox"],"r":"April 8","l":"https://en.wikipedia.org/wiki/Midnight_Club_II"},{"t":"Midtown Madness 3","p":["Xbox"],"d":"Digital Illusions CE","u":"Microsoft Game Studios","g":"Racing","r":"June 17, 2003","l":"https://en.wikipedia.org/wiki/Midtown_Madness_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4esw.jpg","s":"Midtown Madness 3 is an open world racing/arcade sequel, part of the Midtown Madness series. For the first time in the series, the game was released only on the Xbox, with a Windows version rumoured for later release, but ultimately scrapped.[citation needed]\n\nThe game was developed by DICE (of Battlefield 1942 fame) and published by Microsoft Game Studios. This marked a change from the developer of the first two games, Angel Studios (now Rockstar San Diego). Coincidentally, Midtown Madness 3 was released in 2003 against Midnight Club II, created by the developer of the first two games, Rockstar San Diego.\n\nThe Xbox-only release and change of developer heralded a significant graphical improvement to maintain the console's graphical standards."},{"t":"Midway Arcade Treasures","p":["PlayStation 2","Xbox","GameCube"],"d":"Digital Eclipse","u":"Midway","g":"Various","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/Midway_Arcade_Treasures"},{"t":"Mission: Impossible – Operation Surma","p":["Xbox","Game Boy Advance","PlayStation 2"],"r":"December 2"},{"t":"Mistmare","p":["Windows"],"u":"Strategy First","r":"June 30, 2003","l":"https://en.wikipedia.org/wiki/Mistmare"},{"t":"MLB 2004","p":["PlayStation 2","PlayStation"],"r":"March 10","l":"https://en.wikipedia.org/wiki/MLB_2004"},{"t":"MLB Slugfest 2004","p":["GameCube","PlayStation 2","Xbox","Game Boy Advance"],"d":"Point of View, Criterion Games, Handheld Games","u":"Midway Sports","g":"Sports","r":"March 17, 2003","l":"https://en.wikipedia.org/wiki/MLB_Slugfest_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7l5c.jpg","s":"The second title in Midway's baseball series, SlugFest 20-04 continues to pour on the rough-housing gameplay, bizarre codes, and humorous commentary. In addition to the new Home Run Derby mode and Create-A-Team options, the game features the ability of pitchers to catch \"On Fire\" and impossible Special Pitches that zigzag, arc, and whizz by in ways that would leave any batter humiliated. New secret teams have been added to the previous bunch, including aliens, minotaurs, and Sub-Zero of Mortal Kombat fame. The customizable Instant Replay is another nice touch, allowing you to relive the awkward moments once you pause the game. And, of course, Tim Kitzrow and Jim Shorts return to the commentators' booth, making their signature random comments and incessant arguments."},{"t":"Mobile Light Force 2","p":["PlayStation 2"],"r":"March 19","l":"https://en.wikipedia.org/wiki/Shikigami_no_Shiro"},{"t":"Mobile Suit Gundam: Encounters in Space","p":["PlayStation 2"],"d":"Bec","u":"Bandai","g":"Action, Hack and slash, Mecha simulation, Third-person shooter, Mecha, Military science fiction","r":"September 4, 2003","l":"https://en.wikipedia.org/wiki/Mobile_Suit_Gundam:_Encounters_in_Space","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9dbn.jpg","s":"Rather than tell a single continuous story, the single-player game in Encounters in Space is broken up into a few short vignettes that take place over the course of four years. These vignettes are accounts of several significant battles during and after the One Year War between the Earth Federation and the Principality of Zeon."},{"t":"Moekan","p":[],"l":"https://en.wikipedia.org/wiki/Moekan"},{"t":"Mojib-Ribbon","p":["PlayStation 2"],"d":"NanaOn-Sha","u":"Sony Computer Entertainment","g":"Music","r":"November 20, 2003","l":"https://en.wikipedia.org/wiki/Mojib-Ribbon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5p70.jpg","s":"Mojib-Ribbon is a music video game created by Masaya Matsuura as a spinoff of his 1999 music game, Vib-Ribbon, which was released for PlayStation. A direct sequel called Vib-Ripple was released in 2004. The releases are comparable to the releases of the earlier PaRappa series (also a Matsuura series) where the original was followed by a pseudo-sequel and then a direct sequel a few years later."},{"t":"Mojo!","p":["PlayStation 2","Xbox"],"d":"FarSight Technologies","u":"Crave Entertainment, DreamCatcher Interactive","g":"Puzzle","r":"August 26, 2003","l":"https://en.wikipedia.org/wiki/Mojo!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/yyxeaveueom9ygipgx09.jpg","s":"The Mojo! game is a challenging, graphically stunning and addictive 3D puzzle adventure that tests both your mind and your reflexes. Because your \"Mojo\" (energy) drains over time, you must quickly maneuver through progressively difficult stages, clearing sequences of colored blocks in increasingly shorter amounts of time. Only the most skilled players will be able to navigate Mojo!'s mind-bending chain of puzzles in order to survive to the legendary 100th stage!"},{"t":"Monster Rancher 4","p":["PlayStation 2"],"r":"November 13","l":"https://en.wikipedia.org/wiki/Monster_Rancher_4"},{"t":"Mother 1 + 2","p":[],"l":"https://en.wikipedia.org/wiki/Mother_1_+_2"},{"t":"MotoGP","p":["N-Gage"],"u":"THQ","r":"November 14, 2003","l":"https://en.wikipedia.org/wiki/MotoGP"},{"t":"MotoGP 3","p":["PlayStation 2"],"d":"Namco","u":"Namco, Namco Hometek, Sony Computer Entertainment","g":"Racing","r":"February 27, 2003","l":"https://en.wikipedia.org/wiki/MotoGP_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1oxh.jpg","s":"The gameplay is very similar to past games by Namco, like MotoGP (PS2) and MotoGP 2 (PS2). MotoGP 3 is based off the 2002 Grand Prix motorcycle racing season, but with the introduction of four stroke bikes, the gameplay has some slight differences. The new 990cc 4-stroke bikes are faster, but tend to be a bit of a handful while the 500cc 2-strokes are less faster but slightly better to handle."},{"t":"MotoGP: Ultimate Racing Technology 2","p":["Xbox","Windows"],"d":"Climax Brighton, Blue Beck","u":"THQ","g":"Racing","r":"May 16, 2003","l":"https://en.wikipedia.org/wiki/MotoGP:_Ultimate_Racing_Technology_2"},{"t":"Movie Battles","p":["macOS","Windows","Linux"],"d":"Movie Battles Team","g":"First-person shooter, third-person shooter, hack and slash","l":"https://en.wikipedia.org/wiki/Movie_Battles"},{"t":"Mucha Lucha! Mascaritas of the Lost Code","p":["Game Boy Advance"],"u":"Ubisoft","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/Mucha_Lucha!_Mascaritas_of_the_Lost_Code"},{"t":"Multi Theft Auto","p":["Windows"],"g":"Simulator, Indie","l":"https://en.wikipedia.org/wiki/Multi_Theft_Auto","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ipj.jpg","s":"Multi Theft Auto (MTA) is a multiplayer modification for the Microsoft Windows version of Rockstar North games Grand Theft Auto III, Grand Theft Auto: Vice City and Grand Theft Auto: San Andreas that adds online multiplayer functionality. For Grand Theft Auto: San Andreas, the mod also serves as a derivative engine to Rockstar's interpretation of RenderWare."},{"t":"Muppets Party Cruise","p":["GameCube","PlayStation 2"],"r":"November 11","l":"https://en.wikipedia.org/wiki/Muppets_Party_Cruise"},{"t":"Murakumo: Renegade Mech Pursuit","p":["Xbox"],"r":"March 4"},{"t":"Mushiking: The King of Beetles","p":["Arcade"],"d":"Sega","u":"Sega","g":"Collectible card","l":"https://en.wikipedia.org/wiki/Mushiking:_The_King_of_Beetles"},{"t":"Music 3000","p":["PlayStation 2"],"d":"Jester Interactive","u":"Jester Interactive, XS Games","g":"Digital audio workstation","r":"May 30, 2003","l":"https://en.wikipedia.org/wiki/Music_3000"},{"t":"Muv-Luv","p":[],"l":"https://en.wikipedia.org/wiki/Muv-Luv"},{"t":"MVP Baseball 2003","p":["Xbox","PlayStation 2","Windows"],"d":"EA Canada","u":"EA Sports","g":"Sports","r":"March 11, 2003","l":"https://en.wikipedia.org/wiki/MVP_Baseball_2003","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8gk5.jpg","s":"MVP is EA Sports' replacement for the aging Triple Play series. Re-written from the ground up, this rookie title includes a Homerun Showdown (not a derby - something a little different) and Franchise mode as well as the usual exhibition games. Many custom batting and pitching animations as well as vendors hawking hot-dogs and hecklers shouting player and team specific heckles - all in an effort to submerse you in the game."},{"t":"My Street","p":["PlayStation 2"],"d":"Idol Minds","u":"Sony Computer Entertainment","g":"Party","r":"March 12, 2003","l":"https://en.wikipedia.org/wiki/My_Street","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7mdf.jpg","s":"Gamers of all ages will enjoy the varied puzzle games, board games and other multiplayer party-style competitions in My Street for PlayStation 2. My Street takes place in a sunny, residential neighborhood with chirping birds, barking dogs, picket fences, sidewalks and front porches. Customize your character and then head for the backyard, the basement, the local park, or other neighborhood spots to play 8 different games with up to 3 other characters, including Marbles, Chemistry Set, Volleyball, Pigs and Chickens, Dodge Ball, Corn Field Maze, RC Racing and Lawn Mowers."},{"t":"Mysterious Journey II","p":["Windows"],"r":"November 25","l":"https://en.wikipedia.org/wiki/Mysterious_Journey_II"},{"t":"N.U.D.E.@ Natural Ultimate Digital Experiment","p":["Xbox"],"d":"Microsoft Game Studios Japan, Red Entertainment","u":"Microsoft Game Studios","g":"Life simulation","r":"April 24, 2003","l":"https://en.wikipedia.org/wiki/N.U.D.E.@_Natural_Ultimate_Digital_Experiment","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ua6.jpg","s":"A virtual humanoid robot who responds to voice commands, never released outside of Japan."},{"t":"Nancy Drew: Danger on Deception Island","p":["Windows"],"g":"Adventure","r":"October 3","l":"https://store.steampowered.com/app/31840","i":"images/steam-31840.jpg","s":"Plunge into Danger to Bring a Mysterious Island’s Secrets to the Surface!"},{"t":"Nancy Drew: The Haunted Carousel","p":["Windows"],"g":"Adventure","r":"August 22","l":"https://store.steampowered.com/app/31820","i":"images/steam-31820.jpg","s":"Take a Spin with Danger to Unravel the Mystery of a Ghostly Merry-go-Round!"},{"t":"Naruto: Clash of Ninja","p":["GameCube"],"d":"Eighting","u":"Tomy","g":"Fighting","r":"April 11, 2003","l":"https://en.wikipedia.org/wiki/Naruto:_Clash_of_Ninja_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ua2.jpg","s":"Naruto Clash of Ninja is the first of the Naruto Clash of ninja games.It includes 8 playable characters (and 2 unlockables) from the Naruto anime."},{"t":"Naruto: Ultimate Ninja","p":["PlayStation 2"],"d":"CyberConnect2","u":"Bandai, Namco Bandai Games","g":"Fighting game","r":"October 23, 2003","l":"https://en.wikipedia.org/wiki/Naruto:_Ultimate_Ninja_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1oxo.jpg","s":"For the first time in the PS2, explore the incredible world of Naruto Uzumaki on the console. Players can select from 14 key characters taken straight from the anime, including Naruto Uzumaki, the young ninja-in-training, and his two ninja-school classmates Sakura and Sasuke. With its opulent visual style and broad range of gameplay modes Naruto: Ultimate Ninja is a game for arcade-fighter and Naruto fans alike."},{"t":"NASCAR Racing 2003 Season","p":["Windows"],"u":"Sierra Entertainment","r":"February 13, 2003","l":"https://en.wikipedia.org/wiki/NASCAR_Racing_2003_Season"},{"t":"NASCAR Thunder 2004","p":["PlayStation 2","Windows","PlayStation","Xbox"],"u":"EA Sports","r":"September 16, 2003","l":"https://en.wikipedia.org/wiki/NASCAR_Thunder_2004"},{"t":"Naval Ops: Warship Gunner","p":["PlayStation 2"],"d":"Microcabin","u":"Koei","g":"Vehicle simulation game","r":"April 3, 2003","l":"https://en.wikipedia.org/wiki/Naval_Ops:_Warship_Gunner","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/qlgquakmrgsyejyxvznz.jpg","s":"The game is a one-player simulation of naval combat, in which the player commands an individual ship. In the opening cutscene, a World War II-era destroyer is caught in a dimension-warping vortex and transported to a parallel universe where the technology level is the same (although science-fiction weapons such as rail guns are available), but the world is at war between two main factions, the Empire and the Freedom Forces. The first mission of the game revolves around navigating a destroyer to safety while being bombarded by unidentified ships. Upon rendezvous with friendly forces, later identified as the Freedom Forces, the crew decides to join them in the war against the Empire."},{"t":"Navy SEALs: Weapons of Mass Destruction","p":["Windows"],"u":"ValuSoft","r":"July 18, 2003"},{"t":"NBA Inside Drive 2004","p":["Xbox"],"d":"High Voltage Software","u":"Microsoft Game Studios","g":"Sports","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/NBA_Inside_Drive_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/lxd3q0c6f99mh4xow7mv.jpg","s":"Real-time, 3D NBA basketball simulation with online league capabilities. More responsive \"juke\" controls for one-on-one isolation moves. Gamers can play up to 25 NBA seasons with full general management capabilities. All-new Drive Cam camera angle brings the player closer to the action. For 1 or more players (online gaming requires Internet connection). Features 3D crowd."},{"t":"NBA Jam","p":["PlayStation 2","Xbox"],"d":"Acclaim Studios Austin","u":"Acclaim Entertainment","g":"Sports","r":"September 23, 2003","l":"https://en.wikipedia.org/wiki/NBA_Jam_(2003_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7l5i.jpg","s":"3-on-3 arcade-style basketball with over 50 of the NBA's all time greatest players. Enter a Legends Tournament and travel back in time as you work your way up through the ranks in head-to-head battle with the best from each era. Each time you defeat a team their players are available for you to use in creating your ultimate dream team. And for some real high-flying action build up your Jam Meter and hit the lights with the over 40 unique Monster Dunks.\n\nThis game feautres tons of unlockables (teams, courts, and cheats) as well as commentary by Tim Kitzrow and Bootsy Collins."},{"t":"NBA Live 2004","p":["PlayStation 2","Xbox","GameCube","Windows"],"d":"EA Canada","u":"Electronic Arts","g":"Sports","r":"October 14, 2003","l":"https://en.wikipedia.org/wiki/NBA_Live_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3981.jpg","s":"NBA Live 2004 is the 2004 installment of the NBA Live video games series. The cover features Vince Carter as a member of the Toronto Raptors and in Spain copies of NBA Live 2004, it features Raul Lopez. The game was developed by EA Sports and released in 2003. The game is similar graphically to NCAA March Madness 2004 and has the same create-a-player models."},{"t":"NBA ShootOut 2004","p":["PlayStation","PlayStation 2"],"d":"Killer Game, San Diego Studio","u":"Sony Computer Entertainment America","g":"Sports","r":"October 6, 2003","l":"https://en.wikipedia.org/wiki/NBA_ShootOut_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ojmwt0skuqq5xnez0dyh.jpg","s":"NBA Shootout 2004 lets you play either a full season or exhibition matches of fully licensed NBA basketball with your favorite teams and players. Fully textured 3d players with faces of the top NBA players are mapped into the game. Listen to commentary by Ian Eagle and Bill Walton as they call the games right as you play.\n\nWhile there is no franchise mode like other more traditional sports games, there is a career mode where you create a character who tries to make his way up through the summer leagues and the NBDL. You'll be given challenges that you'll need to meet so that you can ultimately make your way to the NBA and get an actual contract to join a NBA team. Once in the NBA, you'll need to work even harder to win championships and titles so you can eventually be inducted into the NBA Hall of Fame.\n\nYou can also unlock the 50 greatest players of all time by completing challenges in exhibition games like scoring a certain number of points or using a certain person to get a number of assists.\n\nUse a USB microphone to give your teammates commands to help. Give them commands on offense or defense about where to move so you can use your teammates effectively."},{"t":"NBA Street Vol. 2","p":["PlayStation 2","GameCube","Xbox"],"u":"EA Sports","r":"April 29, 2003","l":"https://en.wikipedia.org/wiki/NBA_Street_Vol._2"},{"t":"NCAA Final Four 2004","p":["PlayStation 2"],"d":"Killer Game","u":"Sony Computer Entertainment America","g":"Sports","r":"November 11, 2003","l":"https://en.wikipedia.org/wiki/NCAA_Final_Four_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/dsmnvpklwlnymjn4xtoo.jpg","s":"NCAA Final Four 2004"},{"t":"NCAA Football 2004","p":["PlayStation 2","Xbox","GameCube"],"u":"EA Sports","r":"July 16, 2003","l":"https://en.wikipedia.org/wiki/NCAA_Football_2004"},{"t":"NCAA GameBreaker 2004","p":["PlayStation 2"],"d":"Red Zone Interactive, 989 Sports","u":"Sony Computer Entertainment","g":"Sports","r":"August 26, 2003","l":"https://en.wikipedia.org/wiki/NCAA_GameBreaker_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaz25.jpg","s":"For the first time ever, NCAA GameBreaker 2004 will allow gamers to take their skills online and compete against other college football fans anytime, anywhere. NCAA GameBreaker 2004 further illustrates the realism of college football this year by using the new Practice Mode that gives players the option to sharpen their skills before playing an exhibition or entering season mode. Bringing back the true-to-life college football experience that gamers crave, legendary announcers Keith Jackson and Tim Brandt return to the microphone. With more than 50 new animated mascots, cheerleaders, and sideline personnel, gamers everywhere will feel the spirit and emotion of college football."},{"t":"NCAA March Madness 2004","p":["PlayStation 2","Xbox"],"d":"NuFX, EA Canada","u":"Electronic Arts","g":"Sports","r":"November 17, 2003","l":"https://en.wikipedia.org/wiki/NCAA_March_Madness_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/gn28yqugiu8ipd63tmmp.jpg","s":"Choose from one of 320 Division I schools and enter the 30 year dynasty mode."},{"t":"Need for Speed: Underground","p":["Windows","GameCube","PlayStation 2","Xbox"],"r":"November 17"},{"t":"Neighbours from Hell","p":["Windows"],"r":"June 20","l":"https://en.wikipedia.org/wiki/Neighbours_from_Hell"},{"t":"Nemesis of the Roman Empire","p":["Windows"],"d":"Haemimont Games","u":"Enlight Software, FX Interactive","g":"Real-time strategy, role-playing","r":"November 27, 2003","l":"https://en.wikipedia.org/wiki/Nemesis_of_the_Roman_Empire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4vfy.jpg","s":"In the height of its glory Carthage was the greatest power in the ancient world. With trade routes throughout the entire Mediterranean there the was no other nation to dispute its strength. Goods, gold and slaves poured in to the majestic city – the source of its might.\n\nCountless mercenaries armies were constantly bought to ensure that all who threatened Carthage or its interest would be dealt with. However, another Empire was also on the rise. The city of Rome too had begun to gain strength. The Romans soon decided openly to challenge their Carthaginian rivals. The time of the Punic Wars had begun.\n\nThe game is a sequel to Celtic Kings: Rage of War, originally titled Celtic Kings: The Punic Wars."},{"t":"Neon Genesis Evangelion 2","p":["PlayStation 2"],"d":"Alfa System","u":"Bandai","g":"Role-playing video game, Adventure, Simulation","r":"November 20, 2003","l":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2wle.jpg","s":"Neon Genesis Evangelion 2 (新世紀エヴァンゲリオン2 lit. \"Shinseiki Evangelion 2\") is a Japanese video game for the PlayStation 2 developed by Alfa System and published by Bandai. It has role-playing video game and world-controlling elements, and allows the player to follow a number of characters (such as Asuka Langley Soryu, Shinji Ikari, Pen², etc.) through multiple versions of the main plot of the anime Neon Genesis Evangelion. The PlayStation Portable port was released 2006-04-27 as Neon Genesis Evangelion 2 -Another Cases-"},{"t":"Neon Genesis Evangelion: Girlfriend of Steel 2nd","p":["PlayStation 2","macOS","Windows","PlayStation Portable"],"d":"Gainax Network Systems","u":"Broccoli","g":"Visual novel","r":"May 16, 2003","l":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion:_Girlfriend_of_Steel_2nd","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2g3s.jpg","s":"Neon Genesis Evangelion: Girlfriend of Steel 2nd (新世紀エヴァンゲリオン鋼鉄のガールフレンド 2nd Shinseiki Evangerion Kōtetsu no Gārufurendo 2nd, lit. \"Neon Genesis Evangelion Girlfriend of Steel 2nd\"), subtitled in English Neon Genesis Evangelion: Iron Maiden 2nd, is a Gainax-produced adventure anime-style video game, and manga based on that game, set in the alternate universe seen in episode 26 of Neon Genesis Evangelion. The player controls Shinji Ikari, the hero of the original Evangelion series, as he navigates his home, school, and social life in a now-peaceful \"Tokyo-3\"."},{"t":"Neverwinter Nights: Hordes of the Underdark","p":["Windows","Linux"],"d":"BioWare","u":"Atari","g":"Role-playing","r":"December 2, 2003","l":"https://en.wikipedia.org/wiki/Neverwinter_Nights:_Hordes_of_the_Underdark"},{"t":"Neverwinter Nights: Shadows of Undrentide","p":["Windows","Linux"],"d":"Floodgate Entertainment, BioWare","u":"Atari","g":"Role-playing","r":"June 17, 2003","l":"https://en.wikipedia.org/wiki/Neverwinter_Nights:_Shadows_of_Undrentide"},{"t":"NFL Blitz Pro","p":["PlayStation 2","Xbox","GameCube"],"d":"Midway Games","u":"Midway Sports","g":"Sports","r":"October 27, 2003","l":"https://en.wikipedia.org/wiki/NFL_Blitz_Pro","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co45ji.jpg","s":"The mega-popular arcade-style Blitz football series returns with NFL Bliz: Pro for the PlayStation 2, Xbox, and GameCube. For the first time in the series' long-running history Blitz will feature a slew of realistic NFL elements mixed with the fast-paced and action-centered gameplay that fans have come to know and love. New 11-on-11 gameplay takes the action to the pro-level; making it possible to include every player, team and position. An extensive new ten-season Franchise Mode allows gamers to experience player trading and drafting, and improved graphics and animations take advantage of motion-capture technology; making those bone-crunching hits painfully realistic."},{"t":"NFL Fever 2004","p":["Xbox"],"d":"Microsoft Game Studios","u":"Microsoft Game Studios","g":"Sports","r":"August 28, 2003","l":"https://en.wikipedia.org/wiki/NFL_Fever_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/poecngxgypyl0wujt13b.jpg","s":"Microsoft's own football game returns with updated Graphics and Roosters. There are now even more tackles, and avoiding moves to be learned. Play on any Nfl stadium possible, while the power of xbox giving you your own music, and real-to-real football penalties, players, fields, clothes, and the crowd cheering you on. Customize your own coverage, how you want.\n\nPlay 1-4 players in a game, or 1-8 system link. Play Xbox live with a friend with, multiplayer, voice, friends, scoreboard"},{"t":"NFL GameDay 2004","p":["PlayStation","PlayStation 2"],"d":"San Diego Studio","u":"Sony Computer Entertainment America","g":"Sports","r":"August 26, 2003","l":"https://en.wikipedia.org/wiki/NFL_GameDay_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/gk4rlostspu2jqbrhlw6.jpg"},{"t":"NHL 2004","p":["Windows","GameCube","PlayStation 2","Xbox"],"r":"September 22","l":"https://en.wikipedia.org/wiki/NHL_2004"},{"t":"NHL Hitz Pro","p":["GameCube","Xbox","PlayStation 2"],"d":"Next Level Games","u":"Midway Sports","g":"Sports","r":"September 25, 2003","l":"https://en.wikipedia.org/wiki/NHL_Hitz_Pro","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ue4.jpg","s":"NHL Hitz Pro is an ice hockey video game developed by Next Level Games and published by Midway Games. It's the third and final game of the NHL Hitz series. It was released on September 25, 2003, for the PlayStation 2, Nintendo GameCube, and Xbox. Unlike the previous titles in the series, this game has 5-on-5 gameplay instead of the usual 3-on-3 gameplay with the earlier titles. Despite that fact, however, the game does not include penalty shots, and it is still an arcade-type hockey game like its predecessors. It also has, as the name suggests, a lot of hard hitting, appealing more often to casual hockey fans than hardcore ones. The cover athlete of the game is Nicklas Lidström, and features commentary from Tim Kitzrow[1] and Harry Teinowitz.\n\nUnlike many other hockey video games of the 21st century, NHL Hitz Pro had the IIHF license, enabling it to use the jerseys of the Olympic hockey teams.\n\nThe game also has many game modes, one of the most popular being the \"Pick-Up Hockey\" game mode, where the game would turn into either a roller, street, or pond hockey match-up between two amateur teams."},{"t":"NHL Rivals 2004","p":["Xbox"],"d":"Microsoft Game Studios","u":"Xbox Sports Network","g":"Sports","r":"November 21, 2003","l":"https://en.wikipedia.org/wiki/NHL_Rivals_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gou.jpg","s":"NHL Rivals 2004 is the first NHL title for the Xbox, developed by MGS (Microsoft Game Studios), and the second title developed under the XSN Sports banner - the development team's first foray into hockey on console.\n\nAt the time of its release, the visuals in this game were its major selling point, with each player's face mapped onto their model ingame. The game features a fully animated polygonal crowd, tons of motion-captured animations, NHL licensed players, teams and arenas. The look and feel of the game are much different than games like EA's NHL series.\n\nThis was also the first hockey game on Xbox that let players play in online tournaments and leagues over Xbox Live and XSN Sports. Rosters were updated as the season went on via content downloads over Xbox Live, though were only available for a limited time.\n\nRivals 2004 features the gameplay mode of 3-on-3 pond hockey. This pickup-game style of play is meant for those who prefer instant action, and it can also be played over Xbox Live. Players can connect and join in on a recreational game intended to simulate the fun pickup games that many people played as kids.\n\nThe gameplay is arcade-like, with fast play and quick passing via a button or in specific directions using the analog stick."},{"t":"Ninja Five-O","p":["Game Boy Advance"],"r":"April 22","l":"https://en.wikipedia.org/wiki/Ninja_Five-O"},{"t":"Nintendo GameCube Preview Disc","p":[],"l":"https://en.wikipedia.org/wiki/Nintendo_GameCube_Preview_Disc"},{"t":"Nintendo Puzzle Collection","p":["GameCube"],"d":"Intelligent Systems","u":"Nintendo","g":"Puzzle","r":"February 7, 2003","l":"https://en.wikipedia.org/wiki/Nintendo_Puzzle_Collection"},{"t":"No Man's Land","p":["Windows"],"d":"Related Designs","u":"CDV Software, Strategy First","g":"Real-time strategy","r":"October 20, 2003","l":"https://en.wikipedia.org/wiki/No_Man's_Land_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2j5k.jpg","s":"No Man's Land also known as No Man's Land: Fight for your Rights!."},{"t":"Nosferatu: The Wrath of Malachi","p":["Windows"],"d":"Idol FX","u":"iGames Publishing, Mindscape","g":"First-person shooter, Horror","r":"October 21, 2003","l":"https://en.wikipedia.org/wiki/Nosferatu:_The_Wrath_of_Malachi","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc84s.jpg","s":"It is a misty evening in the year of our lord 1912. The Pattersons, a poor but proud aristocratic family of the British nobility, and some of their closest friends, arrive at the castle Malachi residence of a wealthy Romanian Count. It is only three days until the family's eldest daughter, Rebecca, is to be wed to the count's son, uniting the family with the rich heritage of the Malachi, hopefully restoring its glory.\n\nThe only person missing is you, the brother of the bride, who is on your way from Stockholm, where you have defended the Union Jack in the noble art of fencing in the Olympics. You are to arrive later during the evening.\n\nSir Patterson is disappointed when the Count himself doesn't greet the family at their arrival, but still he lets the servants show them all to their rooms, without complaining too loudly. It is not until later--when the doors are slammed shut and locked behind them, that he realizes his mistake that they have become prisoners and are at the Count's mercy..."},{"t":"Notrium","p":["Windows","Linux"],"d":"Ville Mönkkönen","g":"Survival","r":"September 9, 2003","l":"https://en.wikipedia.org/wiki/Notrium"},{"t":"Oddworld: Munch's Oddysee","p":["Game Boy Advance"],"r":"September 24"},{"t":"Omerta","p":[],"l":"https://en.wikipedia.org/wiki/Omerta_(video_game)"},{"t":"One Must Fall: Battlegrounds","p":["Windows"],"d":"Diversions Entertainment","u":"Diversions Publishing, Tri Synergy, GMX Media, Manaccom","g":"Fighting","r":"December 19, 2003","l":"https://en.wikipedia.org/wiki/One_Must_Fall:_Battlegrounds","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7tv1.jpg","s":"Players control various robots from a 3rd person perspective as they maneuver around trap-filled hazardous environments."},{"t":"Onimusha Blade Warriors","p":["PlayStation 2"],"d":"Capcom","u":"Capcom","g":"Fighting","r":"November 27, 2003","l":"https://en.wikipedia.org/wiki/Onimusha_Blade_Warriors"},{"t":"Onimusha Tactics","p":["Game Boy Advance"],"r":"November 11","l":"https://en.wikipedia.org/wiki/Onimusha_Tactics"},{"t":"Online Bomberman","p":["Windows"],"d":"Hudson Soft, MGAME Corporation","u":"Hudson Soft, Wizgate, Fullerton","g":"Massively multiplayer online game, maze","l":"https://en.wikipedia.org/wiki/Online_Bomberman","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4rrn.jpg","s":"Free multiplayer online game where players dash through crazy worlds ... and drop, run and bomb your opponent, Welcome to the world of Bomberman Online!"},{"t":"Operation Armored Liberty","p":["Game Boy Advance"],"d":"Eastridge Technology","u":"Majesco Sales, Inc.","g":"Shooter","r":"November 9, 2003","l":"https://en.wikipedia.org/wiki/Operation_Armored_Liberty"},{"t":"Orange Pocket","p":[],"l":"https://en.wikipedia.org/wiki/Orange_Pocket"},{"t":"Otogi 2: Immortal Warriors","p":["Xbox"],"d":"FromSoftware","u":"FromSoftware, Sega","g":"Action role-playing, hack and slash","r":"December 25, 2003","l":"https://en.wikipedia.org/wiki/Otogi_2:_Immortal_Warriors","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48qc.jpg","s":"Take the role of the undead warrior Raikoh Minamoto and his companions as they are tasked with vanquishing the invading hordes of demons and protecting Japan's capital city from being consumed by the darkness."},{"t":"Otogi: Myth of Demons","p":["Xbox"],"r":"August 27","l":"https://en.wikipedia.org/wiki/Otogi"},{"t":"Out of Order","p":["Windows","macOS","Linux"],"d":"Tim Furnish","u":"Hungry Software","g":"2D adventure","l":"https://en.wikipedia.org/wiki/Out_of_Order_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4gwq.jpg","s":"Out of Order is a freeware 2D point and click adventure video game by British indie developer Tim Furnish for Windows, macOS, and Linux featuring a comedic science fiction-adventure narrative."},{"t":"Outlaw Volleyball","p":["Xbox"],"d":"Hypnotix","u":"Simon & Schuster Interactive, TDK Mediactive Europe, Global Star Software","g":"Sports, fighting","r":"July 8, 2003","l":"https://en.wikipedia.org/wiki/Outlaw_Volleyball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5b7a.jpg","s":"Outlaw Volleyball is the second game in Simon & Schuster's growing Outlaw franchise.\n\nAs the title suggests, you play various games of volleyball with shady and dirty characters, from a slutty biker to an ex con to a pair of strippers. There are sixteen players in total. Each character has his or her own unique personality, strengths and weaknesses.\n\nThere are four different modes you can compete in; Exhibition, which is a standard volleyball game, Tour, which is the career mode that spans fifty different events, and Drills, which are sort of like practice games that awards points you can use to improve your player's abilities. The fourth mode is Xbox Live enabled, allowing you to play with people over the Xbox Live service.\n\nThere are ten different courts to play on, each one with it's own backgrounds and animation. You can play on a beach, at a carnival, or even in a prison.\n\nOutlaw Volleyball utilizes the same momentum feature first seen in Outlaw Golf, which allows you to earn \"beating tokens\" that you can spend on beating up the other team. If you are doing lousy, beating up a member of the other team refills your momentum meter, allowing you to come back and possibly win."},{"t":"Ozzy & Drix","p":["Game Boy Advance"],"u":"Midway Games","r":"December 16, 2003","l":"https://en.wikipedia.org/wiki/Ozzy_%26_Drix_(video_game)"},{"t":"P.N.03","p":["GameCube"],"r":"September 9","l":"https://en.wikipedia.org/wiki/P.N.03"},{"t":"Pac-Man Vs.","p":["GameCube"],"r":"December 2","l":"https://en.wikipedia.org/wiki/Pac-Man_Vs."},{"t":"Pajama Sam: Life Is Rough When You Lose Your Stuff!","p":["Windows"],"d":"Humongous Entertainment","u":"Atari","g":"Adventure","l":"https://en.wikipedia.org/wiki/Pajama_Sam:_Life_Is_Rough_When_You_Lose_Your_Stuff!"},{"t":"Panzer Dragoon Orta","p":["Xbox"],"r":"January 12","l":"https://en.wikipedia.org/wiki/Panzer_Dragoon_Orta"},{"t":"Pekka Kana 2","p":["Windows","Linux","macOS"],"d":"Pistez Gamez","g":"Platformer","l":"https://en.wikipedia.org/wiki/Pekka_Kana_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobrbj.jpg","s":"Pekka is a chicken who will live many adventures in a colorful world full of funny enemies and hard bosses."},{"t":"Penta no Tsuri Bōken","p":["Mobile phone"],"d":"Konami","u":"Konami","g":"Fishing","r":"May 7, 2003","l":"https://en.wikipedia.org/wiki/Penta_no_Tsuri_B%C5%8Dken"},{"t":"Perfect Cherry Blossom","p":["Windows"],"d":"Team Shanghai Alice","u":"Team Shanghai Alice","g":"Scrolling shooter, bullet hell","r":"August 17, 2003","l":"https://en.wikipedia.org/wiki/Perfect_Cherry_Blossom"},{"t":"Peter Pan: The Motion Picture Event","p":[],"l":"https://en.wikipedia.org/wiki/Peter_Pan:_The_Motion_Picture_Event"},{"t":"Phantasy Star Online Episode III: C.A.R.D. Revolution","p":["GameCube"],"d":"Sonic Team","u":"Sega","g":"Role-playing","r":"November 27, 2003","l":"https://en.wikipedia.org/wiki/Phantasy_Star_Online_Episode_III:_C.A.R.D._Revolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hdj.jpg","s":"A turn-based online RPG for the Nintendo GameCube. Set in the Phantasy Star Online universe, join the Hero or Dark side using cards featuring weapons or creatures from Phantasy Star Online Episodes I and II."},{"t":"Piglet's Big Game","p":["Game Boy Advance"],"r":"March 11","l":"https://en.wikipedia.org/wiki/Piglet%27s_Big_Game"},{"t":"Pingus","p":[],"l":"https://en.wikipedia.org/wiki/Pingus"},{"t":"Pinobee: Wings of Adventure","p":["PlayStation"],"r":"April 17"},{"t":"Pirate Hunter","p":["Windows"],"d":"Ascaron Entertainment","u":"Encore","g":"Action-adventure, strategy","r":"October 22, 2003","l":"https://en.wikipedia.org/wiki/Pirate_Hunter"},{"t":"Pirates of the Caribbean","p":["Xbox","Windows"],"g":"Adventure, Massively Multiplayer, RPG, Simulation, Strategy, Free To Play","r":"July 1","l":"https://en.wikipedia.org/wiki/Pirates_of_the_Caribbean_(video_game)","i":"images/steam-2591710.jpg","s":"Battle for the title of Pirate King in Pirates of the Caribbean: Tides of War, the official real-time strategy game. Live the pirate’s life: lead fearsome fleets, plunder priceless treasures, and fight alongside legendary Captains. The seas await, claim your destiny!"},{"t":"Pirates of the Caribbean: The Curse of the Black Pearl","p":["Game Boy Advance"],"d":"Pocket Studios","u":"TDK Mediactive","g":"Action-adventure","r":"June 19, 2003","l":"https://en.wikipedia.org/wiki/Pirates_of_the_Caribbean:_The_Curse_of_the_Black_Pearl_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d6o.jpg","s":"It's mutiny on the high seas as you steal, barter and pillage your way to riches in the video game that accompanies Disney's major live action film for Summer 2003. Search for treasure as you defend your pirating skills with cannons, artillery and swords in an all out battle for the ultimate in pirate booty!"},{"t":"PlanetSide","p":["Windows"],"r":"May 20","l":"https://en.wikipedia.org/wiki/PlanetSide_(video_game)"},{"t":"Plant Tycoon","p":["Mobile phone"],"d":"Last Day of Work","g":"Life simulation, Business simulation","r":"November 8, 2003","l":"https://en.wikipedia.org/wiki/Plant_Tycoon"},{"t":"Pochi and Nyaa","p":["Arcade"],"d":"Aiky","u":"Taito, Bandai, Compile Maru","g":"Puzzle","r":"December 24, 2003","l":"https://en.wikipedia.org/wiki/Pochi_and_Nyaa","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4hpt.jpg","s":"Pochi and Nyaa is a puzzle game made by Taito (Makers of Puzzle Bobble/Bust-A-Move) and Aiky. The story behind it is that in every 1000 years there is a Tournament held by the animal gods Pochi (the Dog) and Nyaa (the Cat) in decision who will be the top star for the next millennium, although they need the power of Earth's people to do so. The gameplay is similar to Super Puzzle Fighter and Puyo Pop, but with a few differences."},{"t":"Pokémon Channel","p":["GameCube"],"d":"Ambrella","u":"The Pokémon Company, Nintendo","g":"Adventure, virtual pet, simulation","r":"July 18, 2003","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Channel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pok.jpg","s":"Pokémon Channel is a 2003 video game in the Pokémon series for the GameCube, developed by Ambrella and published by Nintendo and The Pokémon Company. The player's goal is to help Professor Oak refine and promote his TV network through watching broadcasts with a Pikachu. The game contains elements of the adventure, digital pet, and simulation genres. The player can explore full 3D environments, have Pikachu converse with other Pokémon, and collect various items.\n\nThe game was developed rather quickly as a sequel to the Nintendo 64 title Hey You, Pikachu! and to promote the Nintendo e-Reader accessory, and uses a novel 3D texturing effect. It was first showcased at Electronic Entertainment Expo (E3) 2003 and later through a month-long series of promotional events in Sapporo, Hokkaido, Japan. It was released on July 18, 2003, in Japan, December 1 in North America, and April 2, 2004, in Europe. In Japan, the game sold 66,373 copies in its first year. It received mixed reviews, which generally criticized its low level of interactivity and repetitive sound effects, though its collecting aspects and visuals were somewhat better received."},{"t":"Pokémon Colosseum","p":["GameCube"],"d":"Genius Sonority","u":"The Pokémon Company, Nintendo","g":"Role-playing","r":"November 21, 2003","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Colosseum","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2tpe.jpg","s":"Pokemon fans can now battle their favorite Pokemon on the grand stage. Starring a brand new leading character, Pokemon, Colosseum offers a story mode that pits you against tough trainers who routinely catch damaged Pokemon. In Battle mode, you can use the Game Boy Advance cable to send your team from your Pokemon Ruby or Pokemon Sapphire Game Pak to your Gamecube, then witness the true potential of your team. Rescue Pokemon and watch them come to life in spectacular Colosseum battles."},{"t":"Pokémon Pinball: Ruby & Sapphire","p":["Game Boy Advance"],"d":"Jupiter","u":"The Pokémon Company, Nintendo","g":"Pinball","r":"August 1, 2003","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Pinball:_Ruby_&_Sapphire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coczwe.jpg","s":"Pokemon Pinball has all the features you'd demand of a pinball game, including bonus tables, lots of bumpers and ways to score massive points. As with your standard videogame pinball game, the left button on the D-pad and the A-button control the flippers with the R/L triggers used to shake the table. The catch here is that everything is themed in Pokemon. Instead of a ball, you make use of a Pokeball. Instead of standard bumpers, you're hitting the Pokeball against other Pokemon, and the ultimate goal is of course to \"catch 'em all\". The game features 200 Pokemon, two main tables, and link cable support."},{"t":"Pokémon Ruby and Sapphire","p":["Game Boy Advance"],"g":"Monster tamer","r":"March 19","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Ruby_and_Sapphire"},{"t":"Polanie II","p":["Windows","macOS"],"d":"Reality Pump Studios","u":"Topware Interactive","g":"Real-time strategy, role-playing","l":"https://en.wikipedia.org/wiki/Polanie_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1q6r.jpg","s":"Do you like Real Time Strategy? or are Role Playing Games your preference…\nWhy not try both genres in one? … or even both separately? …\nIn one game: KnightShift!\n\nIn a mystical world beyond fantasy and imagination, where corruption and disaster go hand in hand, not all is as it seems. A dark adventure begins in the RPG part: divided into eight chapters of dungeons, rare treasures, very strange companions and gruesome opponents. Eight individually equipped characters are available to you in this action packed role-play. It is now down to you, the player to form your hero and help him to fame and victory.\n\nAs soon as Gallus has been freed he can get on with job of bringing Prince John back to his father's kingdom. Strategy begins here: with the support of your loyal subjects the fight against the powers of evil begins.\n\nGAME FEATURES:\nTwo games in one, a gripping storyline with amazing characters in a living world of fantasy [RTS-Part in 24 exciting missions and RPG Part with 8 chapters and countless nerve tickling quests]\nSkirmish RPG und RTS Mode with over 20 additional maps\nOver 2,000 various weapons, equipment and magical items\nExtensive multiplayer fun with companion and competitive matches over LAN and EarthNET\nRevolutionary graphics taking full advantage of Per Pixel Shader technology with automatic adaptation of the engine to fitted hardware\nA brand new Musical Score with over 75 pieces of original music\nCompletely 3D with a freely rotating camera"},{"t":"Postal 2","p":["Windows"],"g":"Action, Adventure, Indie","r":"April 14","l":"https://en.wikipedia.org/wiki/Postal_2","i":"images/steam-223470.jpg","s":"Live a week in the life of &quot;The POSTAL Dude&quot;; a hapless everyman just trying to check off some chores. Buying milk, returning an overdue library book, getting Gary Coleman's autograph, what could possibly go wrong?"},{"t":"Power Rangers: Ninja Storm","p":["Game Boy Advance"],"r":"September 5"},{"t":"Praetorians","p":["Windows"],"g":"Indie, Strategy","r":"February 28","l":"https://en.wikipedia.org/wiki/Praetorians_(video_game)","i":"images/steam-277460.jpg","s":"Praetorians is set amidst the political machinations of an emerging Roman Empire. You will be transported back to the dusty battlefields of Egypt, the combat theaters of Gaul and finally to the heart of the Empire itself, Italy in the crusade to become Emperor."},{"t":"Premier Manager 2003–04","p":["Game Boy Advance","PlayStation 2","Windows"],"d":"Zoo Digital Publishing","u":"Zoo Digital Publishing","g":"Sports","r":"November 28, 2003","l":"https://en.wikipedia.org/wiki/Premier_Manager_2003%E2%80%9304"},{"t":"Pride FC: Fighting Championships","p":["PlayStation 2"],"r":"March 20"},{"t":"PrideGP Grand Prix 2003","p":["PlayStation 2"],"d":"DreamFactory","u":"Capcom","g":"Fighting","r":"November 2003","l":"https://en.wikipedia.org/wiki/PrideGP_Grand_Prix_2003"},{"t":"Primal","p":["PlayStation 2"],"r":"March 25","l":"https://en.wikipedia.org/wiki/Primal_(video_game)"},{"t":"Prince of Persia: The Sands of Time","p":["Xbox","GameCube","PlayStation 2","Windows"],"u":"Ubisoft","g":"Action, Adventure","r":"November 18, 2003","l":"https://store.steampowered.com/app/13600","i":"images/steam-13600.jpg","s":"Amidst the scorched sands of ancient Persia, there is a legend spun in an ancient tongue. It speaks of a time borne by blood and ruled by deceit. Drawn to the dark powers of a magic dagger, a young Prince is led to unleash a deadly evil upon a beautiful kingdom."},{"t":"Pro Evolution Soccer 3","p":["Windows","PlayStation 2"],"u":"Konami","r":"October 17, 2003","l":"https://en.wikipedia.org/wiki/Pro_Evolution_Soccer_3"},{"t":"Project Gotham Racing 2","p":["Xbox"],"u":"Microsoft Game Studios","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/Project_Gotham_Racing_2"},{"t":"Psyvariar 2","p":["Arcade"],"d":"SKONEC Entertainment Co., Ltd.","u":"Success Corporation","g":"Scrolling shooter","r":"November 2003","l":"https://en.wikipedia.org/wiki/Psyvariar_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ps4ceh9kll9gu1xjbjwl.jpg","s":"Psyvariar 2: The Will to Fabricate (サイヴァリア2: THE WILL TO FABRICATE?) is a vertically scrolling shoot 'em up developed by SKONEC Entertainment and distributed by Success. It is the sequel to the 2000 title, Psyvariar.\n\nThe game was initially developed for the Sega NAOMI arcade platform, and was released in Japanese arcades in November 2003. A Dreamcast version was released on February 26, 2004, and ports to both the PlayStation 2 and Xbox were released later that year."},{"t":"Pulse Racer","p":["Xbox"],"u":"Jaleco","r":"January 2, 2003","l":"https://en.wikipedia.org/wiki/Pulse_Racer"},{"t":"Purge","p":["Windows"],"d":"Freeform Interactive","u":"Tri Synergy","g":"First-person shooter","r":"April 15, 2003","l":"https://en.wikipedia.org/wiki/Purge_(video_game)"},{"t":"Putt-Putt: Pep's Birthday Surprise","p":["Windows"],"d":"Humongous Entertainment","u":"Atari","g":"Adventure","r":"August 19, 2003","l":"https://en.wikipedia.org/wiki/Putt-Putt:_Pep's_Birthday_Surprise","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3y4j.jpg","s":"It's Pep's birthday and Putt-Putt wants to surprise him with his first birthday party ever!"},{"t":"Puzzle Bobble VS","p":["N-Gage"],"u":"Taito","r":"October 6, 2003","l":"https://en.wikipedia.org/wiki/Puzzle_Bobble"},{"t":"Puzzle Pirates","p":["Windows","macOS","Linux"],"d":"Grey Havens","u":"Grey Havens","g":"MMOG","r":"December 8, 2003","l":"https://en.wikipedia.org/wiki/Puzzle_Pirates","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2270.jpg","s":"Brace yourself for swashbuckling puzzle action as you pillage your way to glory across the briny deep.\n\nCreate and customize a pirate, collect booty, and join a player-run crew of cutthroats! Every activity in Puzzle Pirates is a uniquely fun puzzle: be it sailing, gunning, or hauling treasure, your own puzzling skill determines your success.\n\nFree to Play: Puzzle Pirates is free to play."},{"t":"Quad Desert Fury","p":["Game Boy Advance"],"d":"Skyworks Technologies","u":"Majesco Games","g":"Racing","l":"https://en.wikipedia.org/wiki/Quad_Desert_Fury","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4z8z.jpg","s":"Quad Desert Fury takes games to the desert tracks aboard their ATV's. Riders compete against three other computer controlled Quads to stay on course and not wipe out while finishing with the best time."},{"t":"Quest for Saddam","p":["Windows"],"d":"Petrilla Entertainment","u":"Petrilla Entertainment","g":"First-person shooter","r":"May 14, 2003","l":"https://en.wikipedia.org/wiki/Quest_for_Saddam","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6p9q.jpg","s":"In Quest for Saddam, your mission is to find and capture Saddam Hussein. As a highly trained, special forces soldier, you're armed with an arsenal of weapons and a coalition of comical characters. Battles take you across Iraq, fighting hordes of Iraqi soldiers in your ultimate quest, Saddam Hussein."},{"t":"R: Racing Evolution","p":["GameCube","PlayStation 2","Xbox"],"d":"Namco","u":"Namco, Namco Hometek, Electronic Arts","g":"Sim racing","r":"November 27, 2003","l":"https://en.wikipedia.org/wiki/R:_Racing_Evolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8cag.jpg","s":"You play the part of Rena Hayami who begins the story as an ambulance driver. After successfully racing the vehicle to the hospital, you're offered a chance to drive a racecar."},{"t":"Racing Evoluzione","p":["Xbox"],"d":"Milestone srl","u":"Infogrames Europe","g":"Racing","r":"February 7, 2003","l":"https://en.wikipedia.org/wiki/Racing_Evoluzione","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7hgz.jpg","s":"Get ready to bury the world’s most renowned cars when you race against them with your own brand of sports car. Start off with a small garage, create the ultimate driving machine and go into business as the up and coming sports car manufacturer. Your goal is to build up a reputation for your brand by racing your cars against real sports cars. The more races you win, the more pedigree your brand will receive. If you consistently win the races, you are put to the challenge to start a production line, sell your cars, design new ones, and continue the cycle."},{"t":"RahXephon","p":["PlayStation 2"],"g":"Simulator","l":"https://en.wikipedia.org/wiki/RahXephon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc1i0.jpg","s":"Science-fiction Action-adventure game based on the TV series."},{"t":"Railroad Tycoon 3","p":["Windows"],"d":"PopTop Software, Beenox","u":"Gathering","g":"Business simulation","r":"October 27, 2003","l":"https://en.wikipedia.org/wiki/Railroad_Tycoon_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2r3o.jpg","s":"A fully realised 3D gaming world scaling from eye in the sky views of entire continents down to incredibly detailed close-ups of beautifully modelled locomotives, buildings and landscapes. As well as the 25 challenging scenarios to recreate magnificent feats of railroading history, players can pick from over 40 locomotives over 35 different cargoes and in excess of 150 buildings ? all to be used in a dynamic, fluid economy. Railroad Tycoon 3 defines the essence of tycoon simulations with incredible attention to detail in a living, breathing world, built around a truly amazing game! All aboard."},{"t":"Rakushou! Pachi-Slot Sengen","p":["PlayStation 2"],"d":"Tecmo","u":"Tecmo","g":"Slot machine simulation","r":"October 23, 2003","l":"https://en.wikipedia.org/wiki/Rakushou!_Pachi-Slot_Sengen"},{"t":"Ratchet & Clank: Going Commando","p":["PlayStation 2"],"u":"Sony Computer Entertainment","r":"November 11, 2003"},{"t":"Rayman 3: Hoodlum Havoc","p":["GameCube","Game Boy Advance","PlayStation 2","Xbox","Windows"],"r":"February 21"},{"t":"Rebel Trucker","p":["Windows"],"d":"3 Romans","u":"Global Star Software","g":"Racing, Simulation","r":"November 25, 2003","l":"https://en.wikipedia.org/wiki/Rebel_Trucker"},{"t":"Rei Fighter Gekitsui Senki","p":["GameCube"],"d":"Global A Entertainment","u":"Global A Entertainment","g":"Combat flight simulation","r":"March 6, 2003","l":"https://en.wikipedia.org/wiki/Rei_Fighter_Gekitsui_Senki","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7l5s.jpg"},{"t":"Republic: The Revolution","p":["Windows"],"d":"Elixir Studios","u":"Eidos Interactive, Feral Interactive","g":"Strategy","r":"August 26, 2003","l":"https://en.wikipedia.org/wiki/Republic:_The_Revolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5j84.jpg","s":"Republic: The Revolution is a computer game produced by Elixir Studios, founded by Demis Hassabis , a former programmer of Lionhead Studios and published by Eidos Interactive. It has since been released for the Mac OS X by Feral Interactive. It is a depiction of grassroots political action, where one attempts to put their preferred government in power. It is set in Novistrana, a small, fictional, post-Soviet country in Eastern Europe."},{"t":"Rescue Heroes: Billy Blazes","p":["Game Boy Advance"],"r":"August 27","l":"https://en.wikipedia.org/wiki/Rescue_Heroes"},{"t":"Resident Evil: Dead Aim","p":["PlayStation 2"],"d":"Cavia","u":"Capcom","g":"Light gun shooter","r":"February 13, 2003","l":"https://en.wikipedia.org/wiki/Resident_Evil:_Dead_Aim","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2w5n.jpg","s":"Resident Evil: Dead Aim is a survival-horror game released exclusively for the PlayStation 2 under the Gun Survivor title, which was used for several games made for the Namco light gun controllers. The game is played in two camera angles: the player moves from a third-person perspective while walking, which changes to a first-person perspective while aiming the gun. You'll pick up several guns through the course of the game, including a magnum, a shotgun, and an assault rifle. But like in other Resident Evil games, zombies are difficult to put down permanently and ammo can be very scarce."},{"t":"Restaurant Empire","p":["Windows"],"d":"Enlight Software","u":"Enlight Software","g":"Business simulation","r":"March 2003","l":"https://en.wikipedia.org/wiki/Restaurant_Empire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob3gv.jpg","s":"Starting with nothing except some cash and a passion for food, build a restaurant from the bottom up - hire waiters, decorate, even cook the meals! Buy, build, outsell and underprice your competition.\n\nWill you use your culinary wizardry to out-cook chefs? What tactics and strategies will you employ to buy out the competition? You decide. With a combination of business strategy and role-playing game styles plus a free-form sandbox game mode, three huge cities, and over 30 playable chefs and a host of locations to travel to, Restaurant Empire is an epicurean delight of gastronomic proportions."},{"t":"Revenge of the Apes","p":["Atari 2600"],"d":"20th Century Fox, Retrodesign","u":"Retrodesign","g":"Action-adventure","l":"https://en.wikipedia.org/wiki/Revenge_of_the_Apes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ni0azstvt1rwcx6b8wpt.jpg","s":"Planet of the Apes, later released as Revenge of the Apes, is a video game originally developed in 1983 by 20th Century Fox for the Atari 2600. Planned as the Planet of the Apes franchise's first video game, it was still in the prototype phase when Fox shuttered its game division during the video game crash of 1983. It went unreleased and was assumed lost until 2002, when collectors identified a mislabeled cartridge as the missing Planet of the Apes game. It was completed and released as Revenge of the Apes by Retrodesign in 2003."},{"t":"Ring II: Twilight of Gods","p":["Windows"],"u":"Global Star Software","r":"September 16, 2003","l":"https://en.wikipedia.org/wiki/Ring_(video_game)#Sequel"},{"t":"Rise of Nations","p":["Windows"],"u":"Microsoft Game Studios","r":"May 20, 2003","l":"https://en.wikipedia.org/wiki/Rise_of_Nations"},{"t":"Risk: Global Domination","p":["PlayStation 2"],"d":"Cyberlore Studios","u":"Atari Interactive","g":"Board game, Turn-based strategy","r":"November 4, 2003","l":"https://en.wikipedia.org/wiki/Risk:_Global_Domination","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/jocckrwuaffgdrxkxudd.jpg","s":"Take on master military strategists like Napoleon, Washington, Bolivar, Catherine the Great and more in a worldwide campaign for total world domination."},{"t":"Road Rash: Jailbreak","p":["Game Boy Advance"],"r":"September 11"},{"t":"RoadKill","p":["Xbox","PlayStation 2","GameCube"],"d":"Terminal Reality","u":"Midway","g":"Vehicular combat","r":"October 13, 2003","l":"https://en.wikipedia.org/wiki/RoadKill_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co90j3.jpg","s":"RoadKill is an open world action-adventure video game. It has been described as the only mission-based combat driving game set in a post-apocalyptic world.\nRoadKill is a vehicular combat game, and its gameplay is very similar to Twisted Metal, with a mission-based storyline and elements that share similarities to those from the Grand Theft Auto series."},{"t":"Robin Hood: Defender of the Crown","p":["PlayStation 2","Windows","Xbox"],"d":"Cinemaware, Atomic Planet Entertainment, Simian Industries","u":"Capcom, ZOO Digital Group, I-play","g":"Turn-based strategy","r":"September 30, 2003","l":"https://en.wikipedia.org/wiki/Robin_Hood:_Defender_of_the_Crown","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1oz3.jpg","s":"It is a time of great unrest in England. With King Richard the Lionheart held for ransom, the evil Prince John, seizes the throne, and declares himself the King of England. The entire nation soon falls into civil war as greedy nobles war amongst themselves and Prince John sends forth armies to shackle the country under his unjust rule.\n\nIn this time of lawlessness, only an outlaw can lead the people to freedom. One man, the embodiment of true honor, vows to save his people and restore peace to the land. This man is known as Robin Hood. From the small-scale skirmishes with the Sheriff of Nottingham in Sherwood Forest, Robin finds himself drawn into the larger the battlefields of England, and the hero of the poor must become the savior of an entire nation."},{"t":"RoboCop","p":["Xbox","Windows"],"u":"Titus Interactive","r":"July 24, 2003","l":"https://en.wikipedia.org/wiki/RoboCop_(2003_video_game)"},{"t":"Robot Arena 2: Design and Destroy","p":["Windows"],"d":"Gabriel Entertainment","u":"Infogrames","g":"Robot combat, Action","r":"February 18, 2003","l":"https://en.wikipedia.org/wiki/Robot_Arena_2:_Design_and_Destroy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co99p1.jpg","s":"Robot Arena: Design & Destroy is a PC game of robotic construction and combat. It is a sequel to the original Robot Arena. It's a simulation/arcade game based on robotic combat like you see on television. Robot Arena: Design & Destroy has more weapons, more accessories, more ACTION!\n\nPowered by the Havok Hardcore physics engine, bots can now bounce, flip, twirl and arenas are no longer just a flat box."},{"t":"Rock 'N Roll Racing","p":["Game Boy Advance"],"r":"June 23","l":"https://en.wikipedia.org/wiki/Rock_%27N_Roll_Racing"},{"t":"Rocket Mania!","p":["Windows","Windows Mobile","Mobile phone"],"d":"Nuclide Games","u":"PopCap Games","g":"Puzzle","r":"August 15, 2003","l":"https://en.wikipedia.org/wiki/Rocket_Mania!"},{"t":"Rockman EXE WS","p":["WonderSwan Color"],"d":"Tose","u":"Bandai","g":"Platform","r":"February 8, 2003","l":"https://en.wikipedia.org/wiki/Rockman_EXE_WS","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ba9.jpg","s":"Rockman.EXE WS is a side-scrolling, platform-based video game. The gameplay mainly consisted of shooting enemies and jumping through obstacles and platforms."},{"t":"Rogue Ops","p":["GameCube","PlayStation 2","Xbox"],"d":"Bits Studios","u":"Kemco","g":"Stealth","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Rogue_Ops","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ozd.jpg","s":"In Rogue Ops the player assumes the role of Nikki Connors, an ex-Green Beret whose husband and child are killed by Omega 19, a brutal terrorist organization. She then joins Phoenix, an almost as brutal counter-terrorism organization to seek revenge."},{"t":"Rollercoaster World","p":["PlayStation 2"],"g":"Simulator, Strategy","l":"https://en.wikipedia.org/wiki/Rollercoaster_World","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5y3m.jpg","s":"Rollercoaster World is an Theme Park or Rollercoaster Tycoon style game, where you build your own amusement park and its rollercoasters and you have to end each month with money on the account. The rollercoasters are designed in a four window 3D view, in the style of many 3D model editors."},{"t":"Rolling","p":["PlayStation 2","Xbox"],"d":"Rage Software","u":"SCi","g":"Sports","r":"October 24, 2003","l":"https://en.wikipedia.org/wiki/Rolling_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/bpets3i1fsaonkplmj1m.jpg"},{"t":"RTX Red Rock","p":["PlayStation 2"],"d":"LucasArts","u":"LucasArts","g":"Action-adventure","r":"June 17, 2003","l":"https://en.wikipedia.org/wiki/RTX_Red_Rock","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ozf.jpg","s":"In this game the player controls Major Eugene Wheeler, a radical tactics expert sent to the Mars base to investigate the loss of communications. Once there, he discovers that the base has been taken over by alien invaders who plan to use it to launch an attack on Earth. Wheeler must use all his wits and skills to prevent this from happening.\n\nRTX: Red Rock is a third-person action-adventure game which splits itself between combat with a multitude of weapons and some puzzle-solving. The protagonist is also equipped with a robotic arm with multiple attachments and a 'bionic' eye which gives him four different vision modes. The game is comprised of ten levels, some of which involve driving vehicles and controlling robots."},{"t":"Rubies of Eventide","p":["Windows"],"d":"Mnemosyne, LLC","u":"Mnemosyne, LLC","g":"Fantasy MMORPG","r":"June 2003","l":"https://en.wikipedia.org/wiki/Rubies_of_Eventide","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co93oc.jpg","s":"Rubies of Eventide was a free to play massively multiplayer online role-playing game (MMORPG) previously published by American studio Mnemosyne, LLC. Powered by the Lithtech Jupiter engine. It is set in the medieval fantasy world of Vormis represented by a 3D world.\n\nThe game launched in June 2003, then shut down and restarted and after 6 years, went offline in July 2009, subsequently ceased operation in August."},{"t":"Rugby 2004","p":["PlayStation 2","Windows"],"d":"HB Studios","u":"EA Sports","g":"Sports","r":"September 18, 2003","l":"https://en.wikipedia.org/wiki/Rugby_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8o66.jpg","s":"The official game of the 2003 Rugby Wold Cup in Australia, Rugby 2004 is the sequel to Rugby 2001 with HB Studios replacing The Creative Assembly as the developers.\n\nFully licensed by the IRB, Rugby 2004 features 75 stadiums from around the world, including all the World Cup venues, 95 teams including the British Lions and world champion Australian Wallabies and more than 2000 players each with individual names called by the BBC's John Inverdale and Channel 7's Gordon Bray.\n\nMajor additions to the game include Super 12 and European Cup provincial tournaments, a player editor, custom teams, skill challenges like those found in other EA Sports games and an exclusive soundtrack by INXS."},{"t":"Rugby League","p":["Windows","PlayStation 2","Xbox"],"d":"Sidhe Interactive","u":"Tru Blu Entertainment","g":"Sports","r":"December 12, 2003","l":"https://en.wikipedia.org/wiki/Rugby_League_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2u4t.jpg","s":"NRL Rugby League is a New Zealand-developed rugby sports game in the tradition of console based sports titles. It features 30 licensed teams, several major leagues and interantional test matches, 25 realistic stadiums, commentary by Andrew Voss, variable weather conditions, and all the action on the field you would expect from a game based on the sport, including advanced moves such as offloads, fend offs, side steps and dummy passes. You can create your own players, teams and competitions, with detailed statistics, and you have to take injuries, sin bins and send offs into account."},{"t":"Samorost","p":["Browser","Windows","macOS"],"d":"Amanita Design","u":"Amanita Design","g":"Adventure, art game","l":"https://en.wikipedia.org/wiki/Samorost","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2224.jpg","s":"Samorost is a short point-and-click adventure game. The goal is to help the little space gnome save his home asteroid from a collision with another asteroid by solving diverse puzzles."},{"t":"Samurai Jack: The Amulet of Time","p":["Game Boy Advance"],"r":"March 25"},{"t":"Samurai Shodown V","p":["Arcade","Neo Geo AES","PlayStation 2","Xbox"],"d":"Yuki Enterprise","u":"SNK Playmore, Ignition Entertainment","g":"Fighting","r":"October 10, 2003","l":"https://en.wikipedia.org/wiki/Samurai_Shodown_V","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2t4d.jpg","s":"Samurai Shodown V brings back the classic side-scrolling action with a completely new storyline, new characters and new moves. A samurai's quest to prove himself against the Shogun leads to a gathering of the world's greatest warriors to compete for the right to be named the greatest."},{"t":"Savage: The Battle for Newerth","p":["Linux","Windows"],"d":"S2 Games","u":"iGames","g":"Real-time strategy, first-person shooter","r":"September 9, 2003","l":"https://en.wikipedia.org/wiki/Savage:_The_Battle_for_Newerth","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3coe.jpg","s":"Savage: The Battle for Newerth was originally released by S2 Games in September 2003 and eventually became freeware 3 years later in September 2006, when the game has been officially abandoned and made open source. The last official patch (2.0e) came out in January 2004. Since then Savage: The Battle for Newerth has been continuously improved by the Savage community: from 2004 to 2005 by the EX2 team, from 2005 to 2007 by the SEP/SFE team and since 2008 by the Savage XR team.\n\nAlthough the game has been criticized for being released in an unpolished state, lacking basic features and any kind of tutorials, Savage: The Battle for Newerth with its innovative RTS/FPS gameplay was far ahead of its time, winning awards such as the Seumas McNally Grand Prize, Technical Excellence and the Audience Award at the Independent Games Festival 2004 or the Editor's Choice Award \"8.7 - Great\" by IGN.com."},{"t":"Saya no Uta: The Song of Saya","p":["Windows"],"d":"Nitroplus","u":"Nitroplus, JAST USA","g":"Visual novel, eroge","r":"December 26, 2003","l":"https://en.wikipedia.org/wiki/Saya_no_Uta:_The_Song_of_Saya"},{"t":"Scary Maze Game","p":["Browser"],"d":"Jeremy Winterrowd","g":"Maze, horror","l":"https://en.wikipedia.org/wiki/Scary_Maze_Game","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8gax.jpg","s":"Also commonly known as \"Scary Maze Game,\" it became popular around the early 2000s as a \"screamer\" prank to jump-scare people. Gameplay consists of avoiding touching the walls with your mouse cursor to reach the end of the maze. These walls get closer together after each level, making the path the player must travel through narrower.\n\nInfamously, when the player is close to reaching the end of level 3, a picture of the possessed girl from The Exorcist flashes on the screen against the sounds of loud screaming."},{"t":"Seal Online","p":["Windows"],"d":"Grigon Entertainment, PLAYWITH Games","u":"PLAYWITH Interactive","g":"Fantasy MMORPG","r":"July 16, 2003","l":"https://en.wikipedia.org/wiki/Seal_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co73x6.jpg","s":"Seal Online is a Massively Multiplayer Online Role-Playing game launched in 2007 on United States by Playwith Interactive being one of the most durable and remarkable tittles nowadays. All begins when the world was first created, it was peaceful and everyone’s lives were bountiful under the auspices of the benign Elims. However, when the Balie was born from the Elim’s shadows, chaos ensued over the land. The endless war between the Elims and the Balies razed the world and the earth were no longer able to embrace anything. Elios, the Elim’s Master held fast to a piece crumbling land and collected all the Elims, Balies, and other dying organisms on top of it. That is how Shiltz was created. Players have to choose between 8 classes each one with 2 specializations to be learned at lvl 150, for example, the Craftman that can become a great Artisan or a ruthless Demolitionist. There are also special contents like Couples system with exclusive game store, fishing, crafting, refining, pets raising, battle pets, street kiosks and acquiring fame to become popular on the server!"},{"t":"SeaWorld Adventure Parks Tycoon","p":["Windows"],"r":"October 22","l":"https://en.wikipedia.org/wiki/SeaWorld_Adventure_Parks_Tycoon"},{"t":"Second Life","p":["Windows","Linux","macOS"],"g":"Simulator","l":"https://en.wikipedia.org/wiki/Second_Life","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coavc9.jpg","s":"Travel with friends to thousands of beautiful and exciting places — all created by the Second Life community.\n\nFilled with Friends, millions of people have already joined Second Life. Chat for free using voice or text with folks from around the world who share your passions and interests."},{"t":"Secret Maryo Chronicles","p":["Amiga","Windows","Linux"],"d":"SMC Team","g":"Platform","r":"January 23, 2003","l":"https://en.wikipedia.org/wiki/Secret_Maryo_Chronicles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co271v.jpg","s":"Secret Maryo Chronicles is a free and open-source two-dimensional platform computer game that began in 2003."},{"t":"Secret Service 2","p":["Windows"],"d":"4D Rulers","u":"Activision Value","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Secret_Service_2"},{"t":"Secret Weapons Over Normandy","p":["PlayStation 2","Xbox","Windows"],"d":"Totally Games","u":"LucasArts","g":"Combat flight simulation","r":"November 18, 2003","l":"https://en.wikipedia.org/wiki/Secret_Weapons_Over_Normandy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5w3e.jpg","s":"Secret Weapons Over Normandy or SWON is a World War II-based arcade flight simulation video game released on November 18, 2003. Published by LucasArts and developed by Totally Games, the game is composed of 15 objective-based missions set in 1940s European, North African, and the Pacific theatres of war. The story was written by Derek Chester, who is also famous for his work in Star Trek: Deep Space Nine as well as work on Star Trek videogames. The music was composed by Michael Giacchino."},{"t":"Sega Arcade Gallery","p":["Game Boy Advance"],"d":"Bits Studios","u":"Sega, THQ","g":"Various","r":"May 22, 2003","l":"https://en.wikipedia.org/wiki/Sega_Arcade_Gallery"},{"t":"Seiklus","p":["Windows","macOS"],"u":"Independent","g":"Platform game","l":"https://en.wikipedia.org/wiki/Seiklus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4pyg.jpg","s":"Seiklus is a puzzle platform game with an emphasis on exploration and adventure. There is no dialogue or literary exposition of the plot. The main goal of the game is to collect colored balls of light while you explore the world. Seiklus has no weapons and no violence. There are various \"hostile\" lifeforms in some areas, but at worst they only set the player back a little. It is impossible to die or get stuck."},{"t":"Sexfriend","p":[],"l":"https://en.wikipedia.org/wiki/Sexfriend"},{"t":"Shadow of Memories","p":["Windows"],"r":"February 7","l":"https://en.wikipedia.org/wiki/Shadow_of_Memories"},{"t":"Shadow Tower Abyss","p":["PlayStation 2"],"d":"FromSoftware","u":"FromSoftware","g":"Role-playing game","r":"October 23, 2003","l":"https://en.wikipedia.org/wiki/Shadow_Tower_Abyss","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co39vl.jpg","s":"Shadow Tower Abyss is a dark fantasy role-playing video game, developed and published by From Software in Japan for the PlayStation 2. The game is a sequel to Shadow Tower, and features a number of genre and mechanical elements that can also be found in Demon's Souls and the King's Field series."},{"t":"Shadowbane","p":["Windows","macOS"],"d":"Wolfpack Studios, Stray Bullet Games","u":"Ubi Soft","g":"MMORPG","r":"March 25, 2003","l":"https://en.wikipedia.org/wiki/Shadowbane"},{"t":"ShadowFlare","p":["Windows"],"d":"Denyusha","u":"Emurasoft","g":"Action role-playing, hack and slash","r":"February 13, 2003","l":"https://en.wikipedia.org/wiki/ShadowFlare"},{"t":"Shin Megami Tensei III: Nocturne","p":["PlayStation 2"],"r":"February 20"},{"t":"Shining Soul II","p":["Game Boy Advance"],"d":"Grasshopper Manufacture","u":"Sega, THQ, Atlus USA","g":"Action role-playing","r":"July 24, 2003","l":"https://en.wikipedia.org/wiki/Shining_Soul_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4pug.jpg","s":"As monsters begin to appear in the kingdom Klantol, King Marcel announces a grand tournament at the coliseum to find a hero that can protect the country. Now, as a mighty Brawler, Priestess, Dark Wizard, or Ninja, you must accept the king's challenge. Each character has certain strengths and weaknesses that can mean the difference between victory and defeat in single-player, multiplayer, or cooperative multiplayer modes. In addition to valuable weapons and armor, you can equip your party with Force Links, which, when combined, create a Shining Force--a powerful weapon capable of decimating the enemy forces."},{"t":"Shrek: Reekin' Havoc","p":["Game Boy Advance"],"r":"July 30"},{"t":"Silent Hill 3","p":["PlayStation 2","Windows"],"r":"May 23","l":"https://en.wikipedia.org/wiki/Silent_Hill_3"},{"t":"Silent Line: Armored Core","p":["PlayStation 2"],"d":"FromSoftware","u":"FromSoftware, Agetec","g":"Third-person shooter","r":"January 23, 2003","l":"https://en.wikipedia.org/wiki/Silent_Line:_Armored_Core","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p0e.jpg","s":"Explorers have uncovered a previously unknown megacity that is well protected from scouting incursions. When all attempts at penetrating the border are met with destruction, the call goes out to the Ravens, a team of mercenaries hired by the government. As a Raven, you must pilot armored mech suits and destroy enemy weapon systems. A new first-person view allows you to experience a mission from the cockpit. Silent Line: Armored Core also lets you go head-to-head with up to four players or team up for fierce two-on-two battles."},{"t":"Silent Storm","p":["Windows"],"d":"Nival Interactive","u":"1C Company, JoWooD Productions, Encore Software","g":"Turn-based tactics, tactical RPG","r":"August 22, 2003","l":"https://en.wikipedia.org/wiki/Silent_Storm","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1q79.jpg","s":"1943: The world seems to face its destruction in all parts; war is raging like never before. You are the commander of a squad, leading the soldiers you’ve selected into special and top secret operations to change the tide of war in your favour – allies or axis."},{"t":"SimCity 4","p":["Windows"],"r":"January 14","l":"https://en.wikipedia.org/wiki/SimCity_4"},{"t":"SimCity 4: Rush Hour","p":["Windows"],"d":"Maxis","u":"EA Games, Aspyr Media","g":"City-building","r":"September 22, 2003","l":"https://en.wikipedia.org/wiki/SimCity_4:_Rush_Hour"},{"t":"Singles: Flirt Up Your Life","p":["Windows"],"d":"Rotobee","u":"Deep Silver","g":"Social simulation","r":"April 2, 2003","l":"https://en.wikipedia.org/wiki/Singles:_Flirt_Up_Your_Life","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/zfmse3j9afozdef1ccws.jpg"},{"t":"Siren","p":["PlayStation 2"],"r":"April 20","l":"https://en.wikipedia.org/wiki/Siren_(video_game)"},{"t":"Slime Mori Mori Dragon Quest","p":["Game Boy Advance"],"d":"Tose","u":"Square Enix","g":"Action-adventure","r":"November 14, 2003","l":"https://en.wikipedia.org/wiki/Slime_Mori_Mori_Dragon_Quest"},{"t":"Slouching Towards Bedlam","p":["Windows","Linux","Browser","macOS"],"d":"Daniel Ravipinto, Star Foster","u":"Self-published","g":"Interactive fiction, adventure","l":"https://en.wikipedia.org/wiki/Slouching_Towards_Bedlam","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/kidx9afsdrydzquer8s6.jpg","s":"Enter a steampunk adventure set in a London that might have been. The year is 1885. Bedlam Hospital still stands in Moorsfield, a decaying shell used to house the poor and the hopeless. Steam-driven mechanical wonders roam the streets. Gear-wheeled analytical engines spin out reams of thought onto punched paper tapes. And in the darkness – in the alleys and the side shops – hide secrets. A piece of interactive fiction written by Star Foster and Daniel Ravipinto."},{"t":"SNK vs. Capcom: SVC Chaos","p":["Arcade","Neo Geo AES","PlayStation 2"],"d":"SNK Playmore, Code Mystics","u":"SNK Playmore, Ignition Entertainment","g":"Fighting","r":"July 2003","l":"https://en.wikipedia.org/wiki/SNK_vs._Capcom:_SVC_Chaos","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ydh.jpg","s":"SNK vs. Capcom: SVC Chaos primarily utilizes the command system of The King of Fighters series, incorporating light/strong kicks, punches, cancels and charging attacks. Unlike its predecessor, Capcom vs. SNK 2, this game lacks both air guards and a \"groove system\", instead focusing on quicker gameplay. Characters are provided with a basic 3-level bar system for executing super-special attacks with basic filling options attributed to strikes and damage. Additionally, the sprites from the various series received new models and some special effects were changed in the command lists (for example, the player cannot increase the damage of the Zujou Sashi used by Choi Bounge by tapping the buttons anymore)."},{"t":"Snow","p":["Windows"],"g":"Visual Novel","l":"https://en.wikipedia.org/wiki/Snow_(2003_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobrr9.jpg","s":"The story of Snow starts when the main protagonist Izumo Kanata visits a small village called Ryujinmura (village of the dragon god) to help his cousin Tsugumi manage a local hotel with hot springs. In the village there is an old legend: In ancient times, the village is protected by the dragon goddess. However, one day the dragon goddesses fell in love with a human, which is strictly forbidden, and this incident finally caused the village to be always covered by snow after that. The game then tells the daily life of the protagonist in the village, and finally links the story to the legend of dragon goddess."},{"t":"Snow Sakura","p":["Windows"],"d":"D.O.","u":"D.O., G-Collections","g":"Eroge, visual novel, bishōjo game, comedy","r":"November 28, 2003","l":"https://en.wikipedia.org/wiki/Snow_Sakura"},{"t":"SOCOM II U.S. Navy SEALs","p":["PlayStation 2"],"r":"November 4","l":"https://en.wikipedia.org/wiki/SOCOM_II_U.S._Navy_SEALs"},{"t":"Sonic Advance","p":["N-Gage"],"r":"October 7","l":"https://en.wikipedia.org/wiki/Sonic_Advance"},{"t":"Sonic Advance 2","p":["Game Boy Advance"],"r":"March 9","l":"https://en.wikipedia.org/wiki/Sonic_Advance_2"},{"t":"Sonic Adventure DX: Director's Cut","p":["GameCube"],"r":"June 18","l":"https://en.wikipedia.org/wiki/Sonic_Adventure#Sonic_Adventure_DX"},{"t":"Sonic Heroes","p":["PlayStation 2","Xbox","GameCube"],"r":"December 4","l":"https://en.wikipedia.org/wiki/Sonic_Heroes"},{"t":"Sonic Pinball Party","p":["Game Boy Advance"],"r":"June 1","l":"https://en.wikipedia.org/wiki/Sonic_Pinball_Party"},{"t":"Soulcalibur II","p":["GameCube","Xbox","PlayStation 2"],"u":"Namco","r":"March 27, 2003","l":"https://en.wikipedia.org/wiki/Soulcalibur_II"},{"t":"Space Channel 5 Special Edition","p":["PlayStation 2"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Space_Channel_5"},{"t":"Space Channel 5: Ulala's Cosmic Attack","p":["Game Boy Advance"],"r":"June 17","l":"https://en.wikipedia.org/wiki/Space_Channel_5"},{"t":"Space Colony","p":["Windows","macOS"],"d":"Firefly Studios","u":"Gathering","g":"Real-time strategy, life simulation","r":"September 26, 2003","l":"https://en.wikipedia.org/wiki/Space_Colony_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e48.jpg","s":"Space Colony: Steam Edition is a remaster of the real-time base builder and strategy game from Firefly Studios, creators of the Stronghold series. In Space Colony you colonize to survive, designing intergalactic bases that keep your crew productive, happy and defended against hostile alien threats."},{"t":"Space Empires: Starfury","p":["Windows"],"d":"Malfador Machinations","u":"Shrapnel Games","g":"Turn-based strategy, 4X","r":"October 3, 2003","l":"https://en.wikipedia.org/wiki/Space_Empires:_Starfury","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ivi.jpg","s":"Space Empires: Starfury is a new installment in the long-lasting Space Empires series. No more tiny 2D graphics this time - Starfury features a first-person perspective from a lone ship and a all-new real-time 3D rendering engine. As captain of your battle cruiser, you'll travel through solar systems via warp points, explore the galaxy, engage in furious space combat, and join in large fleet operations. Starfury allows you to completely customize your starship and has a complex ship combat model. Multiple campaigns with a vast array of missions will challenge you to hold back the forces that threaten your race, and to make a little money on the side!\n\nAs always, the game is completely open: you can alter the game's structure and create custom mods and skins."},{"t":"Space Invaders Anniversary","p":["PlayStation 2","Arcade","Windows"],"g":"Arcade","l":"https://en.wikipedia.org/wiki/Space_Invaders_Anniversary","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9i9i.jpg","s":"Space Invaders Anniversary celebrates the 25th anniversary of the oldest Taito franchise."},{"t":"Space Station 13","p":["Windows"],"r":"February 15","l":"https://en.wikipedia.org/wiki/Space_Station_13"},{"t":"Space Tanks","p":["Windows"],"d":"YawThrust Software Labs.","u":"Alten8, Akella, Pepper Games, Tewi Publishing","g":"strategy game","l":"https://en.wikipedia.org/wiki/Space_Tanks"},{"t":"Spawn: Armageddon","p":["PlayStation 2","GameCube","Xbox"],"d":"Point of View","u":"Namco Hometek, Electronic Arts, Namco","g":"Action-adventure, hack and slash","r":"November 21, 2003","l":"https://en.wikipedia.org/wiki/Spawn:_Armageddon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dzc.jpg","s":"Spawn: Armageddon is a 3D action/adventure game based on the comic by Todd McFarlane, who also contributed the storyline for the game. Spawn struggles between the forces of Heaven and Hell in order to save the world, equipped with his Hell-sent living symbiotic suit and its chains. A multitude of weapons and Hell Powers are also available. Agony, the axe that Spawn uses in SoulCalibur II is also available as a melee attack weapon."},{"t":"Special Force","p":["Windows"],"d":"Hadeel","u":"Hezbollah Central Internet Bureau","g":"First-person shooter","r":"February 16, 2003","l":"https://en.wikipedia.org/wiki/Special_Force_(2003_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob70u.jpg","s":"A 2003 first-person shooter produced by the Central Internet Bureau of Hezbollah, a Lebanese Islamist militant group. The game recreates battles from the South Lebanon conflict between Hezbollah and Israel, with the player assuming the role of a Hezbollah fighter tasked with defeating Israeli soldiers."},{"t":"Speed Kings","p":["GameCube","PlayStation 2","Xbox"],"d":"Climax London","u":"Acclaim Entertainment","g":"Racing","r":"May 28, 2003","l":"https://en.wikipedia.org/wiki/Speed_Kings","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p14.jpg"},{"t":"SpellForce: The Order of Dawn","p":["Windows"],"r":"November 28"},{"t":"Sphinx and the Cursed Mummy","p":["GameCube","PlayStation 2","Xbox"],"r":"November 10","l":"https://en.wikipedia.org/wiki/Sphinx_and_the_Cursed_Mummy"},{"t":"SplashDown: Rides Gone Wild","p":["PlayStation 2"],"r":"August 6"},{"t":"SpongeBob SquarePants: Battle for Bikini Bottom","p":["Windows","GameCube","PlayStation 2","Xbox","Game Boy Advance"],"r":"October 29"},{"t":"Spy Fiction","p":["PlayStation 2"],"d":"Access Games","u":"Sammy","g":"Action-adventure, stealth","r":"December 25, 2003","l":"https://en.wikipedia.org/wiki/Spy_Fiction","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p1d.jpg","s":"Spy Fiction is an action-stealth game combining exciting espionage action with a thrilling story line. During your missions, you'll have to assume the identity of others and steal identifying characteristics like voice and appearance. Also included are action-oriented minigames such as parachuting and rappelling. New gadgets like the optical camouflage suit and spider grips round out your spy tools and let you avoid detection. Travel to locations around the world as one of two playable characters and live the shadowy life of a spy."},{"t":"Spy Muppets: License to Croak","p":["Game Boy Advance"],"r":"November 18"},{"t":"SpyHunter 2","p":["PlayStation 2","Xbox"],"d":"Angel Studios","u":"Midway Games","g":"Vehicular combat","r":"November 24, 2003","l":"https://en.wikipedia.org/wiki/SpyHunter_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co90ug.jpg","s":"Shift into something more lethal.\nThe hunt begins again with SpyHunter 2. The ultimate high-speed combat thrill ride continues with the world's most powerful counterintelligence vehicle, the all-new G-B155 Interceptor. Uncover Nostra's sinister plans for world domination and discover the secrets of a mysterious female agent before it's too late."},{"t":"Spyro: Attack of the Rhynocs","p":["Game Boy Advance"],"r":"October 27"},{"t":"SSX 3","p":["PlayStation 2","GameCube","Xbox","Game Boy Advance"],"u":"EA Sports","r":"October 20, 2003","l":"https://en.wikipedia.org/wiki/SSX_3"},{"t":"Stake: Fortune Fighters","p":["Xbox"],"u":"Metro3D, Inc.","r":"May 5, 2003"},{"t":"Star Chamber: The Harbinger Saga","p":["Windows","macOS"],"d":"Nayantara Studios","u":"Matrix Games","g":"Online collectible card game, turn-based strategy","r":"November 13, 2003","l":"https://en.wikipedia.org/wiki/Star_Chamber:_The_Harbinger_Saga"},{"t":"Star Ocean: Till the End of Time","p":["PlayStation 2"],"d":"tri-Ace","u":"Enix, Square Enix, Ubisoft","g":"Action role-playing","r":"February 27, 2003","l":"https://en.wikipedia.org/wiki/Star_Ocean:_Till_the_End_of_Time","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p1j.jpg","s":"Released as \"Star Ocean 3: Till the End of Time\" in 2003 by Enix before they merged with Squaresoft, the game was re-released under the name \"Star Ocean: Till the End of Time\" as a remastered version by Square Enix in 2004."},{"t":"Star Trek: Elite Force II","p":["Windows"],"r":"June 20"},{"t":"Star Wars Galaxies","p":["Windows"],"d":"Sony Online Entertainment","u":"LucasArts","g":"Massively multiplayer online role-playing","r":"June 26, 2003","l":"https://en.wikipedia.org/wiki/Star_Wars_Galaxies"},{"t":"Star Wars Galaxies: An Empire Divided","p":["Windows"],"r":"July 9"},{"t":"Star Wars Jedi Knight: Jedi Academy","p":["Windows","Xbox"],"g":"Action","r":"September 17","l":"https://store.steampowered.com/app/6020","i":"images/steam-6020.jpg","s":"Forge your weapon and follow the path of the Jedi Jedi Knight: Jedi Academy is the latest installment of the highly acclaimed Jedi Knight series. Take on the role of a new student eager to learn the ways of the Force from Jedi Master Luke Skywalker."},{"t":"Star Wars Rogue Squadron III: Rebel Strike","p":["GameCube"],"d":"Factor 5","u":"LucasArts","g":"Action","r":"October 21, 2003","l":"https://en.wikipedia.org/wiki/Star_Wars_Rogue_Squadron_III:_Rebel_Strike","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w3t.jpg","s":"X-wings, B-wings, speeder bikes, AT-STs, tauntauns--you'll have to master them all to save Luke, Wedge, Han, Chewie, and Leia from Darth Vader and his Imperial forces. All new multiplayer modes include the entire Rogue Leader game in co-op, plus endurance, capture-the-base, and dogfight modes.\n\nCinematic realism takes you to new heights as you climb out of your cockpit to battle the Empire on foot in this thrilling third chapter of the Rogue Squadron series."},{"t":"Star Wars: Flight of the Falcon","p":["Game Boy Advance"],"r":"November 18"},{"t":"Star Wars: Knights of the Old Republic","p":["Xbox","Windows"],"u":"LucasArts","g":"Adventure, RPG","r":"July 15, 2003","l":"https://store.steampowered.com/app/32370","i":"images/steam-32370.jpg","s":"It is four thousand years before the Galactic Empire and hundreds of Jedi Knights have fallen in battle against the ruthless Sith. You are the last hope of the Jedi Order. Can you master the awesome power of the Force on your quest to save the Republic? Or will you fall to the lure of the dark side?"},{"t":"Starscape","p":["Windows"],"d":"Moonpod","u":"Moonpod, Snowball Studios","g":"Multidirectional shooter","l":"https://en.wikipedia.org/wiki/Starscape"},{"t":"Starsky & Hutch","p":["Game Boy Advance"],"r":"September 12","l":"https://en.wikipedia.org/wiki/Starsky_%26_Hutch_(video_game)"},{"t":"Stranded","p":["Windows"],"d":"Unreal Software","u":"Unreal Software","g":"Action-adventure, survival","l":"https://en.wikipedia.org/wiki/Stranded_(video_game)"},{"t":"Street Chaves","p":["Windows"],"d":"CyberGamba","u":"CyberGamba","g":"Fighting","l":"https://en.wikipedia.org/wiki/Street_Chaves","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2uiy.jpg","s":"An independent fighting game with a roster of characters from El Chavo del Ocho (Chaves in Portuguese) sitcom."},{"t":"Street Legal Racing: Redline","p":["Windows"],"d":"Invictus Games","u":"Activision Value","g":"Racing","r":"July 18, 2003","l":"https://en.wikipedia.org/wiki/Street_Legal_Racing:_Redline","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2267.jpg","s":"The game takes place in Valo City, a metropolis known for its vast underworld of illegal street racing. The plot of the game is to beat every club and accomplish the requirements to enter the Race of Champions, a prestigious racing competition where one can win a bonus car. Players have to race others on the streets during the day for prestige (respect) or money to customize the car. During the night, players can either participate in a drag race against another driver or watch the race."},{"t":"Stuntman","p":["Game Boy Advance"],"r":"June 24","l":"https://en.wikipedia.org/wiki/Stuntman_(video_game)"},{"t":"Summer Heat Beach Volleyball","p":["PlayStation 2"],"d":"Acclaim Studios Cheltenham","u":"Acclaim Entertainment","g":"Sports","r":"June 30, 2003","l":"https://en.wikipedia.org/wiki/Summer_Heat_Beach_Volleyball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p1y.jpg","s":"Following in the same vein as Dead Or Alive: Xtreme Beach Volleyball, hot girls in bikini's playing beach volleyball comes to the Playstation 2 in the form of Summer Heat Beach Volleyball.\n\nThe game features both male and female competitors from around the world and follows the rules of 2 on 2 volleyball. Unlike Beach Spikers you only control one player on your team, the other player is controlled by the game, unless you play a 2-player co-operative game. There are 12 different locations in the game and 14 playable characters, each with their own statistics.\n\nThe game features Arcade, Exhibition, Summer Heat US Tour and Training modes. As you progress thorugh the different modes, you unlock items of clothing, music videos, courts and more. There are also mini-games to be played.\n\nYou can also relax at the Beach House were you can watch videos, listen to music and check out your trophies."},{"t":"Summer Radish Vacation!!","p":[],"l":"https://en.wikipedia.org/wiki/Summer_Radish_Vacation!!"},{"t":"Summon Night 3","p":["PlayStation 2","PlayStation Portable"],"d":"Flight-Plan, Felistella","u":"Banpresto, Namco Bandai Games","g":"Tactical RPG","r":"August 7, 2003","l":"https://en.wikipedia.org/wiki/Summon_Night_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p20.jpg","s":"Summon Night 3 is a Japanese tactical RPG and the third entry in the Summon Night series. The game follows the male main protagonist Rexx and the female protagonist Aty. As with other game's in the series, it takes place in the fictional world of Linbaum. The game contains multiple difficulty levels."},{"t":"Summon Night: Swordcraft Story","p":["Game Boy Advance"],"d":"Flight-Plan","u":"Banpresto, Atlus","g":"Action role-playing game","r":"April 25, 2003","l":"https://en.wikipedia.org/wiki/Summon_Night:_Swordcraft_Story","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2srk.jpg","s":"Summon Night: Swordcraft Story is an RPG set in the strange world of Lyndbaum, a sacred land linked to four magical dimensions from which Summoners can call forth spirits called Guardian Beasts to do their bidding."},{"t":"Super Bubble Pop","p":["GameCube","Game Boy Advance"],"r":"January 3","l":"https://en.wikipedia.org/wiki/Super_Bubble_Pop"},{"t":"Super Duper Sumos","p":["Game Boy Advance"],"r":"October 26","l":"https://en.wikipedia.org/wiki/Super_Duper_Sumos"},{"t":"Super Farm","p":["PlayStation 2"],"d":"Asobo Studio","u":"Ignition Entertainment","g":"Party, Platformer","l":"https://en.wikipedia.org/wiki/Super_Farm","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4v7d.jpg","s":"Super Farm is a party video game with a farmyard theme developed by Asobo Studio and published by Ignition Entertainment for the PlayStation 2. The game was re-released for Windows 8 in 2013 to commemorate its 10th anniversary."},{"t":"Super Mario Advance 4: Super Mario Bros. 3","p":["Game Boy Advance"],"u":"Nintendo","r":"October 21, 2003"},{"t":"Superball Arcade","p":["Windows"],"d":"Cheeky Monkey","u":"Cheeky Monkey","g":"Breakout","r":"May 29, 2003","l":"https://en.wikipedia.org/wiki/Superball_Arcade"},{"t":"Superman: Countdown to Apokolips","p":["Game Boy Advance"],"r":"March 26"},{"t":"Survival Project","p":["Windows"],"d":"I.O. Entertainment","u":"HanbitSoft","g":"Action RPG, MMORPG","r":"February 17, 2003","l":"https://en.wikipedia.org/wiki/Survival_Project"},{"t":"SWAT: Global Strike Team","p":["PlayStation 2","Xbox"],"r":"October 28"},{"t":"Sword of Mana","p":["Game Boy Advance"],"d":"Square Enix, Brownie Brown","u":"Square Enix, Nintendo","g":"Action role-playing","r":"August 29, 2003","l":"https://en.wikipedia.org/wiki/Sword_of_Mana","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4pw9.jpg","s":"The Mana Tree Needs Defenders!\n\nThe location of the Mana Tree - wellspring of all life - has long been lost to legend. Many centuries have passed, and the Granz Realm's Dark Lord is searching for the secrets of the ancient tree so that he can control the source of Mana. Now, a young hero and heroine must come together to defeat the evil that threatens both the mystical tree and the world itself.\n\nChoose your hero! Guide a battle-hardened gladiator on his quest to avenge the deaths of his parents!\n\n...Or guide a young girl, one of the last survivors of the Mana Clan, as she confronts the past that haunts her.\n\nExperience the saga of these two heroes as their stories weave together and they join forces to protect the Mana Tree from the powers of darkness."},{"t":"SX Superstar","p":["GameCube","PlayStation 2","Xbox"],"d":"Climax Solent","u":"Acclaim Entertainment","g":"Racing","r":"June 30, 2003","l":"https://en.wikipedia.org/wiki/SX_Superstar","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ed2.jpg","s":"SX Superstar is a video game of the racing genre by Climax Studios and published by Acclaim under their AKA Acclaim brand. It was released for the Xbox, GameCube, and PlayStation 2."},{"t":"Tak and the Power of Juju","p":["GameCube","PlayStation 2","Game Boy Advance"],"r":"October 15","l":"https://en.wikipedia.org/wiki/Tak_and_the_Power_of_Juju"},{"t":"TalesWeaver","p":["Windows"],"d":"Softmax","u":"Nexon","g":"MMORPG","r":"June 2003","l":"https://en.wikipedia.org/wiki/TalesWeaver","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2se5.jpg","s":"TalesWeaver is a 2D fantasy MMORPG developed by SoftMax based on Children of the Rune, a Korean novel by Jeon Min-hee."},{"t":"Tao Feng: Fist of the Lotus","p":["Xbox"],"d":"Studio Gigante","u":"Microsoft Game Studios","g":"Fighting","r":"March 18, 2003","l":"https://en.wikipedia.org/wiki/Tao_Feng:_Fist_of_the_Lotus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6amx.jpg","s":"Clothes will tear, blood will spill, and bones will break in the brutal fighting game Tao Feng: Fist of the Lotus. On the vicious streets and back-alleyways of New China, two fierce fighting sects battle in a race to uncover a valuable prize. During your fights throughout interactive environments, your fighter reflects all the physical damage he or she receives from opponents. You can either heal yourself from the beatings or build your powers to unleash devastating Chi attacks."},{"t":"Taxi 3","p":["Game Boy Advance"],"d":"Visual Impact","u":"Ubisoft","g":"Racing","r":"January 2003","l":"https://en.wikipedia.org/wiki/Taxi_3_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2yrw.jpg","s":"Taxi 3 is a Racing game, developed by Ubisoft Montreal and published by Ubisoft, which was released in Europe in 2003.\n\nThe game is based on the 2003 French action comedy film."},{"t":"Teenage Mutant Ninja Turtles","p":["Windows","GameCube","PlayStation 2","Xbox"],"r":"October 21","l":"https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles_(2003_video_game)"},{"t":"Teku-Teku Mappy","p":["Mobile phone"],"d":"Namco","u":"Namco","g":"Puzzle","r":"February 14, 2003","l":"https://en.wikipedia.org/wiki/Teku-Teku_Mappy"},{"t":"Tenchu: Wrath of Heaven","p":["PlayStation 2"],"r":"March 3"},{"t":"Terminator 3: Rise of the Machines","p":["Xbox","Game Boy Advance"],"u":"Atari","r":"November 11, 2003"},{"t":"Terminator 3: War of the Machines","p":["Windows"],"u":"Atari","r":"November, 2003"},{"t":"The Adventures of Fatman","p":["Windows"],"d":"SOCKO! Entertainment","u":"SOCKO! Entertainment","g":"Point-and-click adventure","r":"May 2003","l":"https://en.wikipedia.org/wiki/The_Adventures_of_Fatman","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co430s.jpg","s":"You are Fatman - the heroic crime fighter for the city of Shadowlawn. It is up to you, then, to tear yourself away from food long enough to save the city from certain destruction..."},{"t":"The Adventures of Jimmy Neutron Boy Genius: Jet Fusion","p":["Game Boy Advance"],"r":"September 24"},{"t":"The Battle for Wesnoth","p":[],"l":"https://en.wikipedia.org/wiki/The_Battle_for_Wesnoth"},{"t":"The Black Mirror","p":["Windows"],"d":"Future Games","u":"Future Games, The Adventure Company, GMX Media","g":"Adventure","r":"March 15, 2003","l":"https://en.wikipedia.org/wiki/The_Black_Mirror_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co211n.jpg","s":"Black Mirror is a dark adventure game that details the aftermath of the tragic death of William Gordon. Playing as his grandson Samuel players must unveil the truth behind the events of that fateful, stormy night."},{"t":"The Cat in the Hat","p":["Game Boy Advance","Windows","PlayStation 2","Xbox"],"d":"Magenta Software, Digital Eclipse","u":"Vivendi Universal Games","g":"Platform","r":"November 4, 2003","l":"https://en.wikipedia.org/wiki/The_Cat_in_the_Hat_(video_game)"},{"t":"The Elder Scrolls III: Bloodmoon","p":["Windows","Xbox"],"d":"Bethesda Game Studios","u":"Bethesda Softworks","g":"Action role-playing","r":"June 3, 2003","l":"https://en.wikipedia.org/wiki/The_Elder_Scrolls_III:_Bloodmoon"},{"t":"The Elder Scrolls III: Morrowind – Game of the Year Edition","p":["Xbox"],"u":"Bethesda Softworks","r":"October 31, 2003"},{"t":"The Elder Scrolls Travels","p":[],"l":"https://en.wikipedia.org/wiki/The_Elder_Scrolls_Travels"},{"t":"The Elder Scrolls Travels: Stormhold","p":["Mobile phone"],"d":"Vir2L Studios","u":"Vir2L Studios, Mforma","g":"Role-playing","r":"July 2003","l":"https://en.wikipedia.org/wiki/The_Elder_Scrolls_Travels:_Stormhold","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3ahq.jpg"},{"t":"The Entente: Battlefields WW1","p":["Windows"],"d":"Lesta Studio","u":"Buka Entertainment, Encore, Inc.","g":"Real-time strategy","r":"August 13, 2003","l":"https://en.wikipedia.org/wiki/The_Entente:_Battlefields_WW1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/k36bl879x5nffxovshca.jpg","s":"On June 28, 1914 in the center of Saraevo Gavrilo Princip shot Archduke Franz Ferdinand and his wife. Those shots began one of the bloodiest wars in the history of mankind the First World War. For four long years the earth trembled from gun explosions, the air was whistling with bullets and the sky was covered with smoke and ashes. It was the first war with such amount of troops to take part in it and with military operations going on earth, in the skies and seas, even under the water. Weapons of mass destruction were used for the first time.\nThe Entente WWI Battlefields gives a chance to see it with your own eyes and try to change the history. Choosing one of five available countries of this real time strategy game (France, Germany, Russia, Austro-Hungary, England) players get under command troops with various units starting from infantry and cavalry and ending with battleships. All units were made true from historical point of view by using archive documents and photos. Every nation has its own features, which allow you to use strengths and weaknesses of troops from different states.\n\nEconomic and military advisors are present in the game to facilitate control over economic and military development. Advisors assist in upgrades, obtaining resources and producing units. There are more than 1000 structures on the map and 80000 units, 3D sound and full encyclopedia of armament that give a chance to feel like high military commander entrusted with the fate of the nations."},{"t":"The Fairly OddParents: Breakin' da Rules","p":["Windows","GameCube","PlayStation 2","Xbox","Game Boy Advance"],"r":"November 18"},{"t":"The Getaway","p":["PlayStation 2"],"r":"January 19","l":"https://en.wikipedia.org/wiki/The_Getaway_(video_game)"},{"t":"The Great Escape","p":["Windows","PlayStation 2","Xbox"],"g":"Action, Adventure, Simulation, Strategy","r":"July 23","l":"https://en.wikipedia.org/wiki/The_Great_Escape_(2003_video_game)","i":"images/steam-814570.jpg","s":"Captured, but not defeated, you are being held in the notorious Heldentod camp. This small, converted castle in the middle of nowhere will be your home for the rest of the war—unless you can escape to rejoin the Allied Armies."},{"t":"The Haunted Mansion","p":["GameCube","PlayStation 2","Xbox"],"r":"October 14","l":"https://en.wikipedia.org/wiki/The_Haunted_Mansion_(video_game)"},{"t":"The Hobbit","p":["Game Boy Advance","Windows","GameCube","PlayStation 2","Xbox"],"r":"October 24","l":"https://en.wikipedia.org/wiki/The_Hobbit_(2003_video_game)"},{"t":"The Incredible Hulk","p":["Game Boy Advance"],"r":"May 28","l":"https://en.wikipedia.org/wiki/The_Incredible_Hulk_(2003_video_game)"},{"t":"The Italian Job","p":["GameCube"],"r":"July 17","l":"https://en.wikipedia.org/wiki/The_Italian_Job_(2003_video_game)"},{"t":"The Jungle Book Groove Party","p":["Windows","PlayStation","PlayStation 2"],"d":"Ubi Soft Montreal, Ubi Soft Shanghai","u":"Ubi Soft","l":"https://en.wikipedia.org/wiki/The_Jungle_Book_Groove_Party"},{"t":"The King of Fighters 2003","p":["Arcade"],"d":"SNK Playmore","u":"SNK Playmore, Mega Enterprise, Ignition Entertainment","g":"Fighting","r":"December 12, 2003","l":"https://en.wikipedia.org/wiki/The_King_of_Fighters_2003","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2p0y.jpg","s":"The King of Fighters 2003 is the tenth game in The King of Fighters series. It is the last game of the series to be based on the Neo-Geo MVS hardware, and the first game in the series that was developed and published under the SNK Playmore custody. It is also the first chapter of the \"Tales of Ash Saga\", the third story arc of the series, and the last game of the series with the year's release in the title."},{"t":"The King of Fighters EX2: Howling Blood","p":["Game Boy Advance"],"d":"Marvelous Entertainment, Hudson Soft","u":"Atlus","g":"Fighting","r":"January 1, 2003","l":"https://en.wikipedia.org/wiki/The_King_of_Fighters_EX2:_Howling_Blood","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5v41.jpg","s":"The King of Fighters EX2: Howling Blood is a fighting game released by Playmore, MMV and Sun-Tec for the Gameboy Advance. It is based on The King of Fighters 2000 and is the sequel of The King of Fighters EX. It was also ported for the N-Gage as The King of Fighters Extreme.\n\nLike its predecessor, The EX series takes place in an alternate timeline where the events of the NESTS Saga did not occur, as Kyo Kusanagi was found by Moe Habana rather than NESTS at the end of KOF '97, thus this game took place instead of KOF 2000 in the EX continuity."},{"t":"The Legend of Sword and Fairy 2","p":["Windows"],"d":"Softstar Entertainment Inc.","u":"Softstar Entertainment Inc.","g":"Role-playing","r":"January 23, 2003","l":"https://en.wikipedia.org/wiki/The_Legend_of_Sword_and_Fairy_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobbmd.jpg","s":"The Legend of Sword and Fairy 2 is an action role-playing game developed by the DOMO group (known for its role in developing the Xuan-Yuan Sword video game series) and the now defunct Crazy Boys group under the Taiwanese company Softstar Entertainment. It is the second installment in The Legend of Sword and Fairy (or Chinese Paladin) video game series, and serves as a sequel to the first game. The game incorporates elements of wuxia, shenmo and fantasy."},{"t":"The Legend of Zelda Collector's Edition","p":["GameCube"],"u":"Nintendo","r":"November 17, 2003"},{"t":"The Legend of Zelda: The Wind Waker","p":["GameCube"],"r":"March 24"},{"t":"The Lion King 1½","p":["Game Boy Advance"],"d":"Vicarious Visions","u":"Disney Interactive, THQ","g":"Platform","r":"October 7, 2003","l":"https://en.wikipedia.org/wiki/The_Lion_King_1%C2%BD_(video_game)"},{"t":"The Lord of the Rings: The Return of the King","p":["Windows","PlayStation 2","GameCube","Xbox","Game Boy Advance"],"r":"November 3"},{"t":"The Lord of the Rings: War of the Ring","p":["Windows"],"d":"Liquid Entertainment","u":"Sierra Entertainment","g":"Real-time strategy","r":"November 4, 2003","l":"https://en.wikipedia.org/wiki/The_Lord_of_the_Rings:_War_of_the_Ring","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20pm.jpg","s":"The quest to destroy the One Ring continues in the first real-time strategy game based on The Lord of the Rings saga. Massive battles erupt as the forces of light and darkness fight for control of Middle-earth. The more units you destroy, the more experience and visual enhancements you earn. Play as the forces of good and valiantly fight for the ring's destruction or play as the forces of evil to claim control over Middle-earth forever."},{"t":"The Muppets: On With the Show!","p":["Windows","Game Boy Advance"],"d":"Activision Vicarious Visions","u":"TDK Mediactive","g":"Action","l":"https://en.wikipedia.org/wiki/The_Muppets:_On_With_the_Show!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d0w.jpg","s":"Help the Irresistible Muppets keep the show going, even when the rats steal the Swedish Chef's cooking ingredients, Bunsen and Beaker's experiment is out of control, and a giant Jurassic pig invades the stage!"},{"t":"The Omega Stone: Riddle of the Sphinx II","p":["Windows","macOS"],"d":"Omni World Studios","u":"DreamCatcher Interactive","g":"Adventure","r":"March 18, 2003","l":"https://en.wikipedia.org/wiki/The_Omega_Stone:_Riddle_of_the_Sphinx_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8ec4.jpg","s":"The Omega Stone is a Microsoft Windows puzzle adventure game developed by American studio Omni World Studios. It was the sequel to the game Riddle of the Sphinx: An Egyptian Adventure and was released by DreamCatcher Interactive on March 18, 2003."},{"t":"The Simpsons: Hit & Run","p":["PlayStation 2","Xbox","GameCube","Windows"],"r":"September 16"},{"t":"The Simpsons: Road Rage","p":["Game Boy Advance"],"r":"June 30"},{"t":"The Sims Bustin' Out","p":["Game Boy Advance"],"r":"December 2","l":"https://en.wikipedia.org/wiki/The_Sims_Bustin%27_Out"},{"t":"The Sims: Makin' Magic","p":["Windows"],"d":"Maxis","u":"Electronic Arts, Aspyr Media","g":"Social simulation","r":"October 29, 2003","l":"https://en.wikipedia.org/wiki/The_Sims:_Makin'_Magic"},{"t":"The Sims: Superstar","p":["Windows"],"r":"May 12"},{"t":"The Spirit Engine","p":["Windows"],"d":"Natomic Studios","g":"Role-playing","r":"November 7, 2003","l":"https://en.wikipedia.org/wiki/The_Spirit_Engine","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ql6.jpg","s":"The Spirit Engine is a 2D, sidescrolling adventure/RPG game with a simple story and a straightforward, innovative real-time combat system. Written as an experimental reaction to old 16bit console RPGs, it took a little under two years to complete and was released in November 2003 as freeware under Natomic."},{"t":"The Super Dimension Fortress Macross","p":["PlayStation 2"],"d":"Sega AM2","u":"Bandai","g":"Action, flight simulator, shooter","r":"October 23, 2003","l":"https://en.wikipedia.org/wiki/The_Super_Dimension_Fortress_Macross_(2003_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3gpn.jpg","s":"This action game, based on the Macross franchise, allows players to relive both the 1982 anime series and the Do You Remember Love? movie.\n\nThe game was produced by Bandai and created by the Sega AM2 team that programmed Aero Dancing. The game features a blend of arcade shooting and realistic aerial combat similar to the Ace Combat series."},{"t":"The Sydney Mystery","p":["Windows"],"d":"Twilight Software","u":"Twilight Software","g":"Adventure","r":"April 13, 2003","l":"https://en.wikipedia.org/wiki/The_Sydney_Mystery","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5fsz.jpg","s":"This mystery adventure game takes place in Sydney, Australia, where you play the role of the niece of a kidnapped retired Private Investigator. While you seek out clues to solve his disappearance, you take an interactive tour of Sydney including the Opera House and the Harbour. As the mystery unfolds, you will visit other places in the city of Sydney and even venture into parts of Australia's bushlands.\n\nThrough the use of full-motion video, the game features over 240 scenes, 11 characters, 17 authentic Australian locations, puzzles, inventory objects, music and interactive exploration and conversation."},{"t":"The Temple of Elemental Evil","p":["Windows"],"d":"Troika Games","u":"Atari","g":"Role-playing, turn-based tactics","r":"September 16, 2003","l":"https://en.wikipedia.org/wiki/The_Temple_of_Elemental_Evil_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co28cm.jpg","s":"The game begins with an opening vignette that is determined by the alignment of the party. All of these require the player to start in the town of Hommlet."},{"t":"The Westerner","p":["Windows"],"d":"Revistronic","u":"Planeta DeAgostini","g":"Graphic adventure","r":"December 21, 2003","l":"https://en.wikipedia.org/wiki/The_Westerner_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3ai2.jpg","s":"Take on the role of Fenimore Fillmore as you confront the evil John Starek, who has been threatening the local townspeople into selling him their land. In this wild adventure, you'll meet more than 30 different characters, collect useful inventory objects, and encounter an array of Wild West situations. Ride the rails, fight in barroom brawls, or choose to take it outside in a deadly gunfight. The choice is yours. If you help the townspeople fight to keep their land, you just might be able to ride off into the sunset with the girl of your dreams."},{"t":"There (virtual world)","p":["Windows","macOS"],"d":"Makena Technologies","g":"Virtual world","r":"January 9, 2003","l":"https://en.wikipedia.org/wiki/There_(virtual_world)"},{"t":"Tiger Woods PGA Tour 2004","p":["PlayStation 2","GameCube","Xbox","Windows","Game Boy Advance"],"u":"EA Sports","r":"September 22, 2003","l":"https://en.wikipedia.org/wiki/Tiger_Woods_PGA_Tour_2004"},{"t":"Time Crisis 3","p":["PlayStation 2"],"r":"October 21","l":"https://en.wikipedia.org/wiki/Time_Crisis_3"},{"t":"Tokyo Xtreme Racer 3","p":["PlayStation 2"],"d":"Genki","u":"Genki, Crave Entertainment","g":"Racing","r":"July 24, 2003","l":"https://en.wikipedia.org/wiki/Tokyo_Xtreme_Racer_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8xy0.jpg","s":"Tokyo Xtreme Racer 3 (or 首都高バトル 01 in the Japanese release) was released for the PlayStation 2 in 2003 as part of Genki's Shutokou Battle series. This entry in the series was released two years after the previous game, Tokyo Xtreme Racer: Zero.\n\nMuch like other entries in the series, the objective is to become the fastest racer on the highways of Japan, but unlike those before it, TXR3 allows the players to race in Nagoya and Osaka instead of just Tokyo, and the Tokyo map is expanded to include the Yokohama area. In addition, this title adds a weather cycle.\n\nTXR3 includes a fully-licensed list of cars from a variety of Japanese, American, and European manufacturers instead of the old car model designation method of \"Type-(technical model name)\", and furthermore, the car list itself was culled of many repeat models so to simplify and reduce the number of cars. The A, B, and C car designations were also removed.\n\nGraphically speaking, Tokyo Xtreme Racer 3 is a definite improvement over previous entries. Car models feature a higher polygon count and are much more extensively detailed and lighting effects were also greatly improved, featuring light streaking effects, road reflections and higher quality car reflections."},{"t":"Tokyo Xtreme Racer: Drift","p":["PlayStation 2"],"d":"Genki","u":"Genki, Crave Entertainment","g":"Racing","r":"February 27, 2003","l":"https://en.wikipedia.org/wiki/Tokyo_Xtreme_Racer:_Drift"},{"t":"Tom and Jerry in Infurnal Escape","p":["Game Boy Advance"],"r":"March 14","l":"https://en.wikipedia.org/wiki/Tom_and_Jerry_in_Infurnal_Escape"},{"t":"Tom Clancy's Rainbow Six 3","p":["Xbox"],"u":"Ubisoft","r":"October 28, 2003"},{"t":"Tom Clancy's Rainbow Six 3: Raven Shield","p":["Windows","Xbox"],"r":"March 19"},{"t":"Tom Clancy's Splinter Cell","p":["Windows","PlayStation 2","GameCube"],"u":"Ubisoft","g":"Action","r":"February 19, 2003","l":"https://en.wikipedia.org/wiki/Tom_Clancy%27s_Splinter_Cell_(video_game)","i":"images/steam-13560.jpg","s":"Enter the world of cinematic stealth action with Splinter Cell, the game that propelled the genre to cult status. You are Sam Fisher, an elite covert agent in the NSA's top-secret division: Third Echelon."},{"t":"Tomb Raider: The Angel of Darkness","p":["PlayStation 2","Windows"],"r":"June 20"},{"t":"Tonka: Rescue Patrol","p":["GameCube"],"r":"November 18"},{"t":"Tony Hawk's Pro Skater 4","p":["Windows"],"u":"Activision","r":"August 27, 2003","l":"https://en.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater_4"},{"t":"Tony Hawk's Underground","p":["PlayStation 2","GameCube","Xbox","Game Boy Advance"],"u":"Activision","r":"October 27, 2003","l":"https://en.wikipedia.org/wiki/Tony_Hawk%27s_Underground"},{"t":"Toontown Online","p":["Windows"],"r":"June 2","l":"https://en.wikipedia.org/wiki/Toontown_Online"},{"t":"Top Gear Rally","p":["Game Boy Advance"],"d":"Tantalus Interactive","u":"Kemco, Nintendo","g":"Racing","r":"July 25, 2003","l":"https://en.wikipedia.org/wiki/Top_Gear_Rally_(2003_video_game)"},{"t":"Top Spin","p":["Xbox"],"u":"Microsoft Game Studios","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Top_Spin_(video_game)"},{"t":"Torrente","p":["Windows"],"d":"Virtual Toys","u":"O~3 Entertainment","g":"third-person shooter","l":"https://en.wikipedia.org/wiki/Torrente_(video_game)"},{"t":"TrackMania","p":["Windows"],"d":"Nadeo","u":"Focus Home Interactive, Digital Jesters, Enlight","g":"Racing, puzzle","r":"November 21, 2003","l":"https://en.wikipedia.org/wiki/TrackMania_(2003_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4vfw.jpg","s":"TrackMania is a racing game and the first entry in the TrackMania series, combining driving with track construction. Players race across circuits filled with jumps, loops, and tight corners to earn in-game currency, which is spent on building blocks used to design their own tracks on a snapping grid. Three environments, Rally, Snow, and Desert, each provide a distinct car and handling style, and the game includes Race, Puzzle, and Survival modes. Players can create custom car skins and share their tracks and skins online, and the game supports hotseat, LAN, and internet multiplayer. A later re-release, TrackMania Original, added new block types and features."},{"t":"Traitors Gate 2: Cypher","p":["Windows"],"d":"258 Productions AB, Data Ductus AB","u":"The Adventure Company","g":"Graphic adventure game","r":"October 28, 2003","l":"https://en.wikipedia.org/wiki/Traitors_Gate_2:_Cypher"},{"t":"Tribal Wars","p":["Browser"],"d":"InnoGames","u":"InnoGames","g":"Real-time strategy, Massively multiplayer online game","l":"https://en.wikipedia.org/wiki/Tribal_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co44x8.jpg","s":"Compete in hardcore PvP strategy in persistent game worlds where real time resource and troop management in coordination with other players is required to expand your kingdom from one village to hundreds as you conquer the map in this winner takes all medieval contest."},{"t":"Trickster Online","p":["Windows"],"d":"Ntreev Soft","u":"Gamepot, Gamigo, ChineseGamer, Netmarble, ValofeThai and Smilegate","g":"Fantasy MMORPG","r":"April 10, 2003","l":"https://en.wikipedia.org/wiki/Trickster_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6avq.jpg","s":"A F2P (Free to Play) 2D, isometric MMORPG by Korean developer Ntreev Soft."},{"t":"Tropico 2: Pirate Cove","p":["Windows"],"d":"Frog City Software, Westlake Interactive","u":"Gathering, MacSoft","g":"City-building game","r":"April 8, 2003","l":"https://en.wikipedia.org/wiki/Tropico_2:_Pirate_Cove","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9c74.jpg","s":"As a feared Pirate King, you have to keep both your buccaneers and prisoners under control and send your ships on the prowl for treasury. Apart from an entirely new setting, the official sequel to the original Tropico offers gameplay improvements, new features and scenarios."},{"t":"True Crime: Streets of LA","p":["PlayStation 2","Xbox","GameCube"],"r":"November 3"},{"t":"Tsuki wa Higashi ni Hi wa Nishi ni","p":[],"l":"https://en.wikipedia.org/wiki/Tsuki_wa_Higashi_ni_Hi_wa_Nishi_ni"},{"t":"Tube Slider","p":["GameCube"],"d":"NDcube","u":"NEC Interchannel","g":"Racing","r":"April 15, 2003","l":"https://en.wikipedia.org/wiki/Tube_Slider","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6uff.jpg","s":"Race around fast and futuristic race tracks in some of the most high tech cars ever created. Each hover craft has the ability to get to very high speeds at a simple touch of a button, while side boosters allow you to take sharp turns at full tilt and turbo (if you really want to go even faster) gives you an added boost for a short amount of time.\n\nThe 10 tracks on offer can be completed either in Grand Prix, Time Trial or Free Ride modes. Grand Prix has you competing one race after the other for the grand prize. The higher you finish, the better the chance to progress and win the title."},{"t":"UFC: Tapout 2","p":["Xbox"],"d":"DreamFactory","u":"TDK Mediactive","g":"Versus fighting, Sports","r":"March 20, 2003","l":"https://en.wikipedia.org/wiki/UFC:_Tapout_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3g9c.jpg","s":"UFC: Tapout 2 is the second game released on the Xbox based on the popular mixed martial arts organization."},{"t":"UFO: Aftermath","p":["Windows"],"d":"ALTAR Interactive","u":"Cenega Publishing, Tri Synergy","g":"Real-time tactics, Turn-based strategy","r":"October 3, 2003","l":"https://en.wikipedia.org/wiki/UFO:_Aftermath","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2cqd.jpg","s":"UFO: Aftermath is the first in a three-game squad-based tactical strategy-RPG series clearly inspired by the original X-COM games, with similar themes and gameplay, but with its own post-apocalyptic horror spin on the concept. The game is rendered in isometric 3D."},{"t":"UFO: Alien Invasion","p":["Linux","Windows","Amiga","macOS"],"d":"UFO: Alien Invasion Team","g":"Real-time strategy, turn-based tactics","l":"https://en.wikipedia.org/wiki/UFO:_Alien_Invasion"},{"t":"Ultimate Beach Soccer","p":["Game Boy Advance","PlayStation 2","Xbox","Windows"],"d":"PAM Development, Magic Pockets","u":"DreamCatcher Interactive, Wanadoo","g":"Sports","r":"May 30, 2003","l":"https://en.wikipedia.org/wiki/Ultimate_Beach_Soccer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/nrz2wjdib9giiyj6fpis.jpg","s":"Billed as the first Beach Soccer video game designed especially for fans of soccer and extreme sports, Ultimate Beach Soccer offers five-on-five action with lots of aerial passes, special moves, combos, intense shooting and scoring, spectacular goals and saves. Set in unique and exotic locations spanning the globe, including Rio, France, Japan and Venice Beach, California, Ultimate Beach Soccer offers detailed and exotic stadiums, with daytime and nighttime games, including spectacular pitch-side shows with DJs, cheerleaders and commentators all fully modeled and animated in-game. Game modes range from quick match to long-term competitions and custom tournaments. The game sports the Official Beach Soccer Federation License - Real Players, Real Teams and Real Locations."},{"t":"Ultimate Brain Games","p":["Game Boy Advance","PlayStation"],"d":"Cosmigo","u":"Telegames","g":"Puzzle","r":"March 18, 2003","l":"https://en.wikipedia.org/wiki/Ultimate_Brain_Games","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/mhvmp6o67pcquddtvqm6.jpg","s":"Part of the Telegames Ultimate series of handheld pick-up games. Ultimate Brain Games includes a collection of favorite strategy challenges. Playable games include Chess, Checkers, Backgammon, Mahjong, Dominoes, 4-in-a-Row, Sink the Ships, and Reversi. Features include 2D and 3D graphics, 2-player link play, and downloadable multiplayer."},{"t":"Ultimate Demolition Derby","p":["Windows"],"u":"Global Star Software","r":"September 16, 2003"},{"t":"Ultimate Winter Games","p":["Game Boy Advance"],"d":"Sproing Interactive","u":"Telegames","g":"Sports","r":"December 5, 2003","l":"https://en.wikipedia.org/wiki/Ultimate_Winter_Games","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9vxs.jpg","s":"Ultimate Winter Games features four different Olympic-style events to play: Downhill Skiing, Snowboarding, Bobsled, and Curling. Three of the sports renditions, skiing, snowboarding, and bobsled, utilize an ambitious 3D engine for a realistic you-are-there feel. In Skiing, players rush down the different slopes in order to beat the best time, while Snowboarding requires players to pull off tricks to score points. Bobsled puts players in the ice-riding vehicle, where they must keep the sled on the optimal groove of the course to get the fastest time and Curling is like ice bowling or shuffleboard. Features 10 courses for each event and link-up play for two."},{"t":"Unlimited Saga","p":["PlayStation 2"],"r":"June 17","l":"https://en.wikipedia.org/wiki/Unlimited_Saga"},{"t":"Unreal II: The Awakening","p":["Windows"],"r":"February 3"},{"t":"Urban Freestyle Soccer","p":["Mobile phone"],"d":"Gusto Games","u":"Acclaim Entertainment","g":"Sports","r":"August 17, 2003","l":"https://en.wikipedia.org/wiki/Urban_Freestyle_Soccer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ufi.jpg","s":"Freestyle Street Soccer known as Urban Freestyle Soccer in Europe is, as the name implies, a Freestyle soccer-game in an urban setting. The game focuses on action and fun instead of realism. You play four on four in five game modes: Turf War, Home Turf, Street Challenge Cup, Exhibition and Multiplayer. The first requires you to conquer neighborhoods in the city by winning soccer matches against rival gangs. Street Challenge Cup allows you to play an entire competition.\n\nEach player can perform a large variety of moves beyond the typical soccer game moves, such as scissor kicks, midair juggles, and bicycle kicks. Performing said moves allows you to gain skill points that can be used to unlock new game modes, teams, courts, and cheats. Next to these special moves, you can also interact with the environment. Your players can pick things up and throw them around or manually hit your opponents."},{"t":"Uru: Ages Beyond Myst","p":["Windows"],"r":"November 11"},{"t":"Vegas Tycoon","p":["Windows"],"d":"Deep Red Games","u":"Global Star","g":"Business simulation game Strategy","r":"October 14, 2003","l":"https://en.wikipedia.org/wiki/Vegas_Tycoon"},{"t":"Venetian Blinds","p":["Atari 2600","Windows","macOS","Game Boy Advance"],"d":"David Crane, Bob Whitehead","u":"Activision","g":"Simulation","l":"https://en.wikipedia.org/wiki/Venetian_Blinds_(video_game)"},{"t":"Venus & Braves","p":["PlayStation 2"],"d":"Namco","u":"Namco","g":"Tactical role-playing game","r":"February 13, 2003","l":"https://en.wikipedia.org/wiki/Venus_&_Braves"},{"t":"Vexx","p":["GameCube","PlayStation 2","Xbox"],"d":"Acclaim Studios Austin","u":"Acclaim Entertainment","g":"Platform, action-adventure","r":"February 11, 2003","l":"https://en.wikipedia.org/wiki/Vexx","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co99dv.jpg","s":"Step into the role of Vexx as he seeks vengeance on those who murdered his grandfather and enslaved his people. Equipped with a set of razor-sharp war talons, you'll travel through volcanic islands, desert temples, frozen citadels, and giants' castles to confront the evil Dark Yabu, Shadowraith, and their minions. As darkness falls, enemies become more aggressive and the environments become more hostile. It will take all your combat skills and climbing moves to bring peace back to the villagers of Rockhaven."},{"t":"Victoria: An Empire Under the Sun","p":["Windows"],"r":"November 18"},{"t":"Vietcong","p":["Windows"],"d":"Pterodon, Illusion Softworks, Coyote Developments","u":"Gathering","g":"Tactical first-person shooter","r":"March 26, 2003","l":"https://en.wikipedia.org/wiki/Vietcong_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7nmi.jpg","s":"Vietcong is an tactical FPS known for its realism focused gameplay and at the time, original Vietnam war setting. The game featured many early examples of later genre conventions such as iron sights and a cover system.\n\nIn addition to the main story-driven campaign, the game also features a number of quick skirmish style missions for single player, as well as a fairly robust set of both cooperative and competitive multiplayer modes, including a downloadable set of coop missions entitled \"Red Dawn\" played from the perspective of Vietcong soldiers."},{"t":"Viewtiful Joe","p":["GameCube"],"u":"Capcom","r":"June 26, 2003","l":"https://en.wikipedia.org/wiki/Viewtiful_Joe_(video_game)"},{"t":"Virtua Cop 3","p":["Arcade"],"d":"Sega AM2","u":"Sega","g":"Light gun shooter, rail shooter","r":"March 2003","l":"https://en.wikipedia.org/wiki/Virtua_Cop_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4oq4.jpg","s":"Virtua Cop 3 is the third installment in the series. It also features a bullet time mechanism which players to slow down time by stepping on a pedal."},{"t":"Virtua Fighter 4: Evolution","p":["PlayStation 2"],"u":"Sega","r":"March 13, 2003"},{"t":"Voodoo Vince","p":["Xbox"],"d":"Beep Industries","u":"Microsoft Game Studios, Beep Games","g":"Platform","r":"September 23, 2003","l":"https://en.wikipedia.org/wiki/Voodoo_Vince","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wjd.jpg","s":"No Pain, No Gain!\n\nVince was just a voodoo doll in a French Quarter shop, but when his maker was kidnapped, he became a vengeful doll on a mission! Using voodoo powers, Vince must kick his own butt to beat his enemies! If he stand under a falling safe, bad guys get flattened! Stick a pitch fork in him, and his enemies are done!"},{"t":"Waco Resurrection","p":["Windows"],"g":"Shooter, Simulator","l":"https://en.wikipedia.org/wiki/Waco_Resurrection","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8iee.jpg","s":"Revisiting the 1993 Waco, Texas incident, gamers enter the mind and form of a resurrected David Koresh and advance towards salvation or destruction by wielding weapons, collecting followers and voicing messianic messages."},{"t":"Wakeboarding Unleashed Featuring Shaun Murray","p":["Game Boy Advance","macOS","Windows","PlayStation 2","Xbox"],"d":"Shaba Games","u":"Activision","g":"Sports","r":"June 10, 2003","l":"https://en.wikipedia.org/wiki/Wakeboarding_Unleashed_Featuring_Shaun_Murray","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1onw.jpg","s":"Wakeboarding is part of Activision's line of Extreme Sports titles. A rider (using a board that's like a combination of a surf board, body board and skateboard) is pulled along the water by rope at high speeds by the boat up front, and must pull of tricks either by jumping of jumps or using the wake left by the boat itself (hence the sport's name).\n\nUnleashed takes this sport and turns it upside down, allowing you to fly down water ways through well known locations around the world, pulling stunts off buildings or cliff faces. Other objectives are included that have you completing tasks and busting tricks in a unique way.\n\nMultiplayer modes include one-on-one trick attack and horse, where both players compete against each other to pull off the best tricks. Co-operative mode has one player driving the boat while the other hangs on behind, with new challenges for the boat driver to complete as well as the rider."},{"t":"Waku Waku Volley","p":["PlayStation","PlayStation 2"],"d":"Athena","u":"Success, Agetec","g":"Sports","r":"January 30, 2003","l":"https://en.wikipedia.org/wiki/Waku_Waku_Volley"},{"t":"Wallace & Gromit in Project Zoo","p":["GameCube","PlayStation 2","Xbox","Windows"],"d":"Frontier Developments","u":"BAM! Entertainment","g":"Platform","r":"October 3, 2003","l":"https://en.wikipedia.org/wiki/Wallace_&_Gromit_in_Project_Zoo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dzl.jpg","s":"Wallace & Gromit in Project Zoo is a platform video game developed by Frontier Developments and published by BAM! Entertainment (European distribution being handled by Acclaim Entertainment) for the PlayStation 2, GameCube, Xbox and Microsoft Windows. It is the first console game to feature Aardman Animations' characters Wallace & Gromit and also features the voice of Wallace, Peter Sallis reprising his role."},{"t":"War Chess","p":["Windows","PlayStation 2"],"d":"SuperEmpire Interactive Inc.","u":"XS Games, Big Fish Games, Piko Interactive","g":"Strategy, Tactics, Fantasy Chess","l":"https://en.wikipedia.org/wiki/War_Chess","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coahou.jpg","s":"War Chess is a basically a chess game with a unusual presentation. All the set pieces for the game are substituted for the character of the High Fantasy setting. Whites are pictured as joined armies of humans and elves, while blacks are mostly represented by the undead forces. The player has an ability to choose from 11 various location for the match to take place. Those include: Forest, Desert, Ice and Lava, Dragon Cave etc. All the environments and pieces are rendered in full 3D with a fully rotatable camera.\n\nFor the single playing experience the game provides a difficulty slider to account for gamer's proficiency skill. Additionally War Chess offers a multiplayer mode for two players to battle each other as at one PC so as over the network.\n\nThe game obviously takes it inspiration from the Battlechess series, however doesn't provide unique animations for each type of encounter on the chessboard. Each piece has a double set of animations: one for attacking, another for dying. Those do not differ depending on the type of the opposing piece."},{"t":"War of the Monsters","p":["PlayStation 2"],"d":"Incog Inc. Entertainment","u":"Sony Computer Entertainment","g":"Action, fighting","r":"January 14, 2003","l":"https://en.wikipedia.org/wiki/War_of_the_Monsters","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2mtz.jpg","s":"Get ready to embody the soul of a 100-foot tall monstrosity as you clash with opponents in thriving cities, run rampant through bustling streets, pulverize opponents with body slams and fight off military defenses. War of the Monsters enables you to re-live your favorite monster movies with ten different creatures engaging in all out carnage. Ten fully interactive environments offer numerous weapons, including steel girders, radio antenna, moving vehicles, building rubble, army tanks and more. Clobber opponents with thunderous uppercuts, hand-to-hand weapons and destructive special attacks. Use huge hunks of debris as a shield, topple buildings onto your foes or pick up and throw tanker trucks like toys. Take advantage of environmental attacks such as tidal waves and earthquakes to defeat your opponent and claim total domination."},{"t":"Warblade","p":["Windows","macOS"],"g":"Shooter","l":"https://en.wikipedia.org/wiki/Warblade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocmfl.jpg","s":"Warblade is a shareware computer game for Microsoft Windows and OS X, written by Norwegian developer Edgar M. Vigdal. The Windows version runs well on Linux under Wine. It is also available for retail in the App Store for iOS devices (in iPhone/iPod Touch and iPad versions). The game is a 2D space shooter in the vein of the perennial classic Galaga. It is a rewrite and modernization of a popular Amiga shareware game, Deluxe Galaga, which was written by the same author back in the mid-1990s. Where technically possible, the graphics and sounds are respectful to their Amiga origins."},{"t":"Warcraft III: The Frozen Throne","p":["Windows"],"u":"Blizzard Entertainment","r":"July 1, 2003"},{"t":"Warfare Incorporated","p":["Mobile phone","Windows Mobile","Browser"],"d":"Spiffcode","g":"Real-time strategy","r":"September 12, 2003","l":"https://en.wikipedia.org/wiki/Warfare_Incorporated","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ukl.jpg","s":"Warfare Incorporated is a real-time strategy game, released in 2003. It was developed by American studio Spiffcode and published by Handmark. In 2014 the game became open-sourced and freeware under the name Hostile Takeover."},{"t":"Warhammer 40,000: Fire Warrior","p":["PlayStation 2","Windows"],"d":"Kuju Entertainment","u":"THQ, Chilled Mouse, SNEG","g":"First-person shooter","r":"September 24, 2003","l":"https://en.wikipedia.org/wiki/Warhammer_40,000:_Fire_Warrior","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3a6a.jpg","s":"The game focuses on the Tau Fire Warrior Shas'la T'au Kais, a newly-trained member of the Fire Caste seeking to rescue his Ethereal and defend his race from the aggressive assaults of the Imperium of Man and the Forces of Chaos on the Desert World of Dolumar IV."},{"t":"Wario World","p":["GameCube"],"r":"June 24","l":"https://en.wikipedia.org/wiki/Wario_World"},{"t":"WarioWare Inc.: Mega Microgame$","p":["Game Boy Advance"],"r":"May 21"},{"t":"WarioWare, Inc.: Mega Microgames!","p":["Game Boy Advance"],"u":"Nintendo","r":"March 21, 2003"},{"t":"WarioWare, Inc.: Mega Party Games!","p":["GameCube"],"d":"Nintendo R&D1, Intelligent Systems","u":"Nintendo","g":"Party game","r":"October 17, 2003","l":"https://en.wikipedia.org/wiki/WarioWare,_Inc.:_Mega_Party_Games!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4b10.jpg","s":"Following the almost universally acclaimed short-attention-span action of the Game Boy Advance's WarioWare, Inc.: Mega Microgame$! comes this party-game adaptation for GameCube. Many of the mini-games featured in the handheld original have been converted for four-player competition on the console. Gamers strive to be the quickest teeth-brushers, the most precise nose pickers, the best free-throwers, the most accurate apple shooters, the most skillful paper-airplane pilots, and the victors in countless other quick contests that take no more than a few seconds to complete.\n\nAs in the GBA original, a wide variety of activities combine with a simple, unifying theme, for an experience designed to appeal instantly to anyone who played video games in the days before 3D graphics and complicated storylines. Half the fun is in not knowing which five-second challenge will pop up next, or what the player will be required to do in it. Even when players aren't in control of the active character, some of the mini-games allow them to participate in a more passive fashion, adding to the group-oriented strategy."},{"t":"Warlords IV: Heroes of Etheria","p":["Windows"],"d":"Infinite Interactive","u":"Ubi Soft","g":"Turn-based strategy","r":"October 21, 2003","l":"https://en.wikipedia.org/wiki/Warlords_IV:_Heroes_of_Etheria","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ks4.jpg","s":"Warlords IV: Heroes of Etheria is a strategy game for the PC in the Warlords series."},{"t":"Warning Forever","p":["Windows"],"u":"Hikware","g":"Fixed shooter","r":"July 24, 2003","l":"https://en.wikipedia.org/wiki/Warning_Forever","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co67in.jpg","s":"Warning Forever is a top-down shooter that pits you against a never-ending onslaught of procedurally-generated bosses which evolve to counter your strategies."},{"t":"Warrior Kings: Battles","p":["Windows"],"d":"Black Cactus","u":"Empire Interactive, Strategy First","g":"Real-time strategy","r":"March 21, 2003","l":"https://en.wikipedia.org/wiki/Warrior_Kings:_Battles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co907t.jpg","s":"Warrior Kings: Battles maintains the excitement that made Warrior Kings a leading RTS. It is a stand-alone title that adds a new strategic and tactical dimension to the series."},{"t":"Whiplash","p":["PlayStation 2","Xbox"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Whiplash_(video_game)"},{"t":"Wildlife Park","p":["Windows"],"d":"B-Alive GmbH","u":"Deep Silver, JoWood Productions, Encore Software Inc.","g":"Construction and management sim","r":"September 26, 2003","l":"https://en.wikipedia.org/wiki/Wildlife_Park","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6l1w.jpg","s":"Here is your chance to create a giant and beautiful zoo. A park so amazing, it would be impossible to build in real life. In Wildlife Park you must build an animal park from scratch, managing it so your visitors will spend their money. You begin with just the park area, a ticket booth, and some money. From there you can buy animals, build the zoo, hire employees, and then open the gates and let the visitors come."},{"t":"Will Rock","p":["Windows"],"d":"Saber Interactive","u":"Ubi Soft","g":"First-person shooter","r":"June 10, 2003","l":"https://en.wikipedia.org/wiki/Will_Rock","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2z0x.jpg","s":"Will Rock must save his girlfriend from Zeus and his cronies in this fast-paced first-person shooter by Saber Interactive."},{"t":"With Your Destiny","p":["Windows"],"d":"JoyImpact Co., Ltd.","u":"JoyImpact Co., Ltd., Raid Hut Ltd., Vibrant Communications Ltd., HanbitSoft Inc.","g":"Fantasy MMORPG","r":"May 2003","l":"https://en.wikipedia.org/wiki/With_Your_Destiny","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3w18.jpg","s":"With Your Destiny is an MMORPG released in 2003 by JoyImpact. It takes place in a fantasy setting with ongoing wars and mythological elements. The game includes four base classes (Transknight, Hunter, Foema, Beastmaster), a long leveling system, and several PvP modes like large-scale guild battles."},{"t":"Wolfenstein: Enemy Territory","p":["Linux","Windows"],"d":"Splash Damage","u":"Activision","g":"First-person shooter","r":"May 29, 2003","l":"https://en.wikipedia.org/wiki/Wolfenstein:_Enemy_Territory","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc44n.jpg","s":"Wolfenstein: Enemy Territory is a multiplayer spin-off to Return to Castle Wolfenstein. In this game, two teams battle each other through a series of three missions that make up a single campaign. There are two campaigns: North Africa and Northern Europe. Within a mission there are objectives that must be completed by each team. These are as varied as escorting tanks, building bridges, stealing gold, or blowing up fuel dumps. Each player picks a character class, such as engineer, soldier, field ops, or covert ops, and then makes use of that class's special abilities, class-specific weapons, and inventory items."},{"t":"World Championship Pool 2004","p":["PlayStation 2","Xbox","Windows","GameCube"],"d":"Blade Interactive","u":"Jaleco","g":"Sports simulation","r":"December 8, 2003","l":"https://en.wikipedia.org/wiki/World_Championship_Pool_2004","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9edf.jpg"},{"t":"World Championship Snooker 2003","p":["PlayStation 2","Xbox","Windows"],"d":"Blade Interactive","u":"Codemasters","g":"Sports","r":"June 20, 2003","l":"https://en.wikipedia.org/wiki/World_Championship_Snooker_2003_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/qqceszqa9zmhc5vzmuwt.jpg","s":"The chart-busting success of World Championship Snooker returns for a new year and a new snooker challenge. Veteran snooker fans and championship newcomers step up to the table in opposition to Stephen Hendry, Peter Ebdon, Mark Williams, Ronnie O’Sullivan and more than twenty top players from the world of professional snooker. With incredible enhancements in every area of the game, plus new game modes and a more compelling snooker experience than ever before, World Championship Snooker 2003 is set to make the big breaks frame after frame."},{"t":"World Empire","p":["MS-DOS","Windows"],"d":"Viable Software Alternatives","u":"Viable Software Alternatives","g":"Turn-based strategy","l":"https://en.wikipedia.org/wiki/World_Empire"},{"t":"World Racing","p":["Windows","PlayStation 2","Xbox"],"d":"Synetic","u":"TDK Mediactive Europe","g":"Racing","r":"February 28, 2003","l":"https://en.wikipedia.org/wiki/World_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9bsg.jpg","s":"Mercedes-Benz World Racing (also referred to as World Racing) - is a computer game in the genre of driving simulators, developed by the German company Synetic GmbH. The game was released in September 2003."},{"t":"World Series Baseball 2K3","p":["Xbox","PlayStation 2"],"u":"Sega","r":"March 10, 2003","l":"https://en.wikipedia.org/wiki/World_Series_Baseball_2K3"},{"t":"World War II: Frontline Command","p":["Windows"],"d":"Bitmap Brothers","u":"Koch Media, Strategy First","g":"Strategy","r":"May 2, 2003","l":"https://en.wikipedia.org/wiki/World_War_II:_Frontline_Command","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9c86.jpg","s":"World War II: Frontline Command begins by dropping you into Europe to disrupt the entrenched Axis forces before D-Day. From that point on, it's up to you to take command of your forces to turn the tide of Axis aggression by conquering important areas using authentic infantry, vehicles, and weaponry. You can play 25 single-player missions or challenge up to four of your friends through a local area network or over the Internet. Develop your own combat strategies, but remember to keep your soldiers' morale high so that they are more willing to perform heroic actions."},{"t":"Worms 3D","p":["GameCube","Windows","PlayStation 2","Xbox"],"d":"Team17","u":"Sega, Acclaim Entertainment, Feral Interactive","g":"Artillery, strategy","r":"October 31, 2003","l":"https://en.wikipedia.org/wiki/Worms_3D","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xjk.jpg","s":"Join the party as worm battles ensue across 3D worlds. Worms 3D pits four players--each with a customizable team of worms--against one another in fully deformable landscapes. All the bizarre weapons from the Worms series--including Banana Bomb, flying Super Sheep, Earthquakes, Air Strikes, and Holy Hand Grenade--appear for your destructive pleasure. Wreak havoc in turn-based multiplayer action or unlock landscapes, sound sets, challenges, and secret missions in the immersive single-player mode."},{"t":"WRC 3","p":["PlayStation 2"],"d":"Evolution Studios","u":"Sony Computer Entertainment","g":"Racing","r":"November 21, 2003","l":"https://en.wikipedia.org/wiki/WRC_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9eo4.jpg","s":"Third installment in the rally racing series by Evolution Studios. Fully licensed by the FIA World Rally association, the game features authentic drivers like Richard Burns, Carlos Saints, and Markko Martin,, as well as licensed cars from Peugeot, Ford, Citroen, and others. Overall, more than 35 licensed cars -- including rally concept and extreme cars -- are available for selection. Rally enthusiasts will appreciate the detailed car history essays, driver performance stats based on all known TV broadcasts, team videos, and a new 3D explorer feature that lets you inspect the vehicles from every angle and \"explode\" them to see their innards."},{"t":"WWE Crush Hour","p":["GameCube","PlayStation 2"],"r":"March 17","l":"https://en.wikipedia.org/wiki/WWE_Crush_Hour"},{"t":"WWE Raw 2","p":["Xbox"],"d":"Anchor Inc.","u":"THQ","g":"Sports","r":"September 15, 2003","l":"https://en.wikipedia.org/wiki/WWE_Raw_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co95fl.jpg","s":"WWE Raw 2: Ruthless Aggression, known as simply WWE Raw 2, is the sequel to WWF Raw. It features enhanced graphics and gameplay, a story mode, and more than 60 WWE superstars. WWE Raw 2 showcases its new features in eight arenas that come to life with 3D crowds and special effects. The enhanced gameplay controls provide better grappling, more balanced momentum shifts, and a realistic AI. Now you can play in different modes including multiplayer season mode, Exhibition, Season, King of The Ring, Royal Rumble, expanded Title Match, and Create-A-Superstar. The game also includes Hell in a Cell and TLC match types."},{"t":"WWE SmackDown! Here Comes the Pain","p":["PlayStation 2"],"r":"October 27","l":"https://en.wikipedia.org/wiki/WWE_SmackDown!_Here_Comes_the_Pain"},{"t":"WWE WrestleMania XIX","p":["GameCube"],"r":"September 8","l":"https://en.wikipedia.org/wiki/WWE_WrestleMania_XIX_(video_game)"},{"t":"X2: The Threat","p":["Windows","Linux"],"d":"Egosoft, Virtual Programming","u":"Deep Silver, Enlight, Virtual Programming, Linux Game Publishing","g":"Space simulation","r":"December 1, 2003","l":"https://en.wikipedia.org/wiki/X2:_The_Threat","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1v8u.jpg","s":"X2: The Threat is of a new generation of space simulator games where you play the role of Julian Gardna who continues the story set by X: Beyond The Frontier. The updated graphics engine gives the universe a fresher feel with newly designed ships and stations adding to the complexity of the universe."},{"t":"X2: Wolverine's Revenge","p":["PlayStation 2","GameCube","Xbox","Windows","Game Boy Advance","macOS"],"d":"GenePool Software, Warthog Games, Vicarious Visions, LTI Gray Matter","u":"Activision, Aspyr","g":"Action, Beat'em up","r":"April 15, 2003","l":"https://en.wikipedia.org/wiki/X2:_Wolverine's_Revenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2n0v.jpg","s":"X2: Wolverine's Revenge is an action beat 'em up video game based on the Marvel Comics character Wolverine, a member of the mutant team X-Men.\n\nThe action is played from a third-person perspective as players fight a number of armored soldiers, mutant creatures, and archenemies such as Sabretooth, Magneto, Wendigo, Lady Deathstrike, and Juggernaut. While Professor X is able to assist Wolverine with powers of telepathy, the surly comic book hero must ultimately carry out his adventure alone. To that end, players must tap into Wolverine's unique talents to overcome all manner of obstacles. Wolverine will be able to hunt and track his prey using his heightened sense of smell and ability to detect body heat. As Wolverine makes his way through the military compounds, he will need to avoid defense systems and guards, and find ways into locked rooms to discover the information he needs to survive."},{"t":"Xbox Music Mixer","p":["Xbox"],"d":"WildTangent","u":"Microsoft Game Studios","g":"Family, Music, Utility","r":"October 27, 2003","l":"https://en.wikipedia.org/wiki/Xbox_Music_Mixer"},{"t":"Xenosaga Episode I: Der Wille zur Macht","p":["PlayStation 2"],"r":"February 26"},{"t":"XGRA: Extreme-G Racing Association","p":["PlayStation 2","Xbox","GameCube"],"d":"Acclaim Studios Cheltenham","u":"Acclaim Entertainment","g":"Racing","r":"September 10, 2003","l":"https://en.wikipedia.org/wiki/XGRA:_Extreme-G_Racing_Association","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rx3.jpg","s":"XGRA: Extreme-G Racing Association is a futuristic racing video game, and the fourth in the Extreme-G series, following Extreme-G 3. This game features more tracks as well as a brand new weapon system.\nGameplay is similar but slightly different to previous games in the series. XGRA features a wide range of riders, tracks and bikes that can accelerate at an incredibly rapid rate, going from 0 to 300 mph in a matter of seconds. A returning feature is the ability to break sound barrier: upon reaching 750MPH, all sound effects will cut out, except for item collection sound, other tider's taunts, weapons firing, and in-game music.\n\nXGRA allows players to race for 8 different teams, with each team's bike having their own advantages and drawbacks such as Regeneration, Handling, Speed, Acceleration and Shielding."},{"t":"XIII","p":["Windows","GameCube","PlayStation 2","Xbox"],"r":"November 18","l":"https://en.wikipedia.org/wiki/XIII_(video_game)"},{"t":"XS Junior League Football","p":["PlayStation"],"d":"Wahoo Studios","u":"XS Games, SCEA","g":"Sports","l":"https://en.wikipedia.org/wiki/XS_Junior_League_Football","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/tuj3fhmd0ftp31nfxpef.jpg","s":"American football is a sport played between two teams of eleven with the objective of scoring points by advancing the ball into the opposing team's end zone. Known in the United States simply as football, it may also be referred to informally as gridiron football, and even more rare, the \"pigskin\". The ball can be advanced by running with it or throwing it to a teammate. Points can be scored by carrying the ball over the opponent's goal line, catching a pass thrown over that goal line, kicking the ball through the opponent's goal posts or tackling an opposing ball carrier in his own end zone. \n \nXS Jr. League Football is designed to provide a fun, pick-up-and-play adaptation of the popular sport, with colorful graphics and accessible gameplay for the whole family to enjoy."},{"t":"Yager","p":["Xbox","Windows"],"d":"Yager Development","u":"THQ, Kemco, DreamCatcher Interactive","g":"Air combat simulation","r":"May 23, 2003","l":"https://en.wikipedia.org/wiki/Yager","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rx5.jpg","s":"Step into the shoes of Magnus Tide, a young fighter pilot who must defend his home and way of life from enemies. Your fighter ship--the Sagittarius--can fire a variety of weapons and switch between hover and jet modes. The ship's maneuvering capabilities allow you to dive into canyons, soar over mountains, and explore different landscapes. Equally advanced are the enemy ships, which range from agile fighters to larger battleships and carriers."},{"t":"You Don't Know Jack Vol. 6: The Lost Gold","p":["Windows"],"g":"Quiz/Trivia","l":"https://en.wikipedia.org/wiki/You_Don't_Know_Jack_Vol._6:_The_Lost_Gold","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3l65.jpg","s":"Don’t overlook this lost gem! It’s a tasty morsel of trivia that we found under the couch back in the early 2000s, and now we’re pulling it right back out from under that same, dust-mite filled couch!"},{"t":"Ys VI: The Ark of Napishtim","p":["Windows"],"d":"Nihon Falcom","u":"Nihon Falcom, Konami, Taito, Xseed Games","g":"Action role-playing","r":"September 27, 2003","l":"https://en.wikipedia.org/wiki/Ys_VI:_The_Ark_of_Napishtim","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co260i.jpg","s":"Ys VI: The Ark of Napishtim is an action role-playing game in which adventurer Adol Christin is shipwrecked on the Canaan Islands after the Romun fleet attacks his expedition. Rescued by members of the native Rehda tribe, he explores the archipelago and investigates the forces threatening its inhabitants.\n\nCombat takes place in real time and centers on three elemental swords, each providing distinct attacks and magical abilities. Players explore interconnected areas, collect equipment and items, and battle regular enemies and large bosses."},{"t":"Yu Yu Hakusho: Spirit Detective","p":["Game Boy Advance"],"u":"Atari","r":"December 9, 2003"},{"t":"Yu-Gi-Oh! Dungeon Dice Monsters","p":["Game Boy Advance"],"r":"February 12","l":"https://en.wikipedia.org/wiki/Yu-Gi-Oh!_Dungeon_Dice_Monsters"},{"t":"Yu-Gi-Oh! The Duelists of the Roses","p":["PlayStation 2"],"r":"February 16","l":"https://en.wikipedia.org/wiki/Yu-Gi-Oh!_The_Duelists_of_the_Roses"},{"t":"Yu-Gi-Oh! The Falsebound Kingdom","p":["GameCube"],"r":"November 4","l":"https://en.wikipedia.org/wiki/Yu-Gi-Oh!_The_Falsebound_Kingdom"},{"t":"Yu-Gi-Oh! Worldwide Edition: Stairway to the Destined Duel","p":["Game Boy Advance"],"d":"Konami","u":"Konami","g":"Digital collectible card game","r":"April 15, 2003","l":"https://en.wikipedia.org/wiki/Yu-Gi-Oh!_Worldwide_Edition:_Stairway_to_the_Destined_Duel"},{"t":"Yumeria","p":["PlayStation 2"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Yumeria","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2zst.jpg","s":"A visual novel for the PlayStation 2. It went on to spawn an anime series."},{"t":"Zoids: Battle Legends","p":[],"l":"https://en.wikipedia.org/wiki/Zoids:_Battle_Legends"},{"t":"Zone of the Enders: The 2nd Runner","p":["PlayStation 2"],"d":"Konami Computer Entertainment Japan","u":"Konami","g":"Action, hack and slash","r":"February 13, 2003","l":"https://en.wikipedia.org/wiki/Zone_of_the_Enders:_The_2nd_Runner","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gzx.jpg","s":"The sequel to Zone of the Enders is based around mecha combat with the player once again controlling the \"Orbital Frame\" Jehuty. Unlike its prequel, the game is now centered on action elements with the player not needing to protect civilians in need and instead Jehuty contains more weaponry than in the previous game.\n\nThe plot is set two years after the events from Zone of the Enders and focuses on Dingo Egret, a former member from Mars' military organization BAHRAM whose leader Ridley \"Nohman\" Hardiman wants back with him. Nohman shoots Dingo following his rejection but the agent Ken Marinaris saves Dingo by connecting his body to Jehuty and forces to work in order to defeat BAHRAM. The game had a new director, Shuyo Murata, who producer Hideo Kojima appointed in order to provide a different experience. The team worked to cover the criticism the original Zone of the Enders received resulted in The 2nd Runner having more action elements.\n\nThe game received generally favorable critical response due to the improvements it has in comparison to the previous game. Critics praised the game's graphics and gameplay elements but criticized its short length and presentation. Despite the positive critical reaction, the game suffered mediocre sales.\n\nNorth American & Japan got regular ZOE2, but the regular edition of ZOE2 was never released in Europe. Europe directly got the ZOE2 Special Edition."},{"t":"Zone of the Enders: The Second Runner","p":["PlayStation 2"],"r":"March 10"},{"t":"Zoo Keeper","p":["Browser","Arcade","Game Boy Advance"],"d":"Robot Communications, Success","u":"Robot Communications, Success, Ignition Entertainment, 505 Game Street","g":"Puzzle","r":"October 31, 2003","l":"https://en.wikipedia.org/wiki/Zoo_Keeper_(2003_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobwvv.jpg","s":"A Japanese flash game where you must match the animals to reach at a certain number."},{"t":"Zuma","p":["macOS","Mobile phone","Windows","Windows Mobile","Xbox","PlayStation 2","PlayStation Portable"],"d":"PopCap Games","u":"PopCap Games, Glu Mobile, Oberon Media","g":"Puzzle","r":"December 12, 2003","l":"https://en.wikipedia.org/wiki/Zuma_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sym.jpg","s":"Survive the ancient temples of Zuma, the critically acclaimed action-puzzler from PopCap! Deep in the jungle lie hidden temples bursting with traps and trickery, and it's up to you to uncover their treasures. Fire magical balls from your stone frog idol to make matches of three or more and clear the deadly chain before it reaches the golden skull."}];
